window.KHO_DATA_L2_TIENGANH = [
{"lop":2,"mon":"Tiếng Anh","tuan":1,"tiet":1,"bai":"Unit 1: At my birthday party – Lesson 1 (Activities 1–2)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Vocabulary: pasta, pizza, popcorn\n- Phonics: recognise the letter P, p and say the sound /p/ in the new words\n2. Skills: Listening and speaking\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Health education: Recognise some foods commonly served at parties; build healthy eating habits and avoid wasting food.\n4. Digital Competence (AI 2.A1): Recognise that AI can support listening to and pronouncing English vocabulary through a text-to-speech tool. The teacher lets pupils listen to model pronunciations of the words pasta, pizza, popcorn and identify the word that matches each picture.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 1: At my birthday party), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a friendly atmosphere and lead in to the new unit.\n* Procedure:\n- T greets the class, introduces himself/herself and asks Ss to say hello and their names: Hello. I’m …\n- T and Ss sing a familiar Grade 1 English song together.\n- T shows the Pupil’s Book, then the opening picture of Unit 1: At my birthday party and asks: What can you see?\n- T introduces the unit title and the aims of the lesson.","hs":"- Ss greet T and say their names.\n- Ss sing along.\n- Ss look at the book and the picture and answer.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 1: Listen and repeat","gv":"* Aims: Ss will be able to recognise and say the words pasta, pizza, popcorn and the letter-sound P, p /p/.\n* Procedure:\n- T uses flashcards/pictures to introduce the new words:\n+ pasta: mì Ý (picture)\n+ pizza: bánh pi-za (picture)\n+ popcorn: bỏng ngô (picture)\n- T models each word three times; Ss repeat in chorus, in groups and individually.\n- T sticks the flashcards on the board and writes the words under them.\n- T introduces the letter P, p and the sound /p/ at the beginning of the words; T says the sound slowly and asks Ss to watch T’s mouth.\n- T plays the recording of Activity 1 and pauses after each word for Ss to repeat. T plays it again.\n- T corrects Ss’ pronunciation where necessary.\n- Checking: “What and where” – T rubs out the words one by one; Ss say the words and their places.\n- (AI 2.A1) T types the words pasta, pizza, popcorn into a text-to-speech tool on the class computer (prepared and checked in advance; Ss use no accounts) and plays them in random order. Ss listen, point to the matching picture and repeat; then they practise the sound /p/.\n- T explains simply: “This voice is made by a computer (AI). It helps us listen, but we always check with the teacher and the book.”","hs":"- Ss look at the flashcards and listen.\n- Ss repeat in chorus, in groups and individually.\n- Ss look at the board.\n- Ss watch, listen and say the sound /p/ and the words.\n- Ss listen to the recording and repeat.\n- Ss correct their pronunciation.\n- Ss play “What and where”.\n- Ss listen to the computer voice, point to the matching picture and repeat the words and the sound /p/ (AI 2.A1).\n- Ss listen to T."},{"ten":"3. Practice (12’) – Activity 2: Point and say","gv":"* Aims: Ss will be able to point at the pictures and say the words correctly.\n* Procedure:\n- T draws Ss’ attention to the pictures in Activity 2.\n- T points at each picture and says the word; Ss repeat.\n- T points at the pictures in random order; Ss say the words.\n- T puts Ss into pairs: one pupil points at a picture, the other says the word; then they swap roles.\n- T goes around the classroom to offer support.\n- T invites some pairs to point and say in front of the class; T praises and corrects them.","hs":"- Ss look at the pictures.\n- Ss listen and repeat.\n- Ss say the words.\n- Ss work in pairs to point and say.\n- Ss ask T for help when needed.\n- Some pairs perform; the class listens and claps."},{"ten":"4. Production (6’) – Game: Clap for the sound","gv":"* Aims: Ss will be able to recognise the sound /p/ in words.\n* Procedure:\n- T says the new words and some known words (ball, bag, cat) in random order.\n- Ss clap once when they hear the sound /p/ and stay quiet for the other words.\n- T shows the flashcards quickly (“Flash cards”); Ss say the words.\n- (Health education) T asks: “Do you like pizza/popcorn?” and reminds Ss to eat healthy food at parties and not to waste food.","hs":"- Ss listen carefully.\n- Ss clap when they hear the sound /p/.\n- Ss say the words on the flashcards.\n- Ss answer and listen to T’s advice."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What have we learnt today?” and points at the flashcards for Ss to say the words and the sound /p/.\n- Homework: Practise saying the words at home; prepare Lesson 2 (Activities 3–5).","hs":"- Ss answer and say the words and the sound.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":1,"tiet":2,"bai":"Unit 1: At my birthday party – Lesson 2 (Activities 3–5)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say the chant of Unit 1: At my birthday party with the sound /p/\n- Listen and tick the correct pictures (pasta, pizza, popcorn)\n- Look at the pictures and write the missing letter(s) to complete the words\n2. Skills: Listening and speaking; reading and writing (Activity 5: Look and write)\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Ethics: Share food, wait for their turn and behave politely at birthday parties.\n4. Digital Competence (1.1.CB1a, 4.2.CB1a): Perform simple information-selection actions on digital learning resources under the teacher's guidance. Pupils listen to the audio, look at the pictures of pasta / pizza / popcorn and choose or tick the matching picture. Begin to recognise personal information that needs to be protected when using digital devices. The teacher reminds pupils not to post photos, dates of birth, birthday party locations or family information online without permission.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 1: At my birthday party), TV or projector, computer.\n- Pupils: Pupil’s Book, notebooks, pencils, colour pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Lesson 1 and lead in to the lesson.\n* Procedure:\n- T greets the class.\n- T plays “What’s missing?” with the flashcards pasta, pizza, popcorn: T hides one card; Ss say the missing word.\n- T asks Ss to say the letter P, p and the sound /p/.\n- T introduces Lesson 2.","hs":"- Ss greet T.\n- Ss play the game and say the missing word.\n- Ss say the letter and the sound.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 3: Listen and chant","gv":"* Aims: Ss will be able to say the chant with the correct sound /p/ and rhythm.\n* Procedure:\n- T draws Ss’ attention to the chant and the pictures in Activity 3.\n- T plays the recording all the way through; Ss listen and follow in their books.\n- T plays it again line by line; Ss repeat.\n- T models clapping the rhythm; Ss chant and clap along.\n- T divides the class into groups to take turns chanting.\n- T invites some groups to chant in front of the class and praises them.","hs":"- Ss look at the chant.\n- Ss listen and follow.\n- Ss repeat line by line.\n- Ss chant and clap.\n- Ss chant in groups.\n- Some groups perform; the class claps."},{"ten":"3. Practice (10’) – Activity 4: Listen and tick","gv":"* Aims: Ss will be able to listen and tick the correct pictures.\n* Procedure:\n- T draws Ss’ attention to the pictures and asks Ss to name the things in each picture.\n- T explains the task and does the example with the class.\n- T plays the recording; Ss listen and tick. T plays it again for Ss to check.\n- T asks Ss to swap books and check in pairs.\n- T checks the answers as a class (key: Teacher’s Book) and plays the recording again, pausing for Ss to repeat.\n- (Digital competence 1.1.CB1a) T shows the Activity 4 pictures on the TV/projector (digital book opened by T). T plays each item again; one pupil comes up and clicks/taps the picture they chose under T’s guidance; the class says “Yes” or “No”.","hs":"- Ss look at the pictures and name the things.\n- Ss follow the example.\n- Ss listen and tick, then listen again and check.\n- Ss swap books and check in pairs.\n- Ss check the answers and repeat.\n- Ss take turns to choose the matching picture on the screen; the class checks (Digital competence 1.1.CB1a)."},{"ten":"4. Production (8’) – Activity 5: Look and write","gv":"* Aims: Ss will be able to look at the pictures and write the missing letter(s) to complete the words.\n* Procedure:\n- T draws Ss’ attention to the pictures and the incomplete words.\n- T models the first one on the board, e.g. “_asta” → “pasta”; Ss read the word in chorus.\n- Ss do the task individually; T goes around to help with letter formation.\n- T invites some Ss to write the answers on the board; the class checks and reads the words aloud.\n- (Ethics) T asks: “At a birthday party, what do you do?” and elicits: share food, wait for your turn and say “Thank you”.","hs":"- Ss look at the pictures and the words.\n- Ss watch and read the word in chorus.\n- Ss write the missing letter(s) in their books.\n- Some Ss write on the board; the class checks and reads aloud.\n- Ss answer and share their ideas."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the chant once more and spell the letter P, p.\n- (Digital competence 4.2.CB1a) T shows a birthday party photo and reminds Ss not to post photos, their date of birth, the party place or family information online without their parents’ permission.\n- Homework: Practise the chant and the words at home; prepare Lesson 3 (Activities 6–8).","hs":"- Ss say the chant.\n- Ss listen and say what information they keep private (Digital competence 4.2.CB1a).\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":2,"tiet":1,"bai":"Unit 1: At my birthday party – Lesson 3 (Activities 6–8)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Sentence pattern: The ___ is yummy.\n- e.g. The pizza is yummy. / The popcorn is yummy. / The pasta is yummy.\n- Use the pattern to talk about the pictures and sing the song of Unit 1: At my birthday party\n2. Skills: Listening and speaking\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Culture and communication education: Use positive words when commenting on food and show a cheerful, polite attitude at birthday parties.\n4. Digital Competence (AI 2.A2, 2.1.CB1a): Recognise that AI can support speaking practice and give pronunciation feedback on simple English sentence patterns. Under the teacher's guidance, pupils say “The popcorn is yummy.” / “The pizza is yummy.” / “The pasta is yummy.” and listen to the pronunciation support tool read the model sentences back. Take part in simple digital communication activities in a learning environment guided by the teacher. Pupils listen to the song, look at the pictures and practise the sentence patterns with the class.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 1: At my birthday party), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and the chant and lead in to the lesson.\n* Procedure:\n- T greets the class and asks Ss to say the chant of Lesson 2.\n- T shows the flashcards pasta, pizza, popcorn; Ss say the words.\n- T introduces Lesson 3.","hs":"- Ss greet T and say the chant.\n- Ss say the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 6: Listen and repeat","gv":"* Aims: Ss will be able to understand and say the sentence pattern: The ___ is yummy.\n* Procedure:\n- T shows the pictures in Activity 6 and sets the context: “Look! Who’s this? What can you see?”\n- T introduces the sentence pattern and writes it on the board:\n+ The ___ is yummy.\n+ e.g. The pizza is yummy.\n- T models the sentences; Ss repeat in chorus, in groups and individually.\n- T plays the recording; Ss listen and repeat sentence by sentence. T plays it again.\n- (AI 2.A2) T opens a pronunciation tool on the class computer (teacher’s account only). The tool reads the model sentences: The pizza is yummy. / The popcorn is yummy. / The pasta is yummy. Ss listen and repeat.\n- Two or three volunteers say one sentence into the microphone; the tool reads back what it heard and the class compares it with the model. T gives feedback on pronunciation and reminds Ss that the teacher always checks the tool.","hs":"- Ss look at the pictures and answer.\n- Ss look at the board and listen.\n- Ss repeat in chorus, in groups and individually.\n- Ss listen to the recording and repeat.\n- Ss listen to the tool and repeat the sentences (AI 2.A2).\n- Some Ss say a sentence into the microphone and compare it with the model; the class listens."},{"ten":"3. Practice (10’) – Activity 7: Let’s talk","gv":"* Aims: Ss will be able to use the sentence pattern to talk about the pictures.\n* Procedure:\n- T points at the pictures in Activity 7 and elicits the words.\n- T points at a picture and says the sentence (The pizza is yummy.); Ss repeat.\n- T points at the other pictures; the whole class, then groups, say the sentences.\n- T puts Ss into pairs: S1 points at a picture, S2 says the sentence; then they swap.\n- T goes around to offer support and invites some pairs to perform in front of the class.\n- (Culture and communication education) T encourages Ss to use positive words (Yummy! Thank you!) and to smile when they comment on food.","hs":"- Ss look and say the words.\n- Ss listen and repeat.\n- Ss say the sentences in chorus and in groups.\n- Ss practise in pairs.\n- Some pairs perform; the class listens and gives comments.\n- Ss use positive words and smile when they talk."},{"ten":"4. Production (8’) – Activity 8: Let’s sing","gv":"* Aims: Ss will be able to sing the song of Unit 1: At my birthday party with the correct pronunciation and actions.\n* Procedure:\n- T draws Ss’ attention to the song and the pictures; T reads the lyrics line by line for Ss to repeat.\n- T plays the recording all the way through; Ss listen.\n- T plays it again; Ss sing along line by line.\n- T shows simple actions; Ss sing and do the actions.\n- T invites some groups to sing in front of the class and praises them.\n- (Digital competence 2.1.CB1a) T plays the song with pictures on the TV; after singing, T pauses on each picture and the class says the sentence (The pizza is yummy.).","hs":"- Ss look at the song and repeat the lyrics.\n- Ss listen to the song.\n- Ss sing along line by line.\n- Ss sing and do the actions.\n- Some groups perform; the class claps.\n- Ss watch the screen, sing and say the sentence for each picture (Digital competence 2.1.CB1a)."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T shows a picture and asks Ss to say the sentence pattern once more.\n- Homework: Practise the sentences and the song at home; prepare the next unit.","hs":"- Ss say the sentence.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":2,"tiet":2,"bai":"Unit 2: In the backyard – Lesson 1 (Activities 1–2)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Vocabulary: kite, bike, kitten\n- Phonics: recognise the letter K, k and say the sound /k/ in the new words\n2. Skills: Listening and speaking\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Road safety: Teach pupils to wear helmets and ride bicycles in safe areas with adult supervision.\n- Animal care education: Play gently with pets such as kittens, take care of them and do not tease them.\n4. Digital Competence (AI 2.A1): Recognise that AI can support listening to and pronouncing English vocabulary. The teacher lets pupils listen to model pronunciations of the words kite, bike, kitten; pupils listen, point to the pictures and repeat.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 2: In the backyard), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a friendly atmosphere and lead in to the new unit.\n* Procedure:\n- T greets the class and asks Ss to sing a song they have learnt.\n- T plays “Slap the board” with the flashcards of Unit 1: At my birthday party (pasta, pizza, popcorn).\n- T shows the opening picture of Unit 2: In the backyard and asks: What can you see?\n- T introduces the unit title and the aims of the lesson.","hs":"- Ss greet T and sing the song.\n- Ss play the game in two teams.\n- Ss look at the picture and answer.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 1: Listen and repeat","gv":"* Aims: Ss will be able to recognise and say the words kite, bike, kitten and the letter-sound K, k /k/.\n* Procedure:\n- T uses flashcards/pictures to introduce the new words:\n+ kite: cái diều (picture)\n+ bike: xe đạp (picture)\n+ kitten: mèo con (picture)\n- T models each word three times; Ss repeat in chorus, in groups and individually.\n- T sticks the flashcards on the board and writes the words under them.\n- T introduces the letter K, k and the sound /k/ (at the beginning of kite, kitten and at the end of bike); T says the sound slowly and asks Ss to watch T’s mouth.\n- T plays the recording of Activity 1 and pauses after each word for Ss to repeat. T plays it again.\n- T corrects Ss’ pronunciation where necessary.\n- Checking: “What and where” – T rubs out the words one by one; Ss say the words and their places.\n- (AI 2.A1) T types the words kite, bike, kitten into a text-to-speech tool on the class computer (prepared and checked in advance; Ss use no accounts) and plays them in random order. Ss listen, point to the matching picture and repeat; then they practise the sound /k/.\n- T explains simply: “This voice is made by a computer (AI). It helps us listen, but we always check with the teacher and the book.”","hs":"- Ss look at the flashcards and listen.\n- Ss repeat in chorus, in groups and individually.\n- Ss look at the board.\n- Ss watch, listen and say the sound /k/ and the words.\n- Ss listen to the recording and repeat.\n- Ss correct their pronunciation.\n- Ss play “What and where”.\n- Ss listen to the computer voice, point to the matching picture and repeat the words and the sound /k/ (AI 2.A1).\n- Ss listen to T."},{"ten":"3. Practice (12’) – Activity 2: Point and say","gv":"* Aims: Ss will be able to point at the pictures and say the words correctly.\n* Procedure:\n- T draws Ss’ attention to the pictures in Activity 2.\n- T points at each picture and says the word; Ss repeat.\n- T points at the pictures in random order; Ss say the words.\n- T puts Ss into pairs: one pupil points at a picture, the other says the word; then they swap roles.\n- T goes around the classroom to offer support.\n- T invites some pairs to point and say in front of the class; T praises and corrects them.","hs":"- Ss look at the pictures.\n- Ss listen and repeat.\n- Ss say the words.\n- Ss work in pairs to point and say.\n- Ss ask T for help when needed.\n- Some pairs perform; the class listens and claps."},{"ten":"4. Production (6’) – Game: Clap for the sound","gv":"* Aims: Ss will be able to recognise the sound /k/ in words.\n* Procedure:\n- T says the new words and some known words (ball, bag, fish) in random order.\n- Ss clap once when they hear the sound /k/ and stay quiet for the other words.\n- T shows the flashcards quickly (“Flash cards”); Ss say the words.\n- (Road safety) T points at the bike picture and asks: “What do you wear when you ride a bike?” – a helmet; ride in safe places with an adult.\n- (Animal care education) T points at the kitten and reminds Ss to play gently with pets and never tease them.","hs":"- Ss listen carefully.\n- Ss clap when they hear the sound /k/.\n- Ss say the words on the flashcards.\n- Ss answer and listen.\n- Ss say how they play gently with pets."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What have we learnt today?” and points at the flashcards for Ss to say the words and the sound /k/.\n- Homework: Practise saying the words at home; prepare Lesson 2 (Activities 3–5).","hs":"- Ss answer and say the words and the sound.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":3,"tiet":1,"bai":"Unit 2: In the backyard – Lesson 2 (Activities 3–5)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say the chant of Unit 2: In the backyard with the sound /k/\n- Listen and circle the correct pictures (kite, bike, kitten)\n- Understand the key language: He’s flying a kite. / He’s riding a bike. / She’s playing with a kitten.\n- Look at the pictures and write the missing letter(s) to complete the words\n2. Skills: Listening and speaking; reading and writing (Activity 5: Look and write)\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n4. Digital Competence (1.1.CB1a, AI 2.A2, 4.1.CB1a): Perform simple information-selection actions on digital learning resources under the teacher's guidance. Pupils listen to the sentence, look at the two pictures and choose/circle the matching one. Recognise that AI tools can create or read model sentences from pictures. The teacher has pupils compare the sentence read by AI with the picture to decide on the correct content. Begin to build habits of using digital devices safely: sit properly, keep a suitable distance from the screen and follow the teacher's instructions.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 2: In the backyard), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils, colour pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Lesson 1 and lead in to the lesson.\n* Procedure:\n- T greets the class.\n- T plays “What’s missing?” with the flashcards kite, bike, kitten: T hides one card; Ss say the missing word.\n- T asks Ss to say the letter K, k and the sound /k/.\n- T introduces Lesson 2.","hs":"- Ss greet T.\n- Ss play the game and say the missing word.\n- Ss say the letter and the sound.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 3: Listen and chant","gv":"* Aims: Ss will be able to say the chant with the correct sound /k/ and rhythm.\n* Procedure:\n- T draws Ss’ attention to the chant and the pictures in Activity 3.\n- T plays the recording all the way through; Ss listen and follow in their books.\n- T plays it again line by line; Ss repeat.\n- T models clapping the rhythm; Ss chant and clap along.\n- T divides the class into groups to take turns chanting.\n- T invites some groups to chant in front of the class and praises them.","hs":"- Ss look at the chant.\n- Ss listen and follow.\n- Ss repeat line by line.\n- Ss chant and clap.\n- Ss chant in groups.\n- Some groups perform; the class claps."},{"ten":"3. Practice (10’) – Activity 4: Listen and circle","gv":"* Aims: Ss will be able to listen and circle the correct pictures.\n* Procedure:\n- T draws Ss’ attention to the pictures and asks Ss to name the things in each picture.\n- T revises the key language with the pictures:\n+ He’s flying a kite.\n+ He’s riding a bike.\n+ She’s playing with a kitten.\n- T explains the task and does the example with the class.\n- T plays the recording; Ss listen and circle. T plays it again for Ss to check.\n- T asks Ss to swap books and check in pairs.\n- T checks the answers as a class (key: Teacher’s Book) and plays the recording again, pausing for Ss to repeat.\n- (Digital competence 4.1.CB1a) Before Ss come to the screen, T reminds them to sit properly, keep a suitable distance from the screen and only touch/click when T says so.\n- (Digital competence 1.1.CB1a) T shows the Activity 4 pictures on the TV/projector (digital book opened by T). T plays each sentence again; one pupil comes up and clicks/taps the picture they chose under T’s guidance; the class says “Yes” or “No”.","hs":"- Ss look at the pictures and name the things.\n- Ss listen and repeat the key sentences.\n- Ss follow the example.\n- Ss listen and circle, then listen again and check.\n- Ss swap books and check in pairs.\n- Ss check the answers and repeat.\n- Ss sit properly, keep a suitable distance from the screen and follow T’s instructions (Digital competence 4.1.CB1a).\n- Ss take turns to choose the matching picture on the screen; the class checks (Digital competence 1.1.CB1a)."},{"ten":"4. Production (8’) – Activity 5: Look and write","gv":"* Aims: Ss will be able to look at the pictures and write the missing letter(s) to complete the words.\n* Procedure:\n- T draws Ss’ attention to the pictures and the incomplete words.\n- T models the first one on the board, e.g. “_ite” → “kite”; Ss read the word in chorus.\n- Ss do the task individually; T goes around to help with letter formation.\n- T invites some Ss to write the answers on the board; the class checks and reads the words aloud.\n- (AI 2.A2) Before the writing task, T plays three sentences read by an AI voice (prepared and checked in advance): He’s flying a kite. / He’s riding a bike. / She’s playing with a kitten. For each one T shows a picture; one picture does not match. Ss say “Yes” or “No” and correct the wrong one.","hs":"- Ss look at the pictures and the words.\n- Ss watch and read the word in chorus.\n- Ss write the missing letter(s) in their books.\n- Some Ss write on the board; the class checks and reads aloud.\n- Ss listen to the AI voice, compare it with the picture and say “Yes” or “No” (AI 2.A2)."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the chant once more and spell the letter K, k.\n- Homework: Practise the chant and the words at home; prepare Lesson 3 (Activities 6–8).","hs":"- Ss say the chant.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":3,"tiet":2,"bai":"Unit 2: In the backyard – Lesson 3 (Activities 6–8)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Sentence patterns: Is he/she flying a kite? Yes, he/she is. / No, he/she isn’t.\n- e.g. Is she flying a kite? – Yes, she is. / Is he flying a kite? – No, he isn’t.\n- Use the pattern to talk about the pictures and sing the song of Unit 2: In the backyard\n2. Skills: Listening and speaking\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Life skills: Encourage safe outdoor activity, sharing toys and waiting for one's turn when playing with friends.\n4. Digital Competence (AI 2.A2, 2.1.CB1a): Recognise that AI can support speaking and pronunciation practice of simple question–answer patterns. Under the teacher's guidance, pupils listen to the model Is he/she …? – Yes, he/she is. / No, he/she isn’t. and then practise speaking with the pictures. Take part in simple digital communication activities in a learning environment guided by the teacher: listen to questions, choose pictures and answer in turns.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 2: In the backyard), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and the chant and lead in to the lesson.\n* Procedure:\n- T greets the class and asks Ss to say the chant of Lesson 2.\n- T shows the flashcards kite, bike, kitten; Ss say the words.\n- T introduces Lesson 3.","hs":"- Ss greet T and say the chant.\n- Ss say the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 6: Listen and repeat","gv":"* Aims: Ss will be able to understand and say the sentence patterns: Is he/she flying a kite? Yes, he/she is. / No, he/she isn’t.\n* Procedure:\n- T shows the pictures in Activity 6 and sets the context: “Look! Who’s this? What can you see?”\n- T introduces the sentence pattern and writes it on the board:\n+ Is he/she flying a kite?\n+ Yes, he/she is. / No, he/she isn’t.\n+ e.g. Is she flying a kite? – Yes, she is.\n- T models the sentences; Ss repeat in chorus, in groups and individually.\n- T plays the recording; Ss listen and repeat sentence by sentence. T plays it again.\n- T reminds Ss of the rising intonation in Yes/No questions and the falling intonation in answers.\n- (AI 2.A2) T opens a pronunciation tool on the class computer (teacher’s account only). The tool reads the model sentences: Is she flying a kite? – Yes, she is. / Is he flying a kite? – No, he isn’t. Ss listen and repeat.\n- Two or three volunteers say one sentence into the microphone; the tool reads back what it heard and the class compares it with the model. T gives feedback on pronunciation and reminds Ss that the teacher always checks the tool.","hs":"- Ss look at the pictures and answer.\n- Ss look at the board and listen.\n- Ss repeat in chorus, in groups and individually.\n- Ss listen to the recording and repeat.\n- Ss repeat with the correct intonation.\n- Ss listen to the tool and repeat the sentences (AI 2.A2).\n- Some Ss say a sentence into the microphone and compare it with the model; the class listens."},{"ten":"3. Practice (10’) – Activity 7: Let’s talk","gv":"* Aims: Ss will be able to use the sentence pattern to talk about the pictures.\n* Procedure:\n- T points at the pictures in Activity 7 and elicits the words.\n- T models with a good pupil: T asks, the pupil answers (Is she flying a kite? – Yes, she is.).\n- Half the class asks and the other half answers; then they swap roles.\n- T puts Ss into pairs: S1 points at a picture and asks, S2 answers; then they swap.\n- T goes around to offer support and invites some pairs to perform in front of the class.\n- (Digital competence 2.1.CB1a) T shows the Activity 7 pictures on the TV and plays a recorded question/model for each picture (Is he riding a bike? / Is she playing with a kitten?). Ss look, choose the right picture and answer in turns.","hs":"- Ss look and say the words.\n- Ss watch the model.\n- Ss practise in two halves.\n- Ss practise in pairs.\n- Some pairs perform; the class listens and gives comments.\n- Ss listen to the recorded question, choose the picture and answer in turns (Digital competence 2.1.CB1a)."},{"ten":"4. Production (8’) – Activity 8: Let’s sing","gv":"* Aims: Ss will be able to sing the song of Unit 2: In the backyard with the correct pronunciation and actions.\n* Procedure:\n- T draws Ss’ attention to the song and the pictures; T reads the lyrics line by line for Ss to repeat.\n- T plays the recording all the way through; Ss listen.\n- T plays it again; Ss sing along line by line.\n- T shows simple actions; Ss sing and do the actions.\n- T invites some groups to sing in front of the class and praises them.","hs":"- Ss look at the song and repeat the lyrics.\n- Ss listen to the song.\n- Ss sing along line by line.\n- Ss sing and do the actions.\n- Some groups perform; the class claps."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T shows a picture and asks Ss to say the sentence pattern once more.\n- (Life skills) T encourages Ss to play outdoors safely, share their toys (kites, bikes) and wait for their turn.\n- Homework: Practise the sentences and the song at home; prepare Fun time.","hs":"- Ss say the sentence.\n- Ss listen and say how they share toys.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":4,"tiet":1,"bai":"Fun time 1 – Lesson 1","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Revise the words, letter-sounds and sentence patterns of Units 1–2:\n- Unit 1: At my birthday party – words: pasta, pizza, popcorn – letter and sound: P, p /p/ – pattern: The ___ is yummy.\n- Unit 2: In the backyard – words: kite, bike, kitten – letter and sound: K, k /k/ – pattern: Is he/she flying a kite? Yes, he/she is. / No, he/she isn’t.\n2. Skills: Listening and speaking\n3. Attributes:\n- Cooperate with classmates in games and group work and be confident when speaking English.\n- Character education: Cooperate, play honestly and respect friends.\n4. Digital Competence (AI 2.A2, 2.4.CB1a): The teacher may use AI voices/images checked in advance to create a fun challenge; pupils compare them with the pictures, words and sentence patterns they have learnt, and do not treat AI output as the default answer. Take part in simple digital games/learning resources in groups; wait for their turn, choose answers and respond politely.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Units 1–2), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a cheerful atmosphere and lead in to Fun time.\n* Procedure:\n- T greets the class and asks Ss to sing the song of Unit 2: In the backyard.\n- T introduces Fun time: “Today we play and revise Unit 1: At my birthday party and Unit 2: In the backyard.”","hs":"- Ss greet T and sing the song.\n- Ss listen and open their books."},{"ten":"2. Revision of words and sounds (10’)","gv":"* Aims: Ss will be able to revise the words and letter-sounds of Units 1–2.\n* Procedure:\n- T shows the flashcards quickly (pasta, pizza, popcorn, kite, bike, kitten); Ss say the words.\n- T writes the letters P, p and K, k on the board; Ss come up, stick each flashcard under the correct letter and say the sound (/p/ or /k/).\n- Game “Slap the board”: two teams; T says a word, one pupil from each team slaps the correct picture.","hs":"- Ss say the words.\n- Ss sort the flashcards under the letters and say the sounds.\n- Ss play the game in two teams."},{"ten":"3. Fun time activities (12’)","gv":"* Aims: Ss will be able to use the words and sentence patterns of Units 1–2 in games.\n* Procedure:\n- T draws Ss’ attention to the Fun time page in the Pupil’s Book and explains the activities.\n- T models the first activity with the class; Ss do the activities in pairs or groups.\n- T goes around to offer support and checks the answers as a class.\n- (Digital competence 2.4.CB1a) T runs a simple slide game on the projector (“Guess the picture”: a picture is hidden behind squares). Groups take turns to choose a square and say the word or sentence; groups wait for their turn and respond politely.\n- (AI 2.A2) T shows two AI images/voices prepared and checked in advance (e.g. a kite picture with a voice saying “bike”). Ss compare them with the words and pictures they have learnt and say whether they are right; T reminds Ss that AI output is not always the answer.","hs":"- Ss look at the Fun time page and listen.\n- Ss watch the model and do the activities in pairs or groups.\n- Ss check the answers.\n- Ss play the game in groups, wait for their turn and cheer politely (Digital competence 2.4.CB1a).\n- Ss compare the AI picture/voice with what they have learnt and say “Right” or “Wrong” (AI 2.A2)."},{"ten":"4. Production (6’) – Game: Pass the ball","gv":"* Aims: Ss will be able to say the words and sentences of Units 1–2 confidently.\n* Procedure:\n- T plays music; Ss pass a ball around. When the music stops, the pupil with the ball looks at the flashcard T shows and says a word or a sentence (e.g. The pizza is yummy. / Is she flying a kite? – Yes, she is.).\n- T praises correct answers and helps Ss who need support.\n- (Character education) T reminds Ss to cooperate, play honestly and respect their friends.","hs":"- Ss pass the ball and say a word or a sentence when the music stops.\n- Ss listen and cheer their friends.\n- Ss play fairly and respect their friends."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss which game they liked best and which words they remember.\n- Homework: Revise the words, sounds and sentences of Units 1–2; prepare Fun time Lesson 2.","hs":"- Ss answer.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":4,"tiet":2,"bai":"Fun time 1 – Lesson 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Revise the words, letter-sounds and sentence patterns of Units 1–2:\n- Unit 1: At my birthday party – words: pasta, pizza, popcorn – letter and sound: P, p /p/ – pattern: The ___ is yummy.\n- Unit 2: In the backyard – words: kite, bike, kitten – letter and sound: K, k /k/ – pattern: Is he/she flying a kite? Yes, he/she is. / No, he/she isn’t.\n2. Skills: Listening and speaking; writing (missing letters of known words)\n3. Attributes:\n- Cooperate with classmates in games and group work and be confident when speaking English.\n- Digital safety education: No personal account is needed; do not enter private information.\n4. Digital Competence (1.2.CB1a, AI 2.A1): Observe, listen to and select simple information on teacher-controlled digital learning resources; check again when an answer does not match the picture/audio. Recognise that AI can generate voices or suggest answers but is sometimes wrong; pupils need to ask the teacher/check the textbook before correcting their work.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Units 1–2), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils, colour pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the chants and lead in to the lesson.\n* Procedure:\n- T greets the class and asks Ss to say the chants of Unit 1: At my birthday party and Unit 2: In the backyard with clapping.\n- T introduces the lesson.","hs":"- Ss greet T and say the chants.\n- Ss listen and open their books."},{"ten":"2. Sentence patterns (10’)","gv":"* Aims: Ss will be able to revise the sentence patterns of Units 1–2.\n* Procedure:\n- T shows the pictures and elicits the patterns; T writes them on the board:\n+ The ___ is yummy.\n+ Is he/she flying a kite?\n+ Yes, he/she is. / No, he/she isn’t.\n- T–Ss, then half class – half class practise with the pictures.\n- Ss practise in pairs with the pictures in the Pupil’s Book.","hs":"- Ss look at the pictures and say the patterns.\n- Ss practise with T and in two halves.\n- Ss practise in pairs."},{"ten":"3. Practice (12’) – Fun time activities","gv":"* Aims: Ss will be able to consolidate the words, letters and sentence patterns through the Fun time activities.\n* Procedure:\n- T explains the Fun time activities in the Pupil’s Book and does an example with the class.\n- Ss do the activities individually or in pairs; T goes around to offer support.\n- Look and write: T shows the pictures of the six words; Ss write the missing letters (_asta, _ite …) in their notebooks.\n- T checks the answers as a class.\n- (Digital competence 1.2.CB1a) T opens a listening exercise on the digital resource (teacher-controlled). The computer plays a word or sentence; Ss look and choose the picture; if the answer does not match the picture/audio, Ss listen and check again.\n- (AI 2.A1) T shows an AI-suggested answer prepared by T with one mistake (e.g. “The kitten is yummy.” for a pizza picture). Ss check it with the Pupil’s Book and ask T before correcting it.","hs":"- Ss listen and follow the example.\n- Ss do the activities.\n- Ss write the missing letters in their notebooks.\n- Ss check the answers.\n- Ss listen, choose the picture and check again when it does not match (Digital competence 1.2.CB1a).\n- Ss find the mistake in the AI answer, check with the book and correct it with T (AI 2.A1)."},{"ten":"4. Production (6’) – Mini talks","gv":"* Aims: Ss will be able to use the patterns in short exchanges.\n* Procedure:\n- T gives each pair two flashcards; pairs make a short exchange with a pattern from Unit 1 or Unit 2.\n- T invites some pairs to perform and gives feedback.","hs":"- Ss work in pairs and make short exchanges.\n- Some pairs perform; the class listens."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say one word and one sentence they remember from Units 1–2.\n- (Digital safety education) T reminds Ss: we do not need a personal account to play these games; never type your name, address or phone number into apps or games.\n- Homework: Revise Units 1–2; prepare the next unit.","hs":"- Ss say a word and a sentence.\n- Ss listen and repeat the rule.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":5,"tiet":1,"bai":"Unit 3: At the seaside – Lesson 1 (Activities 1–2)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Vocabulary: sea, sail, sand\n- Phonics: recognise the letter S, s and say the sound /s/ in the new words\n2. Skills: Listening and speaking\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Safety education: Play at the seaside only with adults; wear a helmet and ride bicycles only in safe areas with adult supervision.\n4. Digital Competence (AI 2.A1): Recognise that AI can support listening to and pronouncing English vocabulary through a text-to-speech tool. The teacher has pupils listen to and identify the words sea, sail, sand; pupils point to the matching pictures and practise the /s/ sound.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 3: At the seaside), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a friendly atmosphere and lead in to the new unit.\n* Procedure:\n- T greets the class and asks Ss to sing a song they have learnt.\n- T plays “Slap the board” with the flashcards of Unit 1: At my birthday party and Unit 2: In the backyard (pasta, pizza, popcorn, kite, bike, kitten).\n- T shows the opening picture of Unit 3: At the seaside and asks: What can you see?\n- T introduces the unit title and the aims of the lesson.","hs":"- Ss greet T and sing the song.\n- Ss play the game in two teams.\n- Ss look at the picture and answer.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 1: Listen and repeat","gv":"* Aims: Ss will be able to recognise and say the words sea, sail, sand and the letter-sound S, s /s/.\n* Procedure:\n- T uses flashcards/pictures to introduce the new words:\n+ sea: biển (picture)\n+ sail: cánh buồm (picture)\n+ sand: cát (picture)\n- T models each word three times; Ss repeat in chorus, in groups and individually.\n- T sticks the flashcards on the board and writes the words under them.\n- T introduces the letter S, s and the sound /s/ at the beginning of the words; T says the sound slowly and asks Ss to watch T’s mouth.\n- T plays the recording of Activity 1 and pauses after each word for Ss to repeat. T plays it again.\n- T corrects Ss’ pronunciation where necessary.\n- Checking: “What and where” – T rubs out the words one by one; Ss say the words and their places.\n- (AI 2.A1) T types the words sea, sail, sand into a text-to-speech tool on the class computer (prepared and checked in advance; Ss use no accounts) and plays them in random order. Ss listen, point to the matching picture and repeat; then they practise the sound /s/.\n- T explains simply: “This voice is made by a computer (AI). It helps us listen, but we always check with the teacher and the book.”","hs":"- Ss look at the flashcards and listen.\n- Ss repeat in chorus, in groups and individually.\n- Ss look at the board.\n- Ss watch, listen and say the sound /s/ and the words.\n- Ss listen to the recording and repeat.\n- Ss correct their pronunciation.\n- Ss play “What and where”.\n- Ss listen to the computer voice, point to the matching picture and repeat the words and the sound /s/ (AI 2.A1).\n- Ss listen to T."},{"ten":"3. Practice (12’) – Activity 2: Point and say","gv":"* Aims: Ss will be able to point at the pictures and say the words correctly.\n* Procedure:\n- T draws Ss’ attention to the pictures in Activity 2.\n- T points at each picture and says the word; Ss repeat.\n- T points at the pictures in random order; Ss say the words.\n- T puts Ss into pairs: one pupil points at a picture, the other says the word; then they swap roles.\n- T goes around the classroom to offer support.\n- T invites some pairs to point and say in front of the class; T praises and corrects them.","hs":"- Ss look at the pictures.\n- Ss listen and repeat.\n- Ss say the words.\n- Ss work in pairs to point and say.\n- Ss ask T for help when needed.\n- Some pairs perform; the class listens and claps."},{"ten":"4. Production (6’) – Game: Clap for the sound","gv":"* Aims: Ss will be able to recognise the sound /s/ in words.\n* Procedure:\n- T says the new words and some known words (ball, bag, pen) in random order.\n- Ss clap once when they hear the sound /s/ and stay quiet for the other words.\n- T shows the flashcards quickly (“Flash cards”); Ss say the words.\n- (Safety education) T asks: “Who do you go to the sea with?” and reminds Ss to play at the seaside only with adults and to wear a helmet when they ride a bike.","hs":"- Ss listen carefully.\n- Ss clap when they hear the sound /s/.\n- Ss say the words on the flashcards.\n- Ss answer and listen to T."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What have we learnt today?” and points at the flashcards for Ss to say the words and the sound /s/.\n- Homework: Practise saying the words at home; prepare Lesson 2 (Activities 3–5).","hs":"- Ss answer and say the words and the sound.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":5,"tiet":2,"bai":"Unit 3: At the seaside – Lesson 2 (Activities 3–5)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say the chant of Unit 3: At the seaside with the sound /s/\n- Listen and circle the correct pictures (sea, sail, sand)\n- Look at the pictures and write the missing letter(s) to complete the words\n2. Skills: Listening and speaking; reading and writing (Activity 5: Look and write)\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Animal care education: Play gently with pets; do not tease or hurt animals.\n4. Digital Competence (1.1.CB1a, 4.1.CB1a): Perform simple information-selection actions on digital learning resources under the teacher's guidance. Pupils listen, look at the pictures and choose/circle the correct answer in the pictures of sea, sail and sand. Begin to build habits of using digital devices safely: sit properly, keep a suitable distance from the screen and only operate the device when the teacher gives instructions.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 3: At the seaside), TV or projector, computer.\n- Pupils: Pupil’s Book, notebooks, pencils, colour pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Lesson 1 and lead in to the lesson.\n* Procedure:\n- T greets the class.\n- T plays “What’s missing?” with the flashcards sea, sail, sand: T hides one card; Ss say the missing word.\n- T asks Ss to say the letter S, s and the sound /s/.\n- T introduces Lesson 2.","hs":"- Ss greet T.\n- Ss play the game and say the missing word.\n- Ss say the letter and the sound.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 3: Listen and chant","gv":"* Aims: Ss will be able to say the chant with the correct sound /s/ and rhythm.\n* Procedure:\n- T draws Ss’ attention to the chant and the pictures in Activity 3.\n- T plays the recording all the way through; Ss listen and follow in their books.\n- T plays it again line by line; Ss repeat.\n- T models clapping the rhythm; Ss chant and clap along.\n- T divides the class into groups to take turns chanting.\n- T invites some groups to chant in front of the class and praises them.","hs":"- Ss look at the chant.\n- Ss listen and follow.\n- Ss repeat line by line.\n- Ss chant and clap.\n- Ss chant in groups.\n- Some groups perform; the class claps."},{"ten":"3. Practice (10’) – Activity 4: Listen and circle","gv":"* Aims: Ss will be able to listen and circle the correct pictures.\n* Procedure:\n- T draws Ss’ attention to the pictures and asks Ss to name the things in each picture.\n- T explains the task and does the example with the class.\n- T plays the recording; Ss listen and circle. T plays it again for Ss to check.\n- T asks Ss to swap books and check in pairs.\n- T checks the answers as a class (key: Teacher’s Book) and plays the recording again, pausing for Ss to repeat.\n- (Digital competence 4.1.CB1a) Before Ss come to the screen, T reminds them to sit properly, keep a suitable distance from the screen and only touch/click when T says so; only operate the device when T gives instructions.\n- (Digital competence 1.1.CB1a) T shows the Activity 4 pictures on the TV/projector (digital book opened by T). T plays each item again; one pupil comes up and clicks/taps the picture they chose under T’s guidance; the class says “Yes” or “No”.","hs":"- Ss look at the pictures and name the things.\n- Ss follow the example.\n- Ss listen and circle, then listen again and check.\n- Ss swap books and check in pairs.\n- Ss check the answers and repeat.\n- Ss sit properly, keep a suitable distance from the screen and follow T’s instructions (Digital competence 4.1.CB1a).\n- Ss take turns to choose the matching picture on the screen; the class checks (Digital competence 1.1.CB1a)."},{"ten":"4. Production (8’) – Activity 5: Look and write","gv":"* Aims: Ss will be able to look at the pictures and write the missing letter(s) to complete the words.\n* Procedure:\n- T draws Ss’ attention to the pictures and the incomplete words.\n- T models the first one on the board, e.g. “_ea” → “sea”; Ss read the word in chorus.\n- Ss do the task individually; T goes around to help with letter formation.\n- T invites some Ss to write the answers on the board; the class checks and reads the words aloud.","hs":"- Ss look at the pictures and the words.\n- Ss watch and read the word in chorus.\n- Ss write the missing letter(s) in their books.\n- Some Ss write on the board; the class checks and reads aloud."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the chant once more and spell the letter S, s.\n- (Animal care education) T shows a picture of crabs and fish at the seaside and reminds Ss to play gently with animals and never tease or hurt them.\n- Homework: Practise the chant and the words at home; prepare Lesson 3 (Activities 6–8).","hs":"- Ss say the chant.\n- Ss listen and say how they are kind to animals.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":6,"tiet":1,"bai":"Unit 3: At the seaside – Lesson 3 (Activities 6–8)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Sentence pattern: Let’s look at the ___!\n- e.g. Let’s look at the sea! / Let’s look at the sail! / Let’s look at the sand!\n- Use the pattern to talk about the pictures and sing the song of Unit 3: At the seaside\n2. Skills: Listening and speaking\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Environmental education: Develop awareness of keeping beaches clean, not littering and protecting natural landscapes.\n4. Digital Competence (AI 2.A2, 2.1.CB1a): Recognise that AI can support speaking practice and give pronunciation feedback on simple English sentence patterns. Under the teacher's guidance, pupils listen to the models and practise saying: “Let’s look at the sea!” / “Let’s look at the sail!” / “Let’s look at the sand!”. Take part in simple digital communication activities in a guided learning environment: listen to models, look at the pictures and choose suitable words to complete the sentence “Let’s ____!”.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 3: At the seaside), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and the chant and lead in to the lesson.\n* Procedure:\n- T greets the class and asks Ss to say the chant of Lesson 2.\n- T shows the flashcards sea, sail, sand; Ss say the words.\n- T introduces Lesson 3.","hs":"- Ss greet T and say the chant.\n- Ss say the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 6: Listen and repeat","gv":"* Aims: Ss will be able to understand and say the sentence pattern: Let’s look at the ___!\n* Procedure:\n- T shows the pictures in Activity 6 and sets the context: “Look! Who’s this? What can you see?”\n- T introduces the sentence pattern and writes it on the board:\n+ Let’s look at the ___!\n+ e.g. Let’s look at the sea!\n- T models the sentences; Ss repeat in chorus, in groups and individually.\n- T plays the recording; Ss listen and repeat sentence by sentence. T plays it again.\n- (AI 2.A2) T opens a pronunciation tool on the class computer (teacher’s account only). The tool reads the model sentences: Let’s look at the sea! / Let’s look at the sail! / Let’s look at the sand! Ss listen and repeat.\n- Two or three volunteers say one sentence into the microphone; the tool reads back what it heard and the class compares it with the model. T gives feedback on pronunciation and reminds Ss that the teacher always checks the tool.","hs":"- Ss look at the pictures and answer.\n- Ss look at the board and listen.\n- Ss repeat in chorus, in groups and individually.\n- Ss listen to the recording and repeat.\n- Ss listen to the tool and repeat the sentences (AI 2.A2).\n- Some Ss say a sentence into the microphone and compare it with the model; the class listens."},{"ten":"3. Practice (10’) – Activity 7: Let’s talk","gv":"* Aims: Ss will be able to use the sentence pattern to talk about the pictures.\n* Procedure:\n- T points at the pictures in Activity 7 and elicits the words.\n- T points at a picture and says the sentence (Let’s look at the sea!); Ss repeat.\n- T points at the other pictures; the whole class, then groups, say the sentences.\n- T puts Ss into pairs: S1 points at a picture, S2 says the sentence; then they swap.\n- T goes around to offer support and invites some pairs to perform in front of the class.\n- (Digital competence 2.1.CB1a) T shows the Activity 7 pictures on the TV and plays the model “Let’s look at the ___!”; Ss look, choose the right word (sea, sail, sand) and complete the sentence in turns.","hs":"- Ss look and say the words.\n- Ss listen and repeat.\n- Ss say the sentences in chorus and in groups.\n- Ss practise in pairs.\n- Some pairs perform; the class listens and gives comments.\n- Ss listen, look at the screen and complete the sentence in turns (Digital competence 2.1.CB1a)."},{"ten":"4. Production (8’) – Activity 8: Let’s sing","gv":"* Aims: Ss will be able to sing the song of Unit 3: At the seaside with the correct pronunciation and actions.\n* Procedure:\n- T draws Ss’ attention to the song and the pictures; T reads the lyrics line by line for Ss to repeat.\n- T plays the recording all the way through; Ss listen.\n- T plays it again; Ss sing along line by line.\n- T shows simple actions; Ss sing and do the actions.\n- T invites some groups to sing in front of the class and praises them.","hs":"- Ss look at the song and repeat the lyrics.\n- Ss listen to the song.\n- Ss sing along line by line.\n- Ss sing and do the actions.\n- Some groups perform; the class claps."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T shows a picture and asks Ss to say the sentence pattern once more.\n- (Environmental education) T shows a clean beach and a dirty beach and asks: “Which one do you like?” T reminds Ss not to litter and to keep beaches clean.\n- Homework: Practise the sentences and the song at home; prepare the next unit.","hs":"- Ss say the sentence.\n- Ss answer and promise to keep beaches clean.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":6,"tiet":2,"bai":"Unit 4: In the countryside – Lesson 1 (Activities 1–2)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Vocabulary: road, river, rainbow\n- Phonics: recognise the letter R, r and say the sound /r/ in the new words\n2. Skills: Listening and speaking\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Road safety: Recognise roads in the countryside; remind pupils to walk on the correct part of the road, look carefully when crossing and wear a helmet when riding on a motorbike/e-bike.\n4. Digital Competence (AI 2.A1): Recognise that AI can support listening to and pronouncing English vocabulary through a text-to-speech tool. The teacher has pupils listen to and identify the words road, river, rainbow; pupils point to the correct pictures and practise the /r/ sound.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 4: In the countryside), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a friendly atmosphere and lead in to the new unit.\n* Procedure:\n- T greets the class and asks Ss to sing a song they have learnt.\n- T plays “Slap the board” with the flashcards of Unit 3: At the seaside (sea, sail, sand).\n- T shows the opening picture of Unit 4: In the countryside and asks: What can you see?\n- T introduces the unit title and the aims of the lesson.","hs":"- Ss greet T and sing the song.\n- Ss play the game in two teams.\n- Ss look at the picture and answer.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 1: Listen and repeat","gv":"* Aims: Ss will be able to recognise and say the words road, river, rainbow and the letter-sound R, r /r/.\n* Procedure:\n- T uses flashcards/pictures to introduce the new words:\n+ road: con đường (picture)\n+ river: dòng sông (picture)\n+ rainbow: cầu vồng (picture)\n- T models each word three times; Ss repeat in chorus, in groups and individually.\n- T sticks the flashcards on the board and writes the words under them.\n- T introduces the letter R, r and the sound /r/ at the beginning of the words; T says the sound slowly and asks Ss to watch T’s mouth.\n- T plays the recording of Activity 1 and pauses after each word for Ss to repeat. T plays it again.\n- T corrects Ss’ pronunciation where necessary.\n- Checking: “What and where” – T rubs out the words one by one; Ss say the words and their places.\n- (AI 2.A1) T types the words road, river, rainbow into a text-to-speech tool on the class computer (prepared and checked in advance; Ss use no accounts) and plays them in random order. Ss listen, point to the matching picture and repeat; then they practise the sound /r/.\n- T explains simply: “This voice is made by a computer (AI). It helps us listen, but we always check with the teacher and the book.”","hs":"- Ss look at the flashcards and listen.\n- Ss repeat in chorus, in groups and individually.\n- Ss look at the board.\n- Ss watch, listen and say the sound /r/ and the words.\n- Ss listen to the recording and repeat.\n- Ss correct their pronunciation.\n- Ss play “What and where”.\n- Ss listen to the computer voice, point to the matching picture and repeat the words and the sound /r/ (AI 2.A1).\n- Ss listen to T."},{"ten":"3. Practice (12’) – Activity 2: Point and say","gv":"* Aims: Ss will be able to point at the pictures and say the words correctly.\n* Procedure:\n- T draws Ss’ attention to the pictures in Activity 2.\n- T points at each picture and says the word; Ss repeat.\n- T points at the pictures in random order; Ss say the words.\n- T puts Ss into pairs: one pupil points at a picture, the other says the word; then they swap roles.\n- T goes around the classroom to offer support.\n- T invites some pairs to point and say in front of the class; T praises and corrects them.","hs":"- Ss look at the pictures.\n- Ss listen and repeat.\n- Ss say the words.\n- Ss work in pairs to point and say.\n- Ss ask T for help when needed.\n- Some pairs perform; the class listens and claps."},{"ten":"4. Production (6’) – Game: Clap for the sound","gv":"* Aims: Ss will be able to recognise the sound /r/ in words.\n* Procedure:\n- T says the new words and some known words (ball, bag, pen) in random order.\n- Ss clap once when they hear the sound /r/ and stay quiet for the other words.\n- T shows the flashcards quickly (“Flash cards”); Ss say the words.\n- (Road safety) T points at the road picture and reminds Ss to walk on the correct side of the road, look carefully when crossing and wear a helmet on a motorbike or e-bike.","hs":"- Ss listen carefully.\n- Ss clap when they hear the sound /r/.\n- Ss say the words on the flashcards.\n- Ss listen and repeat the safety rules."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What have we learnt today?” and points at the flashcards for Ss to say the words and the sound /r/.\n- Homework: Practise saying the words at home; prepare Lesson 2 (Activities 3–5).","hs":"- Ss answer and say the words and the sound.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":7,"tiet":1,"bai":"Unit 4: In the countryside – Lesson 2 (Activities 3–5)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say the chant of Unit 4: In the countryside with the sound /r/\n- Listen and circle the correct pictures (road, river, rainbow)\n- Look at the pictures and write the missing letter(s) to complete the words\n2. Skills: Listening and speaking; reading and writing (Activity 5: Look and write)\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Environmental protection: Be aware of keeping rivers and village roads clean; do not throw rubbish into rivers or public places.\n4. Digital Competence (1.1.CB1a, 4.1.CB1a): Perform simple information-selection actions on digital learning resources under the teacher's guidance. Pupils listen to sentences with the key words road / river / rainbow and then choose or circle the matching pictures. Begin to build habits of using digital devices safely: only touch/select as instructed, do not open unfamiliar content on their own and keep a suitable distance from the screen.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 4: In the countryside), TV or projector, computer.\n- Pupils: Pupil’s Book, notebooks, pencils, colour pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Lesson 1 and lead in to the lesson.\n* Procedure:\n- T greets the class.\n- T plays “What’s missing?” with the flashcards road, river, rainbow: T hides one card; Ss say the missing word.\n- T asks Ss to say the letter R, r and the sound /r/.\n- T introduces Lesson 2.","hs":"- Ss greet T.\n- Ss play the game and say the missing word.\n- Ss say the letter and the sound.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 3: Listen and chant","gv":"* Aims: Ss will be able to say the chant with the correct sound /r/ and rhythm.\n* Procedure:\n- T draws Ss’ attention to the chant and the pictures in Activity 3.\n- T plays the recording all the way through; Ss listen and follow in their books.\n- T plays it again line by line; Ss repeat.\n- T models clapping the rhythm; Ss chant and clap along.\n- T divides the class into groups to take turns chanting.\n- T invites some groups to chant in front of the class and praises them.","hs":"- Ss look at the chant.\n- Ss listen and follow.\n- Ss repeat line by line.\n- Ss chant and clap.\n- Ss chant in groups.\n- Some groups perform; the class claps."},{"ten":"3. Practice (10’) – Activity 4: Listen and circle","gv":"* Aims: Ss will be able to listen and circle the correct pictures.\n* Procedure:\n- T draws Ss’ attention to the pictures and asks Ss to name the things in each picture.\n- T explains the task and does the example with the class.\n- T plays the recording; Ss listen and circle. T plays it again for Ss to check.\n- T asks Ss to swap books and check in pairs.\n- T checks the answers as a class (key: Teacher’s Book) and plays the recording again, pausing for Ss to repeat.\n- (Digital competence 4.1.CB1a) Before Ss come to the screen, T reminds them to sit properly, keep a suitable distance from the screen and only touch/click when T says so; do not open unfamiliar content.\n- (Digital competence 1.1.CB1a) T shows the Activity 4 pictures on the TV/projector (digital book opened by T). T plays each sentence with the key words road, river, rainbow again; one pupil comes up and clicks/taps the picture they chose under T’s guidance; the class says “Yes” or “No”.","hs":"- Ss look at the pictures and name the things.\n- Ss follow the example.\n- Ss listen and circle, then listen again and check.\n- Ss swap books and check in pairs.\n- Ss check the answers and repeat.\n- Ss sit properly, keep a suitable distance from the screen and follow T’s instructions (Digital competence 4.1.CB1a).\n- Ss take turns to choose the matching picture on the screen; the class checks (Digital competence 1.1.CB1a)."},{"ten":"4. Production (8’) – Activity 5: Look and write","gv":"* Aims: Ss will be able to look at the pictures and write the missing letter(s) to complete the words.\n* Procedure:\n- T draws Ss’ attention to the pictures and the incomplete words.\n- T models the first one on the board, e.g. “_oad” → “road”; Ss read the word in chorus.\n- Ss do the task individually; T goes around to help with letter formation.\n- T invites some Ss to write the answers on the board; the class checks and reads the words aloud.","hs":"- Ss look at the pictures and the words.\n- Ss watch and read the word in chorus.\n- Ss write the missing letter(s) in their books.\n- Some Ss write on the board; the class checks and reads aloud."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the chant once more and spell the letter R, r.\n- (Environmental protection) T asks: “Can we throw rubbish into the river?” – No! T reminds Ss to keep rivers and village roads clean.\n- Homework: Practise the chant and the words at home; prepare Lesson 3 (Activities 6–8).","hs":"- Ss say the chant.\n- Ss answer and listen.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":7,"tiet":2,"bai":"Unit 4: In the countryside – Lesson 3 (Activities 6–8)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Sentence patterns: What can you see? I can see a ___.\n- e.g. What can you see? – I can see a rainbow. / What can you see? – I can see a river. / What can you see? – I can see a road.\n- Use the pattern to talk about the pictures and sing the song of Unit 4: In the countryside\n2. Skills: Listening and speaking\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Local education – Environmental education: Recognise the beauty of the rural landscape of the homeland; help keep village roads, rivers and the landscape green, clean and beautiful.\n4. Digital Competence (AI 2.A2, 2.1.CB1a): Recognise that AI can support speaking practice and pronunciation checking of simple English sentence patterns. Under the teacher's guidance, pupils practise asking and answering: “What can you see?” – “I can see a rainbow/river/road.” The teacher may use a model-reading tool so that pupils listen, repeat and adjust their own pronunciation. Take part in simple digital communication activities in a guided learning environment: listen to questions, look at the pictures and choose suitable answers.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 4: In the countryside), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and the chant and lead in to the lesson.\n* Procedure:\n- T greets the class and asks Ss to say the chant of Lesson 2.\n- T shows the flashcards road, river, rainbow; Ss say the words.\n- T introduces Lesson 3.","hs":"- Ss greet T and say the chant.\n- Ss say the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 6: Listen and repeat","gv":"* Aims: Ss will be able to understand and say the sentence patterns: What can you see? I can see a ___.\n* Procedure:\n- T shows the pictures in Activity 6 and sets the context: “Look! Who’s this? What can you see?”\n- T introduces the sentence pattern and writes it on the board:\n+ What can you see?\n+ I can see a ___.\n+ e.g. What can you see? – I can see a rainbow.\n- T models the sentences; Ss repeat in chorus, in groups and individually.\n- T plays the recording; Ss listen and repeat sentence by sentence. T plays it again.\n- T reminds Ss of the falling intonation in Wh-questions.\n- (AI 2.A2) T opens a pronunciation tool on the class computer (teacher’s account only). The tool reads the model sentences: What can you see? – I can see a rainbow. / What can you see? – I can see a river. / What can you see? – I can see a road. Ss listen and repeat.\n- Two or three volunteers say one sentence into the microphone; the tool reads back what it heard and the class compares it with the model. T gives feedback on pronunciation and reminds Ss that the teacher always checks the tool.","hs":"- Ss look at the pictures and answer.\n- Ss look at the board and listen.\n- Ss repeat in chorus, in groups and individually.\n- Ss listen to the recording and repeat.\n- Ss repeat with the correct intonation.\n- Ss listen to the tool and repeat the sentences (AI 2.A2).\n- Some Ss say a sentence into the microphone and compare it with the model; the class listens."},{"ten":"3. Practice (10’) – Activity 7: Let’s talk","gv":"* Aims: Ss will be able to use the sentence pattern to talk about the pictures.\n* Procedure:\n- T points at the pictures in Activity 7 and elicits the words.\n- T models with a good pupil: T asks, the pupil answers (What can you see? – I can see a rainbow.).\n- Half the class asks and the other half answers; then they swap roles.\n- T puts Ss into pairs: S1 points at a picture and asks, S2 answers; then they swap.\n- T goes around to offer support and invites some pairs to perform in front of the class.\n- (Digital competence 2.1.CB1a) T shows the Activity 7 pictures on the TV and plays a recorded question/model for each picture (What can you see? – I can see a …). Ss look, choose the right picture and answer in turns.","hs":"- Ss look and say the words.\n- Ss watch the model.\n- Ss practise in two halves.\n- Ss practise in pairs.\n- Some pairs perform; the class listens and gives comments.\n- Ss listen to the recorded question, choose the picture and answer in turns (Digital competence 2.1.CB1a)."},{"ten":"4. Production (8’) – Activity 8: Let’s sing","gv":"* Aims: Ss will be able to sing the song of Unit 4: In the countryside with the correct pronunciation and actions.\n* Procedure:\n- T draws Ss’ attention to the song and the pictures; T reads the lyrics line by line for Ss to repeat.\n- T plays the recording all the way through; Ss listen.\n- T plays it again; Ss sing along line by line.\n- T shows simple actions; Ss sing and do the actions.\n- T invites some groups to sing in front of the class and praises them.","hs":"- Ss look at the song and repeat the lyrics.\n- Ss listen to the song.\n- Ss sing along line by line.\n- Ss sing and do the actions.\n- Some groups perform; the class claps."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T shows a picture and asks Ss to say the sentence pattern once more.\n- (Local education – Environmental education) T shows a photo of the local countryside and asks: “What can you see?” T helps Ss admire its beauty and keep village roads and rivers green, clean and beautiful.\n- Homework: Practise the sentences and the song at home; prepare the Review.","hs":"- Ss say the sentence.\n- Ss look, say what they can see and share how to keep their village clean.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":8,"tiet":1,"bai":"Review 1 – Phil and Sue","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Listen to and understand the Phil and Sue story in Review 1\n- Revise the words, letter-sounds and sentence patterns of Units 1–4:\n- Unit 1: At my birthday party – words: pasta, pizza, popcorn – letter and sound: P, p /p/ – pattern: The ___ is yummy.\n- Unit 2: In the backyard – words: kite, bike, kitten – letter and sound: K, k /k/ – pattern: Is he/she flying a kite? Yes, he/she is. / No, he/she isn’t.\n- Unit 3: At the seaside – words: sea, sail, sand – letter and sound: S, s /s/ – pattern: Let’s look at the ___!\n- Unit 4: In the countryside – words: road, river, rainbow – letter and sound: R, r /r/ – pattern: What can you see? I can see a ___.\n2. Skills: Listening and speaking\n3. Attributes:\n- Cooperate with classmates in games and group work and be confident when speaking English.\n- Character education: Be honest when stating what they have heard/read.\n4. Digital Competence (AI 2.B1, 1.2.CB1a): Recognise that an AI-style answer/illustration may not match the story; pupils check it against the pictures and the textbook content. Find simple information in the story/digital learning resources to confirm answers.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Units 1–4), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a cheerful atmosphere and revise the words.\n* Procedure:\n- T greets the class and asks Ss to sing a song from Units 1–4.\n- T shows the flashcards of Units 1–4 quickly; Ss say the words.","hs":"- Ss greet T and sing the song.\n- Ss say the words."},{"ten":"2. Before the story (7’)","gv":"* Aims: Ss will be able to predict the story and revise key words.\n* Procedure:\n- T shows the story pictures in Review 1 and asks: “Who are they? What can you see?”\n- T introduces the two characters, Phil and Sue.\n- T asks Ss to find in the pictures the things they know from Units 1–4.","hs":"- Ss look at the pictures and answer.\n- Ss listen and say the names Phil and Sue.\n- Ss point at the things they know and say the words."},{"ten":"3. Listen to the story (13’)","gv":"* Aims: Ss will be able to listen to and understand the Phil and Sue story.\n* Procedure:\n- T plays the recording all the way through; Ss listen and point at the pictures.\n- T plays it again, pausing after each line for Ss to repeat.\n- T asks simple questions about each picture: “Who is this? What can you see?”\n- T puts Ss into groups to read/act out the story with the pictures.\n- (Digital competence 1.2.CB1a) T shows the story pictures on the TV; Ss find simple information (who, what they see) to confirm their answers.\n- (AI 2.B1) T shows an AI-style picture/sentence prepared by T that does not match the story (e.g. wrong object). Ss check it with the pictures and the text in the Pupil’s Book and say what is wrong.","hs":"- Ss listen and point at the pictures.\n- Ss listen and repeat line by line.\n- Ss answer the questions.\n- Ss read/act out the story in groups.\n- Ss look at the screen and find information to confirm their answers (Digital competence 1.2.CB1a).\n- Ss compare the AI-style picture/sentence with the book and say what is wrong (AI 2.B1)."},{"ten":"4. Sounds and sentence patterns (8’)","gv":"* Aims: Ss will be able to revise the letter-sounds and sentence patterns of Units 1–4.\n* Procedure:\n- T writes the letters on the board: P, p /p/, K, k /k/, S, s /s/, R, r /r/; Ss say the sounds and a word for each letter.\n- T shows the pictures; Ss say the patterns in pairs:\n+ The pizza is yummy.\n+ Is she flying a kite? – Yes, she is.\n+ Let’s look at the sea!\n+ What can you see? – I can see a rainbow.","hs":"- Ss say the sounds and a word for each letter.\n- Ss practise the patterns in pairs."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “Do you like the story? What do Phil and Sue see?”\n- (Character education) T praises Ss who say honestly what they heard/read, even when they are not sure.\n- Homework: Retell the story to your family; prepare Self-check.","hs":"- Ss answer.\n- Ss say honestly what they heard/read.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":8,"tiet":2,"bai":"Review 1 – Self – check – Part 1","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Self-check (Review 1): listen and choose/tick, read and match/complete with the content of Units 1–4\n2. Skills: Listening and speaking; reading\n3. Attributes:\n- Cooperate with classmates in games and group work and be confident when speaking English.\n- Self-study education: Mark the content they have done well and the content that needs more practice.\n4. Digital Competence (1.1.CB1a, AI 2.A2): Listen, choose and check answers on digital learning resources under the teacher's guidance. Compare a simple AI suggestion with the answer based on the picture/audio and correct it if it is wrong.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Units 1–4), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils, colour pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a relaxed atmosphere before the Self-check.\n* Procedure:\n- T greets the class; Ss sing a song from Units 1–4.\n- T explains the Self-check: “Do your best and see what you can do.”","hs":"- Ss greet T and sing.\n- Ss listen."},{"ten":"2. Listening (12’)","gv":"* Aims: Ss will be able to listen and choose/tick the correct answers.\n* Procedure:\n- T draws Ss’ attention to the listening task(s) in the Self-check of Review 1 and asks Ss to name the pictures.\n- T explains the task and does the example.\n- T plays the recording twice; Ss listen and tick/choose.\n- T plays it once more for Ss to check.","hs":"- Ss look at the pictures and name them.\n- Ss follow the example.\n- Ss listen and do the task.\n- Ss listen again and check."},{"ten":"3. Reading (10’)","gv":"* Aims: Ss will be able to read and match/complete with the words and sentences they have learnt.\n* Procedure:\n- T reads the words/sentences in the reading task with Ss.\n- Ss do the task individually; T goes around and helps Ss who need support.\n- Ss swap books and check in pairs.","hs":"- Ss read the words/sentences with T.\n- Ss do the task individually.\n- Ss check in pairs."},{"ten":"4. Checking and feedback (6’)","gv":"* Aims: Ss will be able to check their answers and know what to practise more.\n* Procedure:\n- T checks the answers as a class (key: Teacher’s Book).\n- (Digital competence 1.1.CB1a) T opens the listening task on the digital resource; Ss listen, choose and check the answers on the screen under T’s guidance.\n- (AI 2.A2) T shows a simple AI suggestion for one item (prepared by T, with a mistake). Ss compare it with the picture/audio and correct it.\n- (Self-study education) Ss put a star next to the items they did well and a circle next to the items they need to practise more.","hs":"- Ss check their answers.\n- Ss listen, choose and check the answers on the screen (Digital competence 1.1.CB1a).\n- Ss compare the AI suggestion with the picture/audio and correct it (AI 2.A2).\n- Ss mark the items they did well and the items to practise more."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T praises the class and reminds Ss what to practise at home.\n- Homework: Practise the words and sentences you found difficult; prepare Self-check Part 2.","hs":"- Ss listen.\n- Ss remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":9,"tiet":1,"bai":"Review 1 – Self – check – Part 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Self-check (Review 1): read and write the words and short sentences, and speak with the sentence patterns of Units 1–4\n- Recognise what they can do well and what they need to practise more\n2. Skills: Speaking, reading and writing\n3. Attributes:\n- Cooperate with classmates in games and group work and be confident when speaking English.\n- Honesty education: Complete the Self-check section independently.\n4. Digital Competence (5.2.CB1a, AI 2.B1): Choose suitable simple tools for revision (audio, digital flashcards, digital games provided by the teacher). Do not copy AI answers; pupils do the task themselves first, then use AI examples to check under the teacher's guidance.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Units 1–4), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils, colour pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and lead in to the lesson.\n* Procedure:\n- T greets the class and shows the flashcards of Units 1–4 quickly; Ss say the words.\n- (Digital competence 5.2.CB1a) T offers three simple revision tools: the audio, digital flashcards, a digital picture game. The class chooses one and uses it for two minutes to revise the words.","hs":"- Ss greet T and say the words.\n- Ss choose a revision tool and use it with T to revise the words (Digital competence 5.2.CB1a)."},{"ten":"2. Reading and writing (12’)","gv":"* Aims: Ss will be able to read and write the words and short sentences they have learnt.\n* Procedure:\n- T draws Ss’ attention to the reading and writing tasks in the Self-check of Review 1 and does the example.\n- Ss look at the pictures and write the missing letters/words individually.\n- T goes around to help with spelling and letter formation.\n- T invites some Ss to write the answers on the board; the class checks.","hs":"- Ss look and follow the example.\n- Ss write the missing letters/words.\n- Ss ask T for help when needed.\n- Some Ss write on the board; the class checks."},{"ten":"3. Speaking (10’)","gv":"* Aims: Ss will be able to use the sentence patterns in short speaking tasks.\n* Procedure:\n- T shows the pictures and revises the patterns:\n+ The pizza is yummy.\n+ Is she flying a kite? – Yes, she is.\n+ Let’s look at the sea!\n+ What can you see? – I can see a rainbow.\n- Ss practise in pairs with the pictures.\n- T calls some pairs to speak and notes who needs more practice.","hs":"- Ss look and say the patterns.\n- Ss practise in pairs.\n- Some pairs speak in front of the class."},{"ten":"4. Self-assessment (6’)","gv":"* Aims: Ss will be able to recognise what they can do well and what they need to practise more.\n* Procedure:\n- T shows the “I can …” statements (say the words, say the sounds, talk with the patterns, write the missing letters).\n- Ss colour a smiley face for each statement in their notebooks.\n- (AI 2.B1) After Ss finish the Self-check on their own, T shows an AI example answer on the screen; Ss use it only to check, not to copy, under T’s guidance.\n- (Honesty education) T reminds Ss to complete the Self-check independently and mark their faces honestly.","hs":"- Ss read the statements with T.\n- Ss colour the faces honestly.\n- Ss finish first, then check with the AI example under T’s guidance (AI 2.B1).\n- Ss work independently and honestly."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T praises the class and reminds each group what to practise more.\n- Homework: Practise the content you marked “need more practice”.","hs":"- Ss listen.\n- Ss remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":9,"tiet":2,"bai":"Unit 5: In the classroom – Lesson 1 (Activities 1–2)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Vocabulary: question, square, quiz\n- Phonics: recognise the letter Q, q and say the sound /kw/ in the new words\n2. Skills: Listening and speaking\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Ethics - classroom routines: Raise their hands to answer, listen to the teacher and classmates, and wait for their turn in class activities.\n4. Digital Competence (AI 2.A1): Recognise that AI can support listening to and pronouncing English vocabulary through a text-to-speech tool. The teacher has pupils listen to and identify the words question, square, quiz; pupils point to the correct pictures and practise the initial sound of the letter Q, q.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 5: In the classroom), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a friendly atmosphere and lead in to the new unit.\n* Procedure:\n- T greets the class and asks Ss to sing a song they have learnt.\n- T plays “Slap the board” with the flashcards of Unit 4: In the countryside (road, river, rainbow).\n- T shows the opening picture of Unit 5: In the classroom and asks: What can you see?\n- T introduces the unit title and the aims of the lesson.","hs":"- Ss greet T and sing the song.\n- Ss play the game in two teams.\n- Ss look at the picture and answer.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 1: Listen and repeat","gv":"* Aims: Ss will be able to recognise and say the words question, square, quiz and the letter-sound Q, q /kw/.\n* Procedure:\n- T uses flashcards/pictures to introduce the new words:\n+ question: câu hỏi (picture)\n+ square: hình vuông (picture)\n+ quiz: câu đố (picture)\n- T models each word three times; Ss repeat in chorus, in groups and individually.\n- T sticks the flashcards on the board and writes the words under them.\n- T introduces the letter Q, q and the sound /kw/ (q + u says /kw/); T says the sound slowly and asks Ss to watch T’s mouth.\n- T plays the recording of Activity 1 and pauses after each word for Ss to repeat. T plays it again.\n- T corrects Ss’ pronunciation where necessary.\n- Checking: “What and where” – T rubs out the words one by one; Ss say the words and their places.\n- (AI 2.A1) T types the words question, square, quiz into a text-to-speech tool on the class computer (prepared and checked in advance; Ss use no accounts) and plays them in random order. Ss listen, point to the matching picture and repeat; then they practise the sound /kw/.\n- T explains simply: “This voice is made by a computer (AI). It helps us listen, but we always check with the teacher and the book.”","hs":"- Ss look at the flashcards and listen.\n- Ss repeat in chorus, in groups and individually.\n- Ss look at the board.\n- Ss watch, listen and say the sound /kw/ and the words.\n- Ss listen to the recording and repeat.\n- Ss correct their pronunciation.\n- Ss play “What and where”.\n- Ss listen to the computer voice, point to the matching picture and repeat the words and the sound /kw/ (AI 2.A1).\n- Ss listen to T."},{"ten":"3. Practice (12’) – Activity 2: Point and say","gv":"* Aims: Ss will be able to point at the pictures and say the words correctly.\n* Procedure:\n- T draws Ss’ attention to the pictures in Activity 2.\n- T points at each picture and says the word; Ss repeat.\n- T points at the pictures in random order; Ss say the words.\n- T puts Ss into pairs: one pupil points at a picture, the other says the word; then they swap roles.\n- T goes around the classroom to offer support.\n- T invites some pairs to point and say in front of the class; T praises and corrects them.\n- (Ethics – classroom routines) T reminds Ss to raise their hands to answer, listen to the teacher and classmates, and wait for their turn.","hs":"- Ss look at the pictures.\n- Ss listen and repeat.\n- Ss say the words.\n- Ss work in pairs to point and say.\n- Ss ask T for help when needed.\n- Some pairs perform; the class listens and claps.\n- Ss raise their hands and wait for their turn."},{"ten":"4. Production (6’) – Game: Clap for the sound","gv":"* Aims: Ss will be able to recognise the sound /kw/ in words.\n* Procedure:\n- T says the new words and some known words (ball, pen, sea) in random order.\n- Ss clap once when they hear the sound /kw/ and stay quiet for the other words.\n- T shows the flashcards quickly (“Flash cards”); Ss say the words.","hs":"- Ss listen carefully.\n- Ss clap when they hear the sound /kw/.\n- Ss say the words on the flashcards."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What have we learnt today?” and points at the flashcards for Ss to say the words and the sound /kw/.\n- Homework: Practise saying the words at home; prepare Lesson 2 (Activities 3–5).","hs":"- Ss answer and say the words and the sound.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":10,"tiet":1,"bai":"Unit 5: In the classroom – Lesson 2 (Activities 3–5)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say the chant of Unit 5: In the classroom with the sound /kw/\n- Listen and tick the correct pictures (question, square, quiz)\n- Look at the pictures and write the missing letter(s) to complete the words\n2. Skills: Listening and speaking; reading and writing (Activity 5: Look and write)\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Health protection: Sit properly, keep a suitable distance when looking at the screen/board and rest their eyes after digital activities.\n4. Digital Competence (1.1.CB1a, 4.1.CB1a): Perform simple information-selection actions on digital learning resources under the teacher's guidance. Pupils listen to sentences with the key words square / question / quiz and then choose or mark the matching pictures. Begin to build habits of using digital devices safely: only touch/select as instructed, do not open unfamiliar content on their own and keep a suitable distance from the screen.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 5: In the classroom), TV or projector, computer.\n- Pupils: Pupil’s Book, notebooks, pencils, colour pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Lesson 1 and lead in to the lesson.\n* Procedure:\n- T greets the class.\n- T plays “What’s missing?” with the flashcards question, square, quiz: T hides one card; Ss say the missing word.\n- T asks Ss to say the letter Q, q and the sound /kw/.\n- T introduces Lesson 2.","hs":"- Ss greet T.\n- Ss play the game and say the missing word.\n- Ss say the letter and the sound.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 3: Listen and chant","gv":"* Aims: Ss will be able to say the chant with the correct sound /kw/ and rhythm.\n* Procedure:\n- T draws Ss’ attention to the chant and the pictures in Activity 3.\n- T plays the recording all the way through; Ss listen and follow in their books.\n- T plays it again line by line; Ss repeat.\n- T models clapping the rhythm; Ss chant and clap along.\n- T divides the class into groups to take turns chanting.\n- T invites some groups to chant in front of the class and praises them.","hs":"- Ss look at the chant.\n- Ss listen and follow.\n- Ss repeat line by line.\n- Ss chant and clap.\n- Ss chant in groups.\n- Some groups perform; the class claps."},{"ten":"3. Practice (10’) – Activity 4: Listen and tick","gv":"* Aims: Ss will be able to listen and tick the correct pictures.\n* Procedure:\n- T draws Ss’ attention to the pictures and asks Ss to name the things in each picture.\n- T explains the task and does the example with the class.\n- T plays the recording; Ss listen and tick. T plays it again for Ss to check.\n- T asks Ss to swap books and check in pairs.\n- T checks the answers as a class (key: Teacher’s Book) and plays the recording again, pausing for Ss to repeat.\n- (Digital competence 4.1.CB1a) Before Ss come to the screen, T reminds them to sit properly, keep a suitable distance from the screen and only touch/click when T says so; do not open unfamiliar content.\n- (Digital competence 1.1.CB1a) T shows the Activity 4 pictures on the TV/projector (digital book opened by T). T plays each sentence with the key words square, question, quiz again; one pupil comes up and clicks/taps the picture they chose under T’s guidance; the class says “Yes” or “No”.","hs":"- Ss look at the pictures and name the things.\n- Ss follow the example.\n- Ss listen and tick, then listen again and check.\n- Ss swap books and check in pairs.\n- Ss check the answers and repeat.\n- Ss sit properly, keep a suitable distance from the screen and follow T’s instructions (Digital competence 4.1.CB1a).\n- Ss take turns to choose the matching picture on the screen; the class checks (Digital competence 1.1.CB1a)."},{"ten":"4. Production (8’) – Activity 5: Look and write","gv":"* Aims: Ss will be able to look at the pictures and write the missing letter(s) to complete the words.\n* Procedure:\n- T draws Ss’ attention to the pictures and the incomplete words.\n- T models the first one on the board, e.g. “__iz” → “quiz”; Ss read the word in chorus.\n- Ss do the task individually; T goes around to help with letter formation.\n- T invites some Ss to write the answers on the board; the class checks and reads the words aloud.","hs":"- Ss look at the pictures and the words.\n- Ss watch and read the word in chorus.\n- Ss write the missing letter(s) in their books.\n- Some Ss write on the board; the class checks and reads aloud."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the chant once more and spell the letter Q, q.\n- (Health protection) T reminds Ss to sit properly, keep a suitable distance from the screen/board and rest their eyes after the digital activity (look out of the window for a moment).\n- Homework: Practise the chant and the words at home; prepare Lesson 3 (Activities 6–8).","hs":"- Ss say the chant.\n- Ss sit properly and rest their eyes.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":10,"tiet":2,"bai":"Unit 5: In the classroom – Lesson 3 (Activities 6–8)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Sentence patterns: What’s she/he doing? She’s/He’s ___.\n- e.g. What’s she doing? – She’s colouring a square. / What’s he doing? – He’s doing a quiz.\n- Use the pattern to talk about the pictures and sing the song of Unit 5: In the classroom\n2. Skills: Listening and speaking\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Ethics: Develop honesty when doing quizzes, do not look at classmates' work and encourage friends in learning activities.\n4. Digital Competence (AI 2.A2, 2.1.CB1a): Recognise that AI can support speaking practice and pronunciation checking of simple English sentence patterns. Under the teacher's guidance, pupils practise asking and answering: “What’s she doing?” - “She’s colouring a square.”; “What’s he doing?” - “He’s doing a quiz.” The teacher may use a model-reading tool so that pupils listen, repeat and adjust their own pronunciation. Take part in simple digital communication activities in a guided learning environment: listen to questions, look at the pictures and choose/say suitable answers.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 5: In the classroom), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and the chant and lead in to the lesson.\n* Procedure:\n- T greets the class and asks Ss to say the chant of Lesson 2.\n- T shows the flashcards question, square, quiz; Ss say the words.\n- T introduces Lesson 3.","hs":"- Ss greet T and say the chant.\n- Ss say the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 6: Listen and repeat","gv":"* Aims: Ss will be able to understand and say the sentence patterns: What’s she/he doing? She’s/He’s ___.\n* Procedure:\n- T shows the pictures in Activity 6 and sets the context: “Look! Who’s this? What can you see?”\n- T introduces the sentence pattern and writes it on the board:\n+ What’s she/he doing?\n+ She’s/He’s ___.\n+ e.g. What’s she doing? – She’s colouring a square.\n- T models the sentences; Ss repeat in chorus, in groups and individually.\n- T plays the recording; Ss listen and repeat sentence by sentence. T plays it again.\n- T reminds Ss of the falling intonation in Wh-questions.\n- (AI 2.A2) T opens a pronunciation tool on the class computer (teacher’s account only). The tool reads the model sentences: What’s she doing? – She’s colouring a square. / What’s he doing? – He’s doing a quiz. Ss listen and repeat.\n- Two or three volunteers say one sentence into the microphone; the tool reads back what it heard and the class compares it with the model. T gives feedback on pronunciation and reminds Ss that the teacher always checks the tool.","hs":"- Ss look at the pictures and answer.\n- Ss look at the board and listen.\n- Ss repeat in chorus, in groups and individually.\n- Ss listen to the recording and repeat.\n- Ss repeat with the correct intonation.\n- Ss listen to the tool and repeat the sentences (AI 2.A2).\n- Some Ss say a sentence into the microphone and compare it with the model; the class listens."},{"ten":"3. Practice (10’) – Activity 7: Let’s talk","gv":"* Aims: Ss will be able to use the sentence pattern to talk about the pictures.\n* Procedure:\n- T points at the pictures in Activity 7 and elicits the words.\n- T models with a good pupil: T asks, the pupil answers (What’s she doing? – She’s colouring a square.).\n- Half the class asks and the other half answers; then they swap roles.\n- T puts Ss into pairs: S1 points at a picture and asks, S2 answers; then they swap.\n- T goes around to offer support and invites some pairs to perform in front of the class.\n- (Digital competence 2.1.CB1a) T shows the Activity 7 pictures on the TV and plays a recorded question/model for each picture (What’s she doing? / What’s he doing?). Ss look, choose the right picture and answer in turns.","hs":"- Ss look and say the words.\n- Ss watch the model.\n- Ss practise in two halves.\n- Ss practise in pairs.\n- Some pairs perform; the class listens and gives comments.\n- Ss listen to the recorded question, choose the picture and answer in turns (Digital competence 2.1.CB1a)."},{"ten":"4. Production (8’) – Activity 8: Let’s sing","gv":"* Aims: Ss will be able to sing the song of Unit 5: In the classroom with the correct pronunciation and actions.\n* Procedure:\n- T draws Ss’ attention to the song and the pictures; T reads the lyrics line by line for Ss to repeat.\n- T plays the recording all the way through; Ss listen.\n- T plays it again; Ss sing along line by line.\n- T shows simple actions; Ss sing and do the actions.\n- T invites some groups to sing in front of the class and praises them.","hs":"- Ss look at the song and repeat the lyrics.\n- Ss listen to the song.\n- Ss sing along line by line.\n- Ss sing and do the actions.\n- Some groups perform; the class claps."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T shows a picture and asks Ss to say the sentence pattern once more.\n- (Ethics) T asks: “When you do a quiz, do you look at your friend’s work?” – No! T encourages Ss to be honest and to cheer their friends on.\n- Homework: Practise the sentences and the song at home; prepare the next unit.","hs":"- Ss say the sentence.\n- Ss answer and promise to be honest.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":11,"tiet":1,"bai":"Unit 6: On the farm – Lesson 1 (Activities 1–2)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Vocabulary: box, fox, ox\n- Phonics: recognise the letter X, x and say the sound /ks/ in the new words\n2. Skills: Listening and speaking\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Experiential education - safety: Recognise some things and animals on a farm; do not go near or touch large farm animals on their own without adult guidance.\n4. Digital Competence (AI 2.A1): Recognise that AI can support listening to and pronouncing English vocabulary through a text-to-speech tool. The teacher has pupils listen to, identify and point to the correct pictures for the words box, fox, ox; pupils practise the letter X, x and the /ks/ sound at the end of words.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 6: On the farm), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a friendly atmosphere and lead in to the new unit.\n* Procedure:\n- T greets the class and asks Ss to sing a song they have learnt.\n- T plays “Slap the board” with the flashcards of Unit 5: In the classroom (question, square, quiz).\n- T shows the opening picture of Unit 6: On the farm and asks: What can you see?\n- T introduces the unit title and the aims of the lesson.","hs":"- Ss greet T and sing the song.\n- Ss play the game in two teams.\n- Ss look at the picture and answer.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 1: Listen and repeat","gv":"* Aims: Ss will be able to recognise and say the words box, fox, ox and the letter-sound X, x /ks/.\n* Procedure:\n- T uses flashcards/pictures to introduce the new words:\n+ box: cái hộp (picture)\n+ fox: con cáo (picture)\n+ ox: con bò đực (picture)\n- T models each word three times; Ss repeat in chorus, in groups and individually.\n- T sticks the flashcards on the board and writes the words under them.\n- T introduces the letter X, x and the sound /ks/ at the end of the words; T says the sound slowly and asks Ss to watch T’s mouth.\n- T plays the recording of Activity 1 and pauses after each word for Ss to repeat. T plays it again.\n- T corrects Ss’ pronunciation where necessary.\n- Checking: “What and where” – T rubs out the words one by one; Ss say the words and their places.\n- (AI 2.A1) T types the words box, fox, ox into a text-to-speech tool on the class computer (prepared and checked in advance; Ss use no accounts) and plays them in random order. Ss listen, point to the matching picture and repeat; then they practise the sound /ks/.\n- T explains simply: “This voice is made by a computer (AI). It helps us listen, but we always check with the teacher and the book.”","hs":"- Ss look at the flashcards and listen.\n- Ss repeat in chorus, in groups and individually.\n- Ss look at the board.\n- Ss watch, listen and say the sound /ks/ and the words.\n- Ss listen to the recording and repeat.\n- Ss correct their pronunciation.\n- Ss play “What and where”.\n- Ss listen to the computer voice, point to the matching picture and repeat the words and the sound /ks/ (AI 2.A1).\n- Ss listen to T."},{"ten":"3. Practice (12’) – Activity 2: Point and say","gv":"* Aims: Ss will be able to point at the pictures and say the words correctly.\n* Procedure:\n- T draws Ss’ attention to the pictures in Activity 2.\n- T points at each picture and says the word; Ss repeat.\n- T points at the pictures in random order; Ss say the words.\n- T puts Ss into pairs: one pupil points at a picture, the other says the word; then they swap roles.\n- T goes around the classroom to offer support.\n- T invites some pairs to point and say in front of the class; T praises and corrects them.","hs":"- Ss look at the pictures.\n- Ss listen and repeat.\n- Ss say the words.\n- Ss work in pairs to point and say.\n- Ss ask T for help when needed.\n- Some pairs perform; the class listens and claps."},{"ten":"4. Production (6’) – Game: Clap for the sound","gv":"* Aims: Ss will be able to recognise the sound /ks/ in words.\n* Procedure:\n- T says the new words and some known words (ball, pen, sea) in random order.\n- Ss clap once when they hear the sound /ks/ and stay quiet for the other words.\n- T shows the flashcards quickly (“Flash cards”); Ss say the words.\n- (Experiential education – safety) T shows a farm picture and reminds Ss not to go near or touch large farm animals such as an ox without an adult.","hs":"- Ss listen carefully.\n- Ss clap when they hear the sound /ks/.\n- Ss say the words on the flashcards.\n- Ss listen and repeat the rule."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What have we learnt today?” and points at the flashcards for Ss to say the words and the sound /ks/.\n- Homework: Practise saying the words at home; prepare Lesson 2 (Activities 3–5).","hs":"- Ss answer and say the words and the sound.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":11,"tiet":2,"bai":"Unit 6: On the farm – Lesson 2 (Activities 3–5)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say the chant of Unit 6: On the farm with the sound /ks/\n- Listen and circle the correct pictures (box, fox, ox)\n- Look at the pictures and write the missing letter(s) to complete the words\n2. Skills: Listening and speaking; reading and writing (Activity 5: Look and write)\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Environmental protection: Keep livestock areas clean, do not litter and be aware of protecting trees and animals.\n4. Digital Competence (1.1.CB1a, 4.1.CB1a): Perform simple information-selection actions on digital learning resources under the teacher's guidance. Pupils listen to the sentences “I can see a box/fox/ox on the farm.” and then choose or circle the matching pictures. Begin to build habits of using digital devices safely: only operate as instructed, do not open unfamiliar content on their own and stop using the device when the activity ends.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 6: On the farm), TV or projector, computer.\n- Pupils: Pupil’s Book, notebooks, pencils, colour pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Lesson 1 and lead in to the lesson.\n* Procedure:\n- T greets the class.\n- T plays “What’s missing?” with the flashcards box, fox, ox: T hides one card; Ss say the missing word.\n- T asks Ss to say the letter X, x and the sound /ks/.\n- T introduces Lesson 2.","hs":"- Ss greet T.\n- Ss play the game and say the missing word.\n- Ss say the letter and the sound.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 3: Listen and chant","gv":"* Aims: Ss will be able to say the chant with the correct sound /ks/ and rhythm.\n* Procedure:\n- T draws Ss’ attention to the chant and the pictures in Activity 3.\n- T plays the recording all the way through; Ss listen and follow in their books.\n- T plays it again line by line; Ss repeat.\n- T models clapping the rhythm; Ss chant and clap along.\n- T divides the class into groups to take turns chanting.\n- T invites some groups to chant in front of the class and praises them.","hs":"- Ss look at the chant.\n- Ss listen and follow.\n- Ss repeat line by line.\n- Ss chant and clap.\n- Ss chant in groups.\n- Some groups perform; the class claps."},{"ten":"3. Practice (10’) – Activity 4: Listen and circle","gv":"* Aims: Ss will be able to listen and circle the correct pictures.\n* Procedure:\n- T draws Ss’ attention to the pictures and asks Ss to name the things in each picture.\n- T explains the task and does the example with the class.\n- T plays the recording; Ss listen and circle. T plays it again for Ss to check.\n- T asks Ss to swap books and check in pairs.\n- T checks the answers as a class (key: Teacher’s Book) and plays the recording again, pausing for Ss to repeat.\n- (Digital competence 4.1.CB1a) Before Ss come to the screen, T reminds them to sit properly, keep a suitable distance from the screen and only touch/click when T says so; do not open unfamiliar content and stop using the device when the activity ends.\n- (Digital competence 1.1.CB1a) T shows the Activity 4 pictures on the TV/projector (digital book opened by T). T plays each sentence (I can see a box/fox/ox on the farm.) again; one pupil comes up and clicks/taps the picture they chose under T’s guidance; the class says “Yes” or “No”.","hs":"- Ss look at the pictures and name the things.\n- Ss follow the example.\n- Ss listen and circle, then listen again and check.\n- Ss swap books and check in pairs.\n- Ss check the answers and repeat.\n- Ss sit properly, keep a suitable distance from the screen and follow T’s instructions (Digital competence 4.1.CB1a).\n- Ss take turns to choose the matching picture on the screen; the class checks (Digital competence 1.1.CB1a)."},{"ten":"4. Production (8’) – Activity 5: Look and write","gv":"* Aims: Ss will be able to look at the pictures and write the missing letter(s) to complete the words.\n* Procedure:\n- T draws Ss’ attention to the pictures and the incomplete words.\n- T models the first one on the board, e.g. “bo_” → “box”; Ss read the word in chorus.\n- Ss do the task individually; T goes around to help with letter formation.\n- T invites some Ss to write the answers on the board; the class checks and reads the words aloud.","hs":"- Ss look at the pictures and the words.\n- Ss watch and read the word in chorus.\n- Ss write the missing letter(s) in their books.\n- Some Ss write on the board; the class checks and reads aloud."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the chant once more and spell the letter X, x.\n- (Environmental protection) T reminds Ss to keep farm areas clean, not to litter and to protect trees and animals.\n- Homework: Practise the chant and the words at home; prepare Lesson 3 (Activities 6–8).","hs":"- Ss say the chant.\n- Ss listen and share their ideas.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":12,"tiet":1,"bai":"Unit 6: On the farm – Lesson 3 (Activities 6–8)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Sentence patterns: Is there a/an ___? Yes, there is. / No, there isn’t.\n- e.g. Is there a fox? – Yes, there is. / Is there an ox? – No, there isn’t.\n- Use the pattern to talk about the pictures and sing the song of Unit 6: On the farm\n2. Skills: Listening and speaking\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Animal care education: Observe and care for pets properly; do not tease, chase or hurt animals.\n4. Digital Competence (AI 2.A2, 2.1.CB1a): Recognise that AI can support speaking practice and pronunciation checking of simple English sentence patterns. Under the teacher's guidance, pupils practise asking and answering: “Is there a fox?” - “Yes, there is.”; “Is there an ox?” - “No, there isn’t.” The teacher may use a model-reading tool so that pupils listen, repeat and adjust their own pronunciation. Take part in simple guided digital communication activities: listen to questions, look at the pictures and choose/say suitable answers.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 6: On the farm), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and the chant and lead in to the lesson.\n* Procedure:\n- T greets the class and asks Ss to say the chant of Lesson 2.\n- T shows the flashcards box, fox, ox; Ss say the words.\n- T introduces Lesson 3.","hs":"- Ss greet T and say the chant.\n- Ss say the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 6: Listen and repeat","gv":"* Aims: Ss will be able to understand and say the sentence patterns: Is there a/an ___? Yes, there is. / No, there isn’t.\n* Procedure:\n- T shows the pictures in Activity 6 and sets the context: “Look! Who’s this? What can you see?”\n- T introduces the sentence pattern and writes it on the board:\n+ Is there a/an ___?\n+ Yes, there is. / No, there isn’t.\n+ e.g. Is there a fox? – Yes, there is.\n- T models the sentences; Ss repeat in chorus, in groups and individually.\n- T plays the recording; Ss listen and repeat sentence by sentence. T plays it again.\n- T reminds Ss of the rising intonation in Yes/No questions and the falling intonation in answers.\n- (AI 2.A2) T opens a pronunciation tool on the class computer (teacher’s account only). The tool reads the model sentences: Is there a fox? – Yes, there is. / Is there an ox? – No, there isn’t. Ss listen and repeat.\n- Two or three volunteers say one sentence into the microphone; the tool reads back what it heard and the class compares it with the model. T gives feedback on pronunciation and reminds Ss that the teacher always checks the tool.","hs":"- Ss look at the pictures and answer.\n- Ss look at the board and listen.\n- Ss repeat in chorus, in groups and individually.\n- Ss listen to the recording and repeat.\n- Ss repeat with the correct intonation.\n- Ss listen to the tool and repeat the sentences (AI 2.A2).\n- Some Ss say a sentence into the microphone and compare it with the model; the class listens."},{"ten":"3. Practice (10’) – Activity 7: Let’s talk","gv":"* Aims: Ss will be able to use the sentence pattern to talk about the pictures.\n* Procedure:\n- T points at the pictures in Activity 7 and elicits the words.\n- T models with a good pupil: T asks, the pupil answers (Is there a fox? – Yes, there is.).\n- Half the class asks and the other half answers; then they swap roles.\n- T puts Ss into pairs: S1 points at a picture and asks, S2 answers; then they swap.\n- T goes around to offer support and invites some pairs to perform in front of the class.\n- (Digital competence 2.1.CB1a) T shows the Activity 7 pictures on the TV and plays a recorded question/model for each picture (Is there a box? / Is there a fox? / Is there an ox?). Ss look, choose the right picture and answer in turns.","hs":"- Ss look and say the words.\n- Ss watch the model.\n- Ss practise in two halves.\n- Ss practise in pairs.\n- Some pairs perform; the class listens and gives comments.\n- Ss listen to the recorded question, choose the picture and answer in turns (Digital competence 2.1.CB1a)."},{"ten":"4. Production (8’) – Activity 8: Let’s sing","gv":"* Aims: Ss will be able to sing the song of Unit 6: On the farm with the correct pronunciation and actions.\n* Procedure:\n- T draws Ss’ attention to the song and the pictures; T reads the lyrics line by line for Ss to repeat.\n- T plays the recording all the way through; Ss listen.\n- T plays it again; Ss sing along line by line.\n- T shows simple actions; Ss sing and do the actions.\n- T invites some groups to sing in front of the class and praises them.","hs":"- Ss look at the song and repeat the lyrics.\n- Ss listen to the song.\n- Ss sing along line by line.\n- Ss sing and do the actions.\n- Some groups perform; the class claps."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T shows a picture and asks Ss to say the sentence pattern once more.\n- (Animal care education) T asks: “How do you take care of animals?” and reminds Ss never to tease, chase or hurt animals.\n- Homework: Practise the sentences and the song at home; prepare Fun time.","hs":"- Ss say the sentence.\n- Ss answer and listen.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":12,"tiet":2,"bai":"Fun time 2 – Lesson 1","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Revise the words, letter-sounds and sentence patterns of Units 5–6:\n- Unit 5: In the classroom – words: question, square, quiz – letter and sound: Q, q /kw/ – pattern: What’s she/he doing? She’s/He’s ___.\n- Unit 6: On the farm – words: box, fox, ox – letter and sound: X, x /ks/ – pattern: Is there a/an ___? Yes, there is. / No, there isn’t.\n2. Skills: Listening and speaking\n3. Attributes:\n- Cooperate with classmates in games and group work and be confident when speaking English.\n- Character education: Cooperate, play honestly and respect friends.\n4. Digital Competence (AI 2.A2, 2.4.CB1a): The teacher may use AI voices/images checked in advance to create a fun challenge; pupils compare them with the pictures, words and sentence patterns they have learnt, and do not treat AI output as the default answer. Take part in simple digital games/learning resources in groups; wait for their turn, choose answers and respond politely.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Units 5–6), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a cheerful atmosphere and lead in to Fun time.\n* Procedure:\n- T greets the class and asks Ss to sing the song of Unit 6: On the farm.\n- T introduces Fun time: “Today we play and revise Unit 5: In the classroom and Unit 6: On the farm.”","hs":"- Ss greet T and sing the song.\n- Ss listen and open their books."},{"ten":"2. Revision of words and sounds (10’)","gv":"* Aims: Ss will be able to revise the words and letter-sounds of Units 5–6.\n* Procedure:\n- T shows the flashcards quickly (question, square, quiz, box, fox, ox); Ss say the words.\n- T writes the letters Q, q and X, x on the board; Ss come up, stick each flashcard under the correct letter and say the sound (/kw/ or /ks/).\n- Game “Slap the board”: two teams; T says a word, one pupil from each team slaps the correct picture.","hs":"- Ss say the words.\n- Ss sort the flashcards under the letters and say the sounds.\n- Ss play the game in two teams."},{"ten":"3. Fun time activities (12’)","gv":"* Aims: Ss will be able to use the words and sentence patterns of Units 5–6 in games.\n* Procedure:\n- T draws Ss’ attention to the Fun time page in the Pupil’s Book and explains the activities.\n- T models the first activity with the class; Ss do the activities in pairs or groups.\n- T goes around to offer support and checks the answers as a class.\n- (Digital competence 2.4.CB1a) T runs a simple slide game on the projector (“Guess the picture”: a picture is hidden behind squares). Groups take turns to choose a square and say the word or sentence; groups wait for their turn and respond politely.\n- (AI 2.A2) T shows two AI images/voices prepared and checked in advance (e.g. a fox picture with a voice saying “box”). Ss compare them with the words and pictures they have learnt and say whether they are right; T reminds Ss that AI output is not always the answer.","hs":"- Ss look at the Fun time page and listen.\n- Ss watch the model and do the activities in pairs or groups.\n- Ss check the answers.\n- Ss play the game in groups, wait for their turn and cheer politely (Digital competence 2.4.CB1a).\n- Ss compare the AI picture/voice with what they have learnt and say “Right” or “Wrong” (AI 2.A2)."},{"ten":"4. Production (6’) – Game: Pass the ball","gv":"* Aims: Ss will be able to say the words and sentences of Units 5–6 confidently.\n* Procedure:\n- T plays music; Ss pass a ball around. When the music stops, the pupil with the ball looks at the flashcard T shows and says a word or a sentence (e.g. What’s she doing? – She’s colouring a square. / Is there a fox? – Yes, there is.).\n- T praises correct answers and helps Ss who need support.\n- (Character education) T reminds Ss to cooperate, play honestly and respect their friends.","hs":"- Ss pass the ball and say a word or a sentence when the music stops.\n- Ss listen and cheer their friends.\n- Ss play fairly and respect their friends."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss which game they liked best and which words they remember.\n- Homework: Revise the words, sounds and sentences of Units 5–6; prepare Fun time Lesson 2.","hs":"- Ss answer.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":13,"tiet":1,"bai":"Fun time 2 – Lesson 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Revise the words, letter-sounds and sentence patterns of Units 5–6:\n- Unit 5: In the classroom – words: question, square, quiz – letter and sound: Q, q /kw/ – pattern: What’s she/he doing? She’s/He’s ___.\n- Unit 6: On the farm – words: box, fox, ox – letter and sound: X, x /ks/ – pattern: Is there a/an ___? Yes, there is. / No, there isn’t.\n2. Skills: Listening and speaking; writing (missing letters of known words)\n3. Attributes:\n- Cooperate with classmates in games and group work and be confident when speaking English.\n- Digital safety education: No personal account is needed; do not enter private information.\n4. Digital Competence (1.2.CB1a, AI 2.A1): Observe, listen to and select simple information on teacher-controlled digital learning resources; check again when an answer does not match the picture/audio. Recognise that AI can generate voices or suggest answers but is sometimes wrong; pupils need to ask the teacher/check the textbook before correcting their work.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Units 5–6), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils, colour pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the chants and lead in to the lesson.\n* Procedure:\n- T greets the class and asks Ss to say the chants of Unit 5: In the classroom and Unit 6: On the farm with clapping.\n- T introduces the lesson.","hs":"- Ss greet T and say the chants.\n- Ss listen and open their books."},{"ten":"2. Sentence patterns (10’)","gv":"* Aims: Ss will be able to revise the sentence patterns of Units 5–6.\n* Procedure:\n- T shows the pictures and elicits the patterns; T writes them on the board:\n+ What’s she/he doing?\n+ She’s/He’s ___.\n+ Is there a/an ___?\n+ Yes, there is. / No, there isn’t.\n- T–Ss, then half class – half class practise with the pictures.\n- Ss practise in pairs with the pictures in the Pupil’s Book.","hs":"- Ss look at the pictures and say the patterns.\n- Ss practise with T and in two halves.\n- Ss practise in pairs."},{"ten":"3. Practice (12’) – Fun time activities","gv":"* Aims: Ss will be able to consolidate the words, letters and sentence patterns through the Fun time activities.\n* Procedure:\n- T explains the Fun time activities in the Pupil’s Book and does an example with the class.\n- Ss do the activities individually or in pairs; T goes around to offer support.\n- Look and write: T shows the pictures of the six words; Ss write the missing letters (__iz, bo_ …) in their notebooks.\n- T checks the answers as a class.\n- (Digital competence 1.2.CB1a) T opens a listening exercise on the digital resource (teacher-controlled). The computer plays a word or sentence; Ss look and choose the picture; if the answer does not match the picture/audio, Ss listen and check again.\n- (AI 2.A1) T shows an AI-suggested answer prepared by T with one mistake (e.g. “Is there a fox?” for a box picture). Ss check it with the Pupil’s Book and ask T before correcting it.","hs":"- Ss listen and follow the example.\n- Ss do the activities.\n- Ss write the missing letters in their notebooks.\n- Ss check the answers.\n- Ss listen, choose the picture and check again when it does not match (Digital competence 1.2.CB1a).\n- Ss find the mistake in the AI answer, check with the book and correct it with T (AI 2.A1)."},{"ten":"4. Production (6’) – Mini talks","gv":"* Aims: Ss will be able to use the patterns in short exchanges.\n* Procedure:\n- T gives each pair two flashcards; pairs make a short exchange with a pattern from Unit 5 or Unit 6.\n- T invites some pairs to perform and gives feedback.","hs":"- Ss work in pairs and make short exchanges.\n- Some pairs perform; the class listens."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say one word and one sentence they remember from Units 5–6.\n- (Digital safety education) T reminds Ss: we do not need a personal account to play these games; never type your name, address or phone number into apps or games.\n- Homework: Revise Units 5–6; prepare the next unit.","hs":"- Ss say a word and a sentence.\n- Ss listen and repeat the rule.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":13,"tiet":2,"bai":"Unit 7: In the kitchen – Lesson 1 (Activities 1–2)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Vocabulary: juice, jelly, jam\n- Phonics: recognise the letter J, j and say the sound /dʒ/ in the new words\n2. Skills: Listening and speaking\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Health education: Recognise some familiar foods and drinks; begin to build healthy eating habits and choose suitable food.\n4. Digital Competence (AI 2.A1): Recognise that AI can support listening to and pronouncing English vocabulary through a text-to-speech tool. The teacher has pupils listen to, identify and point to the correct pictures for the words juice, jelly, jam; pupils practise the letter J, j and the /dʒ/ sound.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 7: In the kitchen), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a friendly atmosphere and lead in to the new unit.\n* Procedure:\n- T greets the class and asks Ss to sing a song they have learnt.\n- T plays “Slap the board” with the flashcards of Unit 5: In the classroom and Unit 6: On the farm (question, square, quiz, box, fox, ox).\n- T shows the opening picture of Unit 7: In the kitchen and asks: What can you see?\n- T introduces the unit title and the aims of the lesson.","hs":"- Ss greet T and sing the song.\n- Ss play the game in two teams.\n- Ss look at the picture and answer.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 1: Listen and repeat","gv":"* Aims: Ss will be able to recognise and say the words juice, jelly, jam and the letter-sound J, j /dʒ/.\n* Procedure:\n- T uses flashcards/pictures to introduce the new words:\n+ juice: nước ép (picture)\n+ jelly: thạch (picture)\n+ jam: mứt (picture)\n- T models each word three times; Ss repeat in chorus, in groups and individually.\n- T sticks the flashcards on the board and writes the words under them.\n- T introduces the letter J, j and the sound /dʒ/ at the beginning of the words; T says the sound slowly and asks Ss to watch T’s mouth.\n- T plays the recording of Activity 1 and pauses after each word for Ss to repeat. T plays it again.\n- T corrects Ss’ pronunciation where necessary.\n- Checking: “What and where” – T rubs out the words one by one; Ss say the words and their places.\n- (AI 2.A1) T types the words juice, jelly, jam into a text-to-speech tool on the class computer (prepared and checked in advance; Ss use no accounts) and plays them in random order. Ss listen, point to the matching picture and repeat; then they practise the sound /dʒ/.\n- T explains simply: “This voice is made by a computer (AI). It helps us listen, but we always check with the teacher and the book.”","hs":"- Ss look at the flashcards and listen.\n- Ss repeat in chorus, in groups and individually.\n- Ss look at the board.\n- Ss watch, listen and say the sound /dʒ/ and the words.\n- Ss listen to the recording and repeat.\n- Ss correct their pronunciation.\n- Ss play “What and where”.\n- Ss listen to the computer voice, point to the matching picture and repeat the words and the sound /dʒ/ (AI 2.A1).\n- Ss listen to T."},{"ten":"3. Practice (12’) – Activity 2: Point and say","gv":"* Aims: Ss will be able to point at the pictures and say the words correctly.\n* Procedure:\n- T draws Ss’ attention to the pictures in Activity 2.\n- T points at each picture and says the word; Ss repeat.\n- T points at the pictures in random order; Ss say the words.\n- T puts Ss into pairs: one pupil points at a picture, the other says the word; then they swap roles.\n- T goes around the classroom to offer support.\n- T invites some pairs to point and say in front of the class; T praises and corrects them.","hs":"- Ss look at the pictures.\n- Ss listen and repeat.\n- Ss say the words.\n- Ss work in pairs to point and say.\n- Ss ask T for help when needed.\n- Some pairs perform; the class listens and claps."},{"ten":"4. Production (6’) – Game: Clap for the sound","gv":"* Aims: Ss will be able to recognise the sound /dʒ/ in words.\n* Procedure:\n- T says the new words and some known words (ball, pen, sea) in random order.\n- Ss clap once when they hear the sound /dʒ/ and stay quiet for the other words.\n- T shows the flashcards quickly (“Flash cards”); Ss say the words.\n- (Health education) T asks: “Do you like juice?” and reminds Ss to drink water and fresh juice and not to eat too much jam or jelly.","hs":"- Ss listen carefully.\n- Ss clap when they hear the sound /dʒ/.\n- Ss say the words on the flashcards.\n- Ss answer and listen to T’s advice."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What have we learnt today?” and points at the flashcards for Ss to say the words and the sound /dʒ/.\n- Homework: Practise saying the words at home; prepare Lesson 2 (Activities 3–5).","hs":"- Ss answer and say the words and the sound.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":14,"tiet":1,"bai":"Unit 7: In the kitchen – Lesson 2 (Activities 3–5)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say the chant of Unit 7: In the kitchen with the sound /dʒ/\n- Listen and tick the correct pictures (juice, jelly, jam)\n- Look at the pictures and write the missing letter(s) to complete the words\n2. Skills: Listening and speaking; reading and writing (Activity 5: Look and write)\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Thrift education - avoiding waste: Take just enough food and drink and do not leave leftovers.\n4. Digital Competence (1.1.CB1a, 4.1.CB1a): Perform simple information-selection actions on digital learning resources under the teacher's guidance. Pupils listen to the sentences “I like jam/juice/jelly.” and then choose or tick the matching pictures; look at the letters and complete the missing words. Begin to build habits of using digital devices safely and for the right purpose: only open learning resources provided by the teacher; do not click on advertisements or unfamiliar links on their own.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 7: In the kitchen), TV or projector, computer.\n- Pupils: Pupil’s Book, notebooks, pencils, colour pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Lesson 1 and lead in to the lesson.\n* Procedure:\n- T greets the class.\n- T plays “What’s missing?” with the flashcards juice, jelly, jam: T hides one card; Ss say the missing word.\n- T asks Ss to say the letter J, j and the sound /dʒ/.\n- T introduces Lesson 2.","hs":"- Ss greet T.\n- Ss play the game and say the missing word.\n- Ss say the letter and the sound.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 3: Listen and chant","gv":"* Aims: Ss will be able to say the chant with the correct sound /dʒ/ and rhythm.\n* Procedure:\n- T draws Ss’ attention to the chant and the pictures in Activity 3.\n- T plays the recording all the way through; Ss listen and follow in their books.\n- T plays it again line by line; Ss repeat.\n- T models clapping the rhythm; Ss chant and clap along.\n- T divides the class into groups to take turns chanting.\n- T invites some groups to chant in front of the class and praises them.","hs":"- Ss look at the chant.\n- Ss listen and follow.\n- Ss repeat line by line.\n- Ss chant and clap.\n- Ss chant in groups.\n- Some groups perform; the class claps."},{"ten":"3. Practice (10’) – Activity 4: Listen and tick","gv":"* Aims: Ss will be able to listen and tick the correct pictures.\n* Procedure:\n- T draws Ss’ attention to the pictures and asks Ss to name the things in each picture.\n- T explains the task and does the example with the class.\n- T plays the recording; Ss listen and tick. T plays it again for Ss to check.\n- T asks Ss to swap books and check in pairs.\n- T checks the answers as a class (key: Teacher’s Book) and plays the recording again, pausing for Ss to repeat.\n- (Digital competence 4.1.CB1a) Before Ss come to the screen, T reminds them to sit properly, keep a suitable distance from the screen and only touch/click when T says so; only open learning resources provided by T and never click on advertisements or unfamiliar links.\n- (Digital competence 1.1.CB1a) T shows the Activity 4 pictures on the TV/projector (digital book opened by T). T plays each sentence (I like jam/juice/jelly.) again; one pupil comes up and clicks/taps the picture they chose under T’s guidance; the class says “Yes” or “No”.","hs":"- Ss look at the pictures and name the things.\n- Ss follow the example.\n- Ss listen and tick, then listen again and check.\n- Ss swap books and check in pairs.\n- Ss check the answers and repeat.\n- Ss sit properly, keep a suitable distance from the screen and follow T’s instructions (Digital competence 4.1.CB1a).\n- Ss take turns to choose the matching picture on the screen; the class checks (Digital competence 1.1.CB1a)."},{"ten":"4. Production (8’) – Activity 5: Look and write","gv":"* Aims: Ss will be able to look at the pictures and write the missing letter(s) to complete the words.\n* Procedure:\n- T draws Ss’ attention to the pictures and the incomplete words.\n- T models the first one on the board, e.g. “_am” → “jam”; Ss read the word in chorus.\n- Ss do the task individually; T goes around to help with letter formation.\n- T invites some Ss to write the answers on the board; the class checks and reads the words aloud.","hs":"- Ss look at the pictures and the words.\n- Ss watch and read the word in chorus.\n- Ss write the missing letter(s) in their books.\n- Some Ss write on the board; the class checks and reads aloud."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the chant once more and spell the letter J, j.\n- (Thrift education – avoiding waste) T reminds Ss to take just enough food and drink and not to leave leftovers.\n- Homework: Practise the chant and the words at home; prepare Lesson 3 (Activities 6–8).","hs":"- Ss say the chant.\n- Ss listen and say how they avoid wasting food.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":14,"tiet":2,"bai":"Unit 7: In the kitchen – Lesson 3 (Activities 6–8)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Sentence patterns: Pass me the ___, please. Here you are.\n- e.g. Pass me the jam, please. – Here you are. / Pass me the juice, please. – Here you are. / Pass me the jelly, please. – Here you are.\n- Use the pattern to talk about the pictures and sing the song of Unit 7: In the kitchen\n2. Skills: Listening and speaking\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Ethics - communication skills: Use the word “please”, say thank you and pass things to others politely at mealtimes.\n4. Digital Competence (AI 2.A2, 2.1.CB1a): Recognise that AI can support speaking practice and pronunciation checking of simple English communication patterns. Under the teacher's guidance, pupils practise the pattern “Pass me the jam, please.” - “Here you are.” and substitute juice/jelly. The teacher may use a model-reading tool so that pupils listen, repeat and adjust their own pronunciation. Take part in simple guided digital communication activities: listen to requests, look at the pictures and choose/say suitable responses.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 7: In the kitchen), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and the chant and lead in to the lesson.\n* Procedure:\n- T greets the class and asks Ss to say the chant of Lesson 2.\n- T shows the flashcards juice, jelly, jam; Ss say the words.\n- T introduces Lesson 3.","hs":"- Ss greet T and say the chant.\n- Ss say the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 6: Listen and repeat","gv":"* Aims: Ss will be able to understand and say the sentence patterns: Pass me the ___, please. Here you are.\n* Procedure:\n- T shows the pictures in Activity 6 and sets the context: “Look! Who’s this? What can you see?”\n- T introduces the sentence pattern and writes it on the board:\n+ Pass me the ___, please.\n+ Here you are.\n+ e.g. Pass me the jam, please. – Here you are.\n- T models the sentences; Ss repeat in chorus, in groups and individually.\n- T plays the recording; Ss listen and repeat sentence by sentence. T plays it again.\n- T reminds Ss to say “please” and “Here you are.” in a polite voice.\n- (AI 2.A2) T opens a pronunciation tool on the class computer (teacher’s account only). The tool reads the model sentences: Pass me the jam, please. – Here you are. / Pass me the juice, please. – Here you are. / Pass me the jelly, please. – Here you are. Ss listen and repeat.\n- Two or three volunteers say one sentence into the microphone; the tool reads back what it heard and the class compares it with the model. T gives feedback on pronunciation and reminds Ss that the teacher always checks the tool.","hs":"- Ss look at the pictures and answer.\n- Ss look at the board and listen.\n- Ss repeat in chorus, in groups and individually.\n- Ss listen to the recording and repeat.\n- Ss repeat with the correct intonation.\n- Ss listen to the tool and repeat the sentences (AI 2.A2).\n- Some Ss say a sentence into the microphone and compare it with the model; the class listens."},{"ten":"3. Practice (10’) – Activity 7: Let’s talk","gv":"* Aims: Ss will be able to use the sentence pattern to talk about the pictures.\n* Procedure:\n- T points at the pictures in Activity 7 and elicits the words.\n- T models with a good pupil: T asks, the pupil answers (Pass me the jam, please. – Here you are.).\n- Half the class asks and the other half answers; then they swap roles.\n- T puts Ss into pairs: S1 points at a picture and asks, S2 answers; then they swap.\n- T goes around to offer support and invites some pairs to perform in front of the class.\n- (Digital competence 2.1.CB1a) T shows the Activity 7 pictures on the TV and plays a recorded question/model for each picture (Pass me the juice/jelly, please. – Here you are.). Ss look, choose the right picture and answer in turns.\n- (Ethics – communication skills) T reminds Ss to say “please” and “Thank you” and to pass things politely with both hands at mealtimes.","hs":"- Ss look and say the words.\n- Ss watch the model.\n- Ss practise in two halves.\n- Ss practise in pairs.\n- Some pairs perform; the class listens and gives comments.\n- Ss listen to the recorded question, choose the picture and answer in turns (Digital competence 2.1.CB1a).\n- Ss act out passing things politely."},{"ten":"4. Production (8’) – Activity 8: Let’s sing","gv":"* Aims: Ss will be able to sing the song of Unit 7: In the kitchen with the correct pronunciation and actions.\n* Procedure:\n- T draws Ss’ attention to the song and the pictures; T reads the lyrics line by line for Ss to repeat.\n- T plays the recording all the way through; Ss listen.\n- T plays it again; Ss sing along line by line.\n- T shows simple actions; Ss sing and do the actions.\n- T invites some groups to sing in front of the class and praises them.","hs":"- Ss look at the song and repeat the lyrics.\n- Ss listen to the song.\n- Ss sing along line by line.\n- Ss sing and do the actions.\n- Some groups perform; the class claps."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T shows a picture and asks Ss to say the sentence pattern once more.\n- Homework: Practise the sentences and the song at home; prepare the next unit.","hs":"- Ss say the sentence.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":15,"tiet":1,"bai":"Unit 8: In the village – Lesson 1 (Activities 1–2)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Vocabulary: village, van, volleyball\n- Phonics: recognise the letter V, v and say the sound /v/ in the new words\n2. Skills: Listening and speaking\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Local education: Recognise some familiar images of the countryside; develop love for and awareness of preserving the landscape where they live.\n4. Digital Competence (AI 2.A1): Recognise that AI can support listening to and pronouncing English vocabulary through a text-to-speech tool. The teacher has pupils listen to, identify and point to the correct pictures for the words village, van, volleyball; pupils practise the letter V, v and the /v/ sound.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 8: In the village), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a friendly atmosphere and lead in to the new unit.\n* Procedure:\n- T greets the class and asks Ss to sing a song they have learnt.\n- T plays “Slap the board” with the flashcards of Unit 7: In the kitchen (juice, jelly, jam).\n- T shows the opening picture of Unit 8: In the village and asks: What can you see?\n- T introduces the unit title and the aims of the lesson.","hs":"- Ss greet T and sing the song.\n- Ss play the game in two teams.\n- Ss look at the picture and answer.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 1: Listen and repeat","gv":"* Aims: Ss will be able to recognise and say the words village, van, volleyball and the letter-sound V, v /v/.\n* Procedure:\n- T uses flashcards/pictures to introduce the new words:\n+ village: ngôi làng (picture)\n+ van: xe tải nhỏ (picture)\n+ volleyball: bóng chuyền (picture)\n- T models each word three times; Ss repeat in chorus, in groups and individually.\n- T sticks the flashcards on the board and writes the words under them.\n- T introduces the letter V, v and the sound /v/ at the beginning of the words; T says the sound slowly and asks Ss to watch T’s mouth.\n- T plays the recording of Activity 1 and pauses after each word for Ss to repeat. T plays it again.\n- T corrects Ss’ pronunciation where necessary.\n- Checking: “What and where” – T rubs out the words one by one; Ss say the words and their places.\n- (AI 2.A1) T types the words village, van, volleyball into a text-to-speech tool on the class computer (prepared and checked in advance; Ss use no accounts) and plays them in random order. Ss listen, point to the matching picture and repeat; then they practise the sound /v/.\n- T explains simply: “This voice is made by a computer (AI). It helps us listen, but we always check with the teacher and the book.”","hs":"- Ss look at the flashcards and listen.\n- Ss repeat in chorus, in groups and individually.\n- Ss look at the board.\n- Ss watch, listen and say the sound /v/ and the words.\n- Ss listen to the recording and repeat.\n- Ss correct their pronunciation.\n- Ss play “What and where”.\n- Ss listen to the computer voice, point to the matching picture and repeat the words and the sound /v/ (AI 2.A1).\n- Ss listen to T."},{"ten":"3. Practice (12’) – Activity 2: Point and say","gv":"* Aims: Ss will be able to point at the pictures and say the words correctly.\n* Procedure:\n- T draws Ss’ attention to the pictures in Activity 2.\n- T points at each picture and says the word; Ss repeat.\n- T points at the pictures in random order; Ss say the words.\n- T puts Ss into pairs: one pupil points at a picture, the other says the word; then they swap roles.\n- T goes around the classroom to offer support.\n- T invites some pairs to point and say in front of the class; T praises and corrects them.","hs":"- Ss look at the pictures.\n- Ss listen and repeat.\n- Ss say the words.\n- Ss work in pairs to point and say.\n- Ss ask T for help when needed.\n- Some pairs perform; the class listens and claps."},{"ten":"4. Production (6’) – Game: Clap for the sound","gv":"* Aims: Ss will be able to recognise the sound /v/ in words.\n* Procedure:\n- T says the new words and some known words (bike, pen, fox) in random order.\n- Ss clap once when they hear the sound /v/ and stay quiet for the other words.\n- T shows the flashcards quickly (“Flash cards”); Ss say the words.\n- (Local education) T shows a photo of a familiar village scene and asks: “Do you like your village?” T encourages Ss to love and keep clean the place where they live.","hs":"- Ss listen carefully.\n- Ss clap when they hear the sound /v/.\n- Ss say the words on the flashcards.\n- Ss look, answer and share how they keep their place clean."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What have we learnt today?” and points at the flashcards for Ss to say the words and the sound /v/.\n- Homework: Practise saying the words at home; prepare Lesson 2 (Activities 3–5).","hs":"- Ss answer and say the words and the sound.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":15,"tiet":2,"bai":"Unit 8: In the village – Lesson 2 (Activities 3–5)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say the chant of Unit 8: In the village with the sound /v/\n- Listen and circle the correct pictures (village, van, volleyball)\n- Look at the pictures and write the missing letter(s) to complete the words\n2. Skills: Listening and speaking; reading and writing (Activity 5: Look and write)\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Road safety: Recognise that a van is a means of transport; sit properly, fasten the seat belt if there is one and do not play around in the vehicle.\n4. Digital Competence (1.1.CB1a, 4.1.CB1a): Perform simple information-selection actions on digital learning resources under the teacher's guidance. Pupils listen to the sentences “This is a van/village/volleyball.” and then choose or circle the matching pictures; look at the pictures and complete the missing words. Begin to build habits of using digital devices for the right purpose: only work on learning resources opened by the teacher and stop using the device when asked.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 8: In the village), TV or projector, computer.\n- Pupils: Pupil’s Book, notebooks, pencils, colour pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Lesson 1 and lead in to the lesson.\n* Procedure:\n- T greets the class.\n- T plays “What’s missing?” with the flashcards village, van, volleyball: T hides one card; Ss say the missing word.\n- T asks Ss to say the letter V, v and the sound /v/.\n- T introduces Lesson 2.","hs":"- Ss greet T.\n- Ss play the game and say the missing word.\n- Ss say the letter and the sound.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 3: Listen and chant","gv":"* Aims: Ss will be able to say the chant with the correct sound /v/ and rhythm.\n* Procedure:\n- T draws Ss’ attention to the chant and the pictures in Activity 3.\n- T plays the recording all the way through; Ss listen and follow in their books.\n- T plays it again line by line; Ss repeat.\n- T models clapping the rhythm; Ss chant and clap along.\n- T divides the class into groups to take turns chanting.\n- T invites some groups to chant in front of the class and praises them.","hs":"- Ss look at the chant.\n- Ss listen and follow.\n- Ss repeat line by line.\n- Ss chant and clap.\n- Ss chant in groups.\n- Some groups perform; the class claps."},{"ten":"3. Practice (10’) – Activity 4: Listen and circle","gv":"* Aims: Ss will be able to listen and circle the correct pictures.\n* Procedure:\n- T draws Ss’ attention to the pictures and asks Ss to name the things in each picture.\n- T explains the task and does the example with the class.\n- T plays the recording; Ss listen and circle. T plays it again for Ss to check.\n- T asks Ss to swap books and check in pairs.\n- T checks the answers as a class (key: Teacher’s Book) and plays the recording again, pausing for Ss to repeat.\n- (Digital competence 4.1.CB1a) Before Ss come to the screen, T reminds them to sit properly, keep a suitable distance from the screen and only touch/click when T says so; stop using the device when T asks.\n- (Digital competence 1.1.CB1a) T shows the Activity 4 pictures on the TV/projector (digital book opened by T). T plays each sentence (This is a van/village/volleyball.) again; one pupil comes up and clicks/taps the picture they chose under T’s guidance; the class says “Yes” or “No”.","hs":"- Ss look at the pictures and name the things.\n- Ss follow the example.\n- Ss listen and circle, then listen again and check.\n- Ss swap books and check in pairs.\n- Ss check the answers and repeat.\n- Ss sit properly, keep a suitable distance from the screen and follow T’s instructions (Digital competence 4.1.CB1a).\n- Ss take turns to choose the matching picture on the screen; the class checks (Digital competence 1.1.CB1a)."},{"ten":"4. Production (8’) – Activity 5: Look and write","gv":"* Aims: Ss will be able to look at the pictures and write the missing letter(s) to complete the words.\n* Procedure:\n- T draws Ss’ attention to the pictures and the incomplete words.\n- T models the first one on the board, e.g. “_an” → “van”; Ss read the word in chorus.\n- Ss do the task individually; T goes around to help with letter formation.\n- T invites some Ss to write the answers on the board; the class checks and reads the words aloud.","hs":"- Ss look at the pictures and the words.\n- Ss watch and read the word in chorus.\n- Ss write the missing letter(s) in their books.\n- Some Ss write on the board; the class checks and reads aloud."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the chant once more and spell the letter V, v.\n- (Road safety) T points at the van: “A van is a vehicle.” T reminds Ss to sit properly, fasten the seat belt if there is one and not play around in a vehicle.\n- Homework: Practise the chant and the words at home; prepare Lesson 3 (Activities 6–8).","hs":"- Ss say the chant.\n- Ss listen and repeat the rules.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":16,"tiet":1,"bai":"Unit 8: In the village – Lesson 3 (Activities 6–8)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Sentence patterns: Can you draw a ___? Yes, I can. / No, I can’t.\n- e.g. Can you draw a van? – Yes, I can. / Can you draw a village? – No, I can’t.\n- Use the pattern to talk about the pictures and sing the song of Unit 8: In the village\n2. Skills: Listening and speaking\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Ethics - cooperation skills: Respect classmates' products, encourage friends and take care of school supplies together during drawing activities.\n4. Digital Competence (AI 2.A2, 3.1.CB1a): Recognise that AI can support speaking practice and pronunciation checking of simple English communication patterns. Under the teacher's guidance, pupils practise the pattern “Can you draw a van?” - “Yes, I can.” / “No, I can’t.” and substitute volleyball, football, village. The teacher may use a model-reading tool so that pupils listen, repeat and adjust their own pronunciation. Create simple digital content under the teacher's guidance: use basic drawing tools to draw a familiar object/scene and save the product in the location specified by the teacher.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 8: In the village), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance), a basic drawing program on the class computer.\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and the chant and lead in to the lesson.\n* Procedure:\n- T greets the class and asks Ss to say the chant of Lesson 2.\n- T shows the flashcards village, van, volleyball; Ss say the words.\n- T introduces Lesson 3.","hs":"- Ss greet T and say the chant.\n- Ss say the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 6: Listen and repeat","gv":"* Aims: Ss will be able to understand and say the sentence patterns: Can you draw a ___? Yes, I can. / No, I can’t.\n* Procedure:\n- T shows the pictures in Activity 6 and sets the context: “Look! Who’s this? What can you see?”\n- T introduces the sentence pattern and writes it on the board:\n+ Can you draw a ___?\n+ Yes, I can. / No, I can’t.\n+ e.g. Can you draw a van? – Yes, I can.\n- T models the sentences; Ss repeat in chorus, in groups and individually.\n- T plays the recording; Ss listen and repeat sentence by sentence. T plays it again.\n- T reminds Ss of the rising intonation in Yes/No questions and the falling intonation in answers.\n- (AI 2.A2) T opens a pronunciation tool on the class computer (teacher’s account only). The tool reads the model sentences: Can you draw a van? – Yes, I can. / Can you draw a village? – No, I can’t. Ss listen and repeat.\n- Two or three volunteers say one sentence into the microphone; the tool reads back what it heard and the class compares it with the model. T gives feedback on pronunciation and reminds Ss that the teacher always checks the tool.","hs":"- Ss look at the pictures and answer.\n- Ss look at the board and listen.\n- Ss repeat in chorus, in groups and individually.\n- Ss listen to the recording and repeat.\n- Ss repeat with the correct intonation.\n- Ss listen to the tool and repeat the sentences (AI 2.A2).\n- Some Ss say a sentence into the microphone and compare it with the model; the class listens."},{"ten":"3. Practice (10’) – Activity 7: Let’s talk","gv":"* Aims: Ss will be able to use the sentence pattern to talk about the pictures.\n* Procedure:\n- T points at the pictures in Activity 7 and elicits the words.\n- T models with a good pupil: T asks, the pupil answers (Can you draw a van? – Yes, I can.).\n- Half the class asks and the other half answers; then they swap roles.\n- T puts Ss into pairs: S1 points at a picture and asks, S2 answers; then they swap.\n- T goes around to offer support and invites some pairs to perform in front of the class.","hs":"- Ss look and say the words.\n- Ss watch the model.\n- Ss practise in two halves.\n- Ss practise in pairs.\n- Some pairs perform; the class listens and gives comments."},{"ten":"4. Production (8’) – Activity 8: Let’s sing","gv":"* Aims: Ss will be able to sing the song of Unit 8: In the village with the correct pronunciation and actions.\n* Procedure:\n- T draws Ss’ attention to the song and the pictures; T reads the lyrics line by line for Ss to repeat.\n- T plays the recording all the way through; Ss listen.\n- T plays it again; Ss sing along line by line.\n- T shows simple actions; Ss sing and do the actions.\n- T invites some groups to sing in front of the class and praises them.\n- (Digital competence 3.1.CB1a) After the song, T opens a basic drawing program (e.g. Paint) on the class computer. Two or three Ss take turns to draw a simple van or a house in the village with the pencil/shape tools; T saves each drawing in the class folder with the pupil’s first name.\n- (Ethics – cooperation skills) The class looks at the drawings and says “Good job!”; T reminds Ss to respect their friends’ work and to take care of school things.","hs":"- Ss look at the song and repeat the lyrics.\n- Ss listen to the song.\n- Ss sing along line by line.\n- Ss sing and do the actions.\n- Some groups perform; the class claps.\n- Some Ss draw on the class computer while the class watches and asks: Can you draw a van? (Digital competence 3.1.CB1a)\n- Ss praise their friends’ drawings and take care of school things."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T shows a picture and asks Ss to say the sentence pattern once more.\n- Homework: Practise the sentences and the song at home; prepare the Review.","hs":"- Ss say the sentence.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":16,"tiet":2,"bai":"Review 2 – Phil and Sue","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Listen to and understand the Phil and Sue story in Review 2\n- Revise the words, letter-sounds and sentence patterns of Units 5–8:\n- Unit 5: In the classroom – words: question, square, quiz – letter and sound: Q, q /kw/ – pattern: What’s she/he doing? She’s/He’s ___.\n- Unit 6: On the farm – words: box, fox, ox – letter and sound: X, x /ks/ – pattern: Is there a/an ___? Yes, there is. / No, there isn’t.\n- Unit 7: In the kitchen – words: juice, jelly, jam – letter and sound: J, j /dʒ/ – pattern: Pass me the ___, please. Here you are.\n- Unit 8: In the village – words: village, van, volleyball – letter and sound: V, v /v/ – pattern: Can you draw a ___? Yes, I can. / No, I can’t.\n2. Skills: Listening and speaking\n3. Attributes:\n- Cooperate with classmates in games and group work and be confident when speaking English.\n- Character education: Be honest when stating what they have heard/read.\n4. Digital Competence (AI 2.B1, 1.2.CB1a): Recognise that an AI-style answer/illustration may not match the story; pupils check it against the pictures and the textbook content. Find simple information in the story/digital learning resources to confirm answers.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Units 5–8), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a cheerful atmosphere and revise the words.\n* Procedure:\n- T greets the class and asks Ss to sing a song from Units 5–8.\n- T shows the flashcards of Units 5–8 quickly; Ss say the words.","hs":"- Ss greet T and sing the song.\n- Ss say the words."},{"ten":"2. Before the story (7’)","gv":"* Aims: Ss will be able to predict the story and revise key words.\n* Procedure:\n- T shows the story pictures in Review 2 and asks: “Who are they? What can you see?”\n- T introduces the two characters, Phil and Sue.\n- T asks Ss to find in the pictures the things they know from Units 5–8.","hs":"- Ss look at the pictures and answer.\n- Ss listen and say the names Phil and Sue.\n- Ss point at the things they know and say the words."},{"ten":"3. Listen to the story (13’)","gv":"* Aims: Ss will be able to listen to and understand the Phil and Sue story.\n* Procedure:\n- T plays the recording all the way through; Ss listen and point at the pictures.\n- T plays it again, pausing after each line for Ss to repeat.\n- T asks simple questions about each picture: “Who is this? What can you see?”\n- T puts Ss into groups to read/act out the story with the pictures.\n- (Digital competence 1.2.CB1a) T shows the story pictures on the TV; Ss find simple information (who, what they see) to confirm their answers.\n- (AI 2.B1) T shows an AI-style picture/sentence prepared by T that does not match the story (e.g. wrong object). Ss check it with the pictures and the text in the Pupil’s Book and say what is wrong.","hs":"- Ss listen and point at the pictures.\n- Ss listen and repeat line by line.\n- Ss answer the questions.\n- Ss read/act out the story in groups.\n- Ss look at the screen and find information to confirm their answers (Digital competence 1.2.CB1a).\n- Ss compare the AI-style picture/sentence with the book and say what is wrong (AI 2.B1)."},{"ten":"4. Sounds and sentence patterns (8’)","gv":"* Aims: Ss will be able to revise the letter-sounds and sentence patterns of Units 5–8.\n* Procedure:\n- T writes the letters on the board: Q, q /kw/, X, x /ks/, J, j /dʒ/, V, v /v/; Ss say the sounds and a word for each letter.\n- T shows the pictures; Ss say the patterns in pairs:\n+ What’s she doing? – She’s colouring a square.\n+ Is there a fox? – Yes, there is.\n+ Pass me the jam, please. – Here you are.\n+ Can you draw a van? – Yes, I can.","hs":"- Ss say the sounds and a word for each letter.\n- Ss practise the patterns in pairs."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “Do you like the story? What do Phil and Sue see?”\n- (Character education) T praises Ss who say honestly what they heard/read, even when they are not sure.\n- Homework: Retell the story to your family; prepare Self-check.","hs":"- Ss answer.\n- Ss say honestly what they heard/read.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":17,"tiet":1,"bai":"Review 2 – Self – check – Part 1","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Self-check (Review 2): listen and choose/tick, read and match/complete with the content of Units 5–8\n2. Skills: Listening and speaking; reading\n3. Attributes:\n- Cooperate with classmates in games and group work and be confident when speaking English.\n- Self-study education: Mark the content they have done well and the content that needs more practice.\n4. Digital Competence (1.1.CB1a, AI 2.A2): Listen, choose and check answers on digital learning resources under the teacher's guidance. Compare a simple AI suggestion with the answer based on the picture/audio and correct it if it is wrong.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Units 5–8), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils, colour pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a relaxed atmosphere before the Self-check.\n* Procedure:\n- T greets the class; Ss sing a song from Units 5–8.\n- T explains the Self-check: “Do your best and see what you can do.”","hs":"- Ss greet T and sing.\n- Ss listen."},{"ten":"2. Listening (12’)","gv":"* Aims: Ss will be able to listen and choose/tick the correct answers.\n* Procedure:\n- T draws Ss’ attention to the listening task(s) in the Self-check of Review 2 and asks Ss to name the pictures.\n- T explains the task and does the example.\n- T plays the recording twice; Ss listen and tick/choose.\n- T plays it once more for Ss to check.","hs":"- Ss look at the pictures and name them.\n- Ss follow the example.\n- Ss listen and do the task.\n- Ss listen again and check."},{"ten":"3. Reading (10’)","gv":"* Aims: Ss will be able to read and match/complete with the words and sentences they have learnt.\n* Procedure:\n- T reads the words/sentences in the reading task with Ss.\n- Ss do the task individually; T goes around and helps Ss who need support.\n- Ss swap books and check in pairs.","hs":"- Ss read the words/sentences with T.\n- Ss do the task individually.\n- Ss check in pairs."},{"ten":"4. Checking and feedback (6’)","gv":"* Aims: Ss will be able to check their answers and know what to practise more.\n* Procedure:\n- T checks the answers as a class (key: Teacher’s Book).\n- (Digital competence 1.1.CB1a) T opens the listening task on the digital resource; Ss listen, choose and check the answers on the screen under T’s guidance.\n- (AI 2.A2) T shows a simple AI suggestion for one item (prepared by T, with a mistake). Ss compare it with the picture/audio and correct it.\n- (Self-study education) Ss put a star next to the items they did well and a circle next to the items they need to practise more.","hs":"- Ss check their answers.\n- Ss listen, choose and check the answers on the screen (Digital competence 1.1.CB1a).\n- Ss compare the AI suggestion with the picture/audio and correct it (AI 2.A2).\n- Ss mark the items they did well and the items to practise more."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T praises the class and reminds Ss what to practise at home.\n- Homework: Practise the words and sentences you found difficult; prepare Self-check Part 2.","hs":"- Ss listen.\n- Ss remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":17,"tiet":2,"bai":"Review 2 – Self – check – Part 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Self-check (Review 2): read and write the words and short sentences, and speak with the sentence patterns of Units 5–8\n- Recognise what they can do well and what they need to practise more\n2. Skills: Speaking, reading and writing\n3. Attributes:\n- Cooperate with classmates in games and group work and be confident when speaking English.\n- Honesty education: Complete the Self-check section independently.\n4. Digital Competence (5.2.CB1a, AI 2.B1): Choose suitable simple tools for revision (audio, digital flashcards, digital games provided by the teacher). Do not copy AI answers; pupils do the task themselves first, then use AI examples to check under the teacher's guidance.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Units 5–8), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils, colour pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and lead in to the lesson.\n* Procedure:\n- T greets the class and shows the flashcards of Units 5–8 quickly; Ss say the words.\n- (Digital competence 5.2.CB1a) T offers three simple revision tools: the audio, digital flashcards, a digital picture game. The class chooses one and uses it for two minutes to revise the words.","hs":"- Ss greet T and say the words.\n- Ss choose a revision tool and use it with T to revise the words (Digital competence 5.2.CB1a)."},{"ten":"2. Reading and writing (12’)","gv":"* Aims: Ss will be able to read and write the words and short sentences they have learnt.\n* Procedure:\n- T draws Ss’ attention to the reading and writing tasks in the Self-check of Review 2 and does the example.\n- Ss look at the pictures and write the missing letters/words individually.\n- T goes around to help with spelling and letter formation.\n- T invites some Ss to write the answers on the board; the class checks.","hs":"- Ss look and follow the example.\n- Ss write the missing letters/words.\n- Ss ask T for help when needed.\n- Some Ss write on the board; the class checks."},{"ten":"3. Speaking (10’)","gv":"* Aims: Ss will be able to use the sentence patterns in short speaking tasks.\n* Procedure:\n- T shows the pictures and revises the patterns:\n+ What’s she doing? – She’s colouring a square.\n+ Is there a fox? – Yes, there is.\n+ Pass me the jam, please. – Here you are.\n+ Can you draw a van? – Yes, I can.\n- Ss practise in pairs with the pictures.\n- T calls some pairs to speak and notes who needs more practice.","hs":"- Ss look and say the patterns.\n- Ss practise in pairs.\n- Some pairs speak in front of the class."},{"ten":"4. Self-assessment (6’)","gv":"* Aims: Ss will be able to recognise what they can do well and what they need to practise more.\n* Procedure:\n- T shows the “I can …” statements (say the words, say the sounds, talk with the patterns, write the missing letters).\n- Ss colour a smiley face for each statement in their notebooks.\n- (AI 2.B1) After Ss finish the Self-check on their own, T shows an AI example answer on the screen; Ss use it only to check, not to copy, under T’s guidance.\n- (Honesty education) T reminds Ss to complete the Self-check independently and mark their faces honestly.","hs":"- Ss read the statements with T.\n- Ss colour the faces honestly.\n- Ss finish first, then check with the AI example under T’s guidance (AI 2.B1).\n- Ss work independently and honestly."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T praises the class and reminds each group what to practise more.\n- Homework: Practise the content you marked “need more practice”.","hs":"- Ss listen.\n- Ss remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":18,"tiet":1,"bai":"Reserve period 1","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Consolidate the words, letter-sounds and sentence patterns of Units 1–8 (mainly Units 5–8), focusing on what the class still finds difficult\n2. Skills: Listening and speaking\n3. Attributes:\n- Cooperate with classmates in games and group work and be confident when speaking English.\n- Flexible learning: Take part in the activities the teacher adjusts to the class’s needs; know which content to practise more.\n4. Digital Competence (2.4.CB1a, AI 2.A1): Take part in simple digital activities organised by the teacher where appropriate. Recall the principle that AI only supports; information must be checked before it is used.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Units 1–8), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a cheerful atmosphere.\n* Procedure:\n- T greets the class and asks Ss to choose and sing a song from Units 1–8.\n- Note: T may use this period for test correction or a library/club activity according to the school’s actual plan.","hs":"- Ss greet T and sing the song.\n- Ss listen."},{"ten":"2. Words and sounds (10’)","gv":"* Aims: Ss will be able to consolidate the letters, sounds and words of Units 1–8, focusing on what the class still finds difficult.\n* Procedure:\n- T writes the letters on the board: P, p /p/, K, k /k/, S, s /s/, R, r /r/, Q, q /kw/, X, x /ks/, J, j /dʒ/, V, v /v/.\n- Game “Sound sorting”: T shows a flashcard; a pupil says the word and sticks it under the correct letter.\n- T gives extra practice to Ss who made mistakes in the Self-check.","hs":"- Ss say the letters and sounds.\n- Ss play the game and say the words.\n- Ss practise the difficult words again."},{"ten":"3. Sentence patterns (10’)","gv":"* Aims: Ss will be able to use the sentence patterns of Units 5–8 more confidently.\n* Procedure:\n- T shows the pictures and revises the patterns:\n+ What’s she doing? – She’s colouring a square.\n+ Is there a fox? – Yes, there is.\n+ Pass me the jam, please. – Here you are.\n+ Can you draw a van? – Yes, I can.\n- Ss practise in pairs; T helps pairs that need support.\n- T invites some pairs to perform.","hs":"- Ss look and say the patterns.\n- Ss practise in pairs.\n- Some pairs perform."},{"ten":"4. Digital game (8’)","gv":"* Aims: Ss will be able to revise words and patterns through a simple digital game.\n* Procedure:\n- T runs a picture quiz on the projector (prepared in advance).\n- (Digital competence 2.4.CB1a) Teams take turns: the computer shows a picture, the team says the word or sentence; teams wait for their turn and cheer politely.\n- (AI 2.A1) T plays one AI-voice clue (prepared and checked in advance) and reminds Ss: AI only helps us; we always check the information with the teacher and the book before we use it.","hs":"- Ss play the game in teams.\n- Ss play in teams and wait for their turn (Digital competence 2.4.CB1a).\n- Ss listen to the AI clue and check it with the picture (AI 2.A1)."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say one thing they can do better now.\n- Homework: Revise Units 1–8; prepare Unit 9: In the grocery store.","hs":"- Ss answer.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":18,"tiet":2,"bai":"Unit 9: In the grocery store – Lesson 1 (Activities 1–2)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Vocabulary: yogurt, yams, yo-yos\n- Phonics: recognise the letter Y, y and say the sound /j/ in the new words\n2. Skills: Listening and speaking\n3. Attributes:\n- Actively take part in pair and group work and love learning English.\n- Health education: Choose suitable food, eat sensibly and do not eat any food without an adult's permission.\n4. Digital Competence (AI 2.A1): Recognise that AI can support listening to and pronouncing English vocabulary through a text-to-speech tool. The teacher has pupils listen to, identify and point to the correct pictures for the words yogurt, yams, yo-yos; pupils practise the letter Y, y and the /j/ sound.","dodung":"- Teacher: Teacher’s Book, audio, flashcards/pictures (Unit 9: In the grocery store), TV or projector, computer, a text-to-speech/pronunciation tool on the teacher’s computer (checked in advance).\n- Pupils: Pupil’s Book, notebooks, pencils.","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a friendly atmosphere and lead in to the new unit.\n* Procedure:\n- T greets the class and asks Ss to sing a song they have learnt.\n- T plays “Slap the board” with the flashcards of Unit 8: In the village (village, van, volleyball).\n- T shows the opening picture of Unit 9: In the grocery store and asks: What can you see?\n- T introduces the unit title and the aims of the lesson.","hs":"- Ss greet T and sing the song.\n- Ss play the game in two teams.\n- Ss look at the picture and answer.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’) – Activity 1: Listen and repeat","gv":"* Aims: Ss will be able to recognise and say the words yogurt, yams, yo-yos and the letter-sound Y, y /j/.\n* Procedure:\n- T uses flashcards/pictures to introduce the new words:\n+ yogurt: sữa chua (picture)\n+ yams: củ khoai mỡ (picture)\n+ yo-yos: đồ chơi yo-yo (picture)\n- T models each word three times; Ss repeat in chorus, in groups and individually.\n- T sticks the flashcards on the board and writes the words under them.\n- T introduces the letter Y, y and the sound /j/ at the beginning of the words; T says the sound slowly and asks Ss to watch T’s mouth.\n- T plays the recording of Activity 1 and pauses after each word for Ss to repeat. T plays it again.\n- T corrects Ss’ pronunciation where necessary.\n- Checking: “What and where” – T rubs out the words one by one; Ss say the words and their places.\n- (AI 2.A1) T types the words yogurt, yams, yo-yos into a text-to-speech tool on the class computer (prepared and checked in advance; Ss use no accounts) and plays them in random order. Ss listen, point to the matching picture and repeat; then they practise the sound /j/.\n- T explains simply: “This voice is made by a computer (AI). It helps us listen, but we always check with the teacher and the book.”","hs":"- Ss look at the flashcards and listen.\n- Ss repeat in chorus, in groups and individually.\n- Ss look at the board.\n- Ss watch, listen and say the sound /j/ and the words.\n- Ss listen to the recording and repeat.\n- Ss correct their pronunciation.\n- Ss play “What and where”.\n- Ss listen to the computer voice, point to the matching picture and repeat the words and the sound /j/ (AI 2.A1).\n- Ss listen to T."},{"ten":"3. Practice (12’) – Activity 2: Point and say","gv":"* Aims: Ss will be able to point at the pictures and say the words correctly.\n* Procedure:\n- T draws Ss’ attention to the pictures in Activity 2.\n- T points at each picture and says the word; Ss repeat.\n- T points at the pictures in random order; Ss say the words.\n- T puts Ss into pairs: one pupil points at a picture, the other says the word; then they swap roles.\n- T goes around the classroom to offer support.\n- T invites some pairs to point and say in front of the class; T praises and corrects them.","hs":"- Ss look at the pictures.\n- Ss listen and repeat.\n- Ss say the words.\n- Ss work in pairs to point and say.\n- Ss ask T for help when needed.\n- Some pairs perform; the class listens and claps."},{"ten":"4. Production (6’) – Game: Clap for the sound","gv":"* Aims: Ss will be able to recognise the sound /j/ in words.\n* Procedure:\n- T says the new words and some known words (jam, pen, van) in random order.\n- Ss clap once when they hear the sound /j/ and stay quiet for the other words.\n- T shows the flashcards quickly (“Flash cards”); Ss say the words.\n- (Health education) T asks: “Is yogurt good for you?” and reminds Ss to choose healthy food and not to eat anything without an adult’s permission.","hs":"- Ss listen carefully.\n- Ss clap when they hear the sound /j/.\n- Ss say the words on the flashcards.\n- Ss answer and listen to T’s advice."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What have we learnt today?” and points at the flashcards for Ss to say the words and the sound /j/.\n- Homework: Practise saying the words at home; prepare Lesson 2 (Activities 3–5).","hs":"- Ss answer and say the words and the sound.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":19,"tiet":1,"bai":"Unit 9: In the grocery store – Lesson 2 (Activities 3–5)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say the chant with the words yams, yogurt, yo-yos and the sound /j/ correctly.\n- Listen and tick the correct pictures.\n- Look at the pictures and write the missing letters/words (Look and write).\n2. Skills: Listening and speaking; reading and writing (Look and write)\n3. Attributes:\n- Work hard and help friends to complete the tasks.\n- Be careful and polite when going shopping with the family.\n4. Digital Competence (1.1.CB1a; 4.2.CB1a): Perform simple information-selection actions on digital learning resources under the teacher's guidance: listen to words/sentences with yo-yos, yams, yogurt, choose or tick the matching pictures and complete the missing words (1.1.CB1a); begin to recognise and protect personal information: do not click on shopping advertisements on their own and do not enter their name, address, phone number or family information without an adult's permission (4.2.CB1a).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 9), TV or projector, computer, digital version of the activities (teacher-controlled)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Lesson 1.\n* Procedure:\n- T greets the class.\n- T plays “Flashcard flash” with yams, yogurt, yo-yos: T flashes a card quickly and Ss say the word.\n- T asks Ss to say the sound /j/ and the words again.\n- T introduces Unit 9 – Lesson 2.","hs":"- Ss greet the teacher.\n- Ss look and say the words.\n- Ss say the sound and the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 3: Listen and chant\n* Aims: Pupils can say the chant with the correct rhythm and pronunciation.\n* Procedure:\n- T shows the chant picture and asks Ss to find yams, yogurt, yo-yos.\n- T plays the chant once; Ss listen and follow in their books.\n- T plays it again line by line; Ss repeat.\n- T has Ss chant and clap to the rhythm, first as a class, then in groups.\n- T invites some groups to perform; the class gives praise.","hs":"- Ss look and point to the things in the picture.\n- Ss listen and follow.\n- Ss repeat line by line.\n- Ss chant and clap as a class and in groups.\n- Some groups perform; the others clap."},{"ten":"3. Practice (10’)","gv":"Activity 4: Listen and tick\n* Aims: Pupils can listen and tick the correct pictures.\n* Procedure:\n- T has Ss look at the pictures and say what they can see.\n- T explains the task and does the example with the class.\n- T plays the audio twice: Ss listen and tick the correct pictures.\n- T has Ss swap books and check their answers in pairs.\n- (Digital competence 1.1.CB1a) T shows Activity 4 on the screen; for each item, T invites a pupil to come up and tick the matching picture on the class device under the teacher's guidance; the class says “Yes” or “No”.\n- T checks the answers with the class (key in the Teacher's Book) and plays the audio again to confirm.","hs":"- Ss look and name the pictures.\n- Ss listen and follow the example.\n- Ss listen and tick.\n- Ss swap books and check in pairs.\n- Ss take turns to tick the picture on the class device; the class checks.\n- Ss correct their answers."},{"ten":"4. Production (10’)","gv":"Activity 5: Look and write\n* Aims: Pupils can look at the pictures and write the missing letters/words.\n* Procedure:\n- T has Ss look at the pictures and say the words.\n- T models the first item on the board.\n- T asks Ss to do the task individually and goes around to help.\n- T invites some Ss to write the answers on the board; the class checks.\n- T has Ss read the completed words aloud.\n- (Digital competence 1.1.CB1a) T shows the Activity 5 pictures on the screen and, after Ss finish writing, clicks to show the missing letters/words one by one.\n- (Digital competence 4.2.CB1a) T shows a picture of a shopping advertisement on a tablet and asks: “Can you click it? Can you type your name or address?” T reminds Ss never to click on shopping ads or enter their name, address, phone number or family information without an adult's permission.","hs":"- Ss look and say the words.\n- Ss watch the example.\n- Ss write in their books.\n- Some Ss write on the board; the class checks.\n- Ss read the words aloud.\n- Ss look at the screen and check their own writing.\n- Ss answer “No!” and repeat the rule: ask an adult first."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the chant once more and name the words of the lesson.\n- T praises Ss and asks them to practise at home and prepare Lesson 3.","hs":"- Ss chant and say the words.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":19,"tiet":2,"bai":"Unit 9: In the grocery store – Lesson 3 (Activities 6–8)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Ask and answer with “What do you want?” – “I want some yams.”, substituting yogurt and yo-yos.\n- Sing the song of Unit 9 with the correct rhythm and actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Speak confidently and listen to friends politely.\n- Life skills/Ethics: speak politely when buying or receiving things; queue, take just enough and be thrifty to avoid waste.\n4. Digital Competence (AI 2.A2): Recognise that AI can support speaking practice and pronunciation checking of simple English communication patterns; under the teacher's guidance, pupils practise “What do you want?” – “I want some yams.” and substitute yogurt, yo-yos.","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 9), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and the chant of Lesson 2.\n* Procedure:\n- T greets the class.\n- T has Ss say the chant of Lesson 2 and revises yams, yogurt, yo-yos with flashcards.\n- T introduces Unit 9 – Lesson 3.","hs":"- Ss greet the teacher.\n- Ss chant and say the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’)","gv":"Activity 6: Listen and repeat\n* Aims: Pupils can understand and say the sentence pattern correctly.\n* Procedure:\n- T shows the pictures of Activity 6 and asks: “Who can you see? What can you see?”\n- T presents the sentence pattern on the board:\n+ What do you want?: Bạn muốn gì?\n+ I want some yams.: Mình muốn một ít khoai mỡ.\n- T models the sentences; Ss repeat in chorus and individually (T uses backchaining for long sentences).\n- T plays the audio: Ss listen, point to the pictures and repeat.","hs":"- Ss look and answer.\n- Ss look at the board and listen.\n- Ss repeat in chorus and individually.\n- Ss listen, point and repeat."},{"ten":"3. Practice (10’)","gv":"Activity 7: Let's talk\n* Aims: Pupils can use the sentence pattern with the words of the unit.\n* Procedure:\n- T points to the pictures and elicits the sentences.\n- T models with a good pupil: T: “What do you want?” – S: “I want some yogurt.”\n- T organises T–Ss, open pairs, then closed pairs: one pupil asks “What do you want?”, the other points to a picture and answers “I want some yams / yogurt / yo-yos.”\n- (AI 2.A2) T opens a teacher-checked AI speaking tool on the class device (teacher's account; pupils use no accounts). A few pupils say “I want some yams.” / “I want some yogurt.” / “I want some yo-yos.” into the microphone; the class compares what the tool shows with the model. T explains that the tool can help check pronunciation, but the teacher gives the final feedback.\n- T invites some pairs to act out in front of the class and gives feedback.","hs":"- Ss look and say the sentences.\n- Ss listen and watch the model.\n- Ss practise in open pairs, then closed pairs.\n- A few Ss say the sentences to the class device; the class compares the result with the model and listens to T's feedback.\n- Some pairs act out; the class listens and claps."},{"ten":"4. Production (8’)","gv":"Activity 8: Let's sing\n* Aims: Pupils can sing the song of the unit with the correct rhythm and actions.\n* Procedure:\n- T shows the song picture and reads the lyrics (Pupil's Book) line by line.\n- T plays the song; Ss listen and follow in their books.\n- T plays it again; Ss sing along and do actions.\n- T has groups take turns to sing; the class claps and praises.\n- T sets up a mini “grocery store” role-play: one pupil is the shop assistant, the others queue and say “I want some yams, please.” – “Thank you.” T reminds Ss to queue, take just enough and not waste food.","hs":"- Ss look, listen and repeat the lyrics.\n- Ss listen and follow.\n- Ss sing along and do actions.\n- Ss sing in groups and praise their friends.\n- Ss queue, ask politely, say “Thank you” and take just enough."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the sentence pattern once more: “What do you want?” – “I want some yams.”\n- T praises Ss and asks them to practise the sentences and the song at home.","hs":"- Ss say the sentences.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":20,"tiet":1,"bai":"Unit 10: At the zoo – Lesson 1 (Activities 1–2)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise and say the words: zoo, zebra, zebu.\n- Recognise the letter Z, z and say the sound /z/ in zoo, zebra, zebu.\n2. Skills: Listening and speaking\n3. Attributes:\n- Take an active part in the lesson and cooperate with friends in pairs and groups.\n- Animal protection: love animals; do not tease them, throw food at them or frighten them when visiting the zoo.\n4. Digital Competence (AI 2.A1): Recognise that AI can support listening, image recognition and pronunciation of simple English vocabulary: listen to model words and look at the pictures to identify zoo, zebra, zebu, and practise the letter Z, z and the /z/ sound.","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 10), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a friendly atmosphere and revise the previous unit.\n* Procedure:\n- T greets the class and asks: “How are you today?”\n- T plays “Slap the board” with yams, yogurt, yo-yos (Unit 9).\n- T shows the Unit 10 opening picture and asks: “Where are they? What can you see?”\n- T introduces the new lesson: Unit 10: At the zoo – Lesson 1.","hs":"- Ss greet the teacher and answer.\n- Ss play the game in two teams.\n- Ss look at the picture and answer.\n- Ss listen and open their books."},{"ten":"2. Presentation (12’)","gv":"Activity 1: Listen and repeat\n* Aims: Pupils can recognise and say the words zoo, zebra, zebu correctly.\n* Procedure:\n- T shows the flashcards/pictures one by one and elicits the new words:\n+ zoo: sở thú (picture)\n+ zebra: con ngựa vằn (picture)\n+ zebu: con bò u (picture)\n- T models each word three times.\n- T has Ss repeat in chorus, in groups and individually.\n- (AI 2.A1) T plays a teacher-checked AI text-to-speech model of zoo, zebra, zebu on the class device (teacher's account only) while showing the pictures; Ss listen, point to the correct picture and repeat; T asks: “Does it sound like the teacher's model?” and corrects where needed.\n- T plays the audio of Activity 1 twice: Ss listen, point to the pictures and repeat.\n- Checking: T plays “What and where” with the new words.","hs":"- Ss look at the pictures and guess the words.\n- Ss listen to the teacher.\n- Ss repeat in chorus, in groups and individually.\n- Ss listen to the AI model, point to the picture and repeat.\n- Ss listen, point and repeat.\n- Ss play the game and say the words."},{"ten":"3. Practice (10’)","gv":"Activity 2: Letter and sound – Z, z /z/\n* Aims: Pupils can recognise Z, z and say the sound /z/ correctly.\n* Procedure:\n- T writes Z, z on the board and says /z/ several times, showing the mouth shape.\n- T plays the audio of Activity 2: Ss listen and repeat the letter(s), the sound and the words.\n- T underlines the letter z in zoo, zebra, zebu and has Ss say the words again, stressing /z/.\n- T has Ss write Z, z in the air and on their desks while saying the sound.\n- T plays “Listen and clap”: T says some familiar words; Ss clap when they hear /z/.\n- T corrects pronunciation where necessary.","hs":"- Ss look, listen and say /z/.\n- Ss listen and repeat.\n- Ss read the words, stressing the sound.\n- Ss write in the air and say the sound.\n- Ss listen and clap when they hear the sound.\n- Ss correct their pronunciation."},{"ten":"4. Production (6’)","gv":"Point and say – Guess the picture\n* Aims: Pupils can use the new words in pairs and in a game.\n* Procedure:\n- T puts Ss in pairs: one points to a picture in the Pupil's Book, the other says the word.\n- T plays “Guess the picture”: T slowly shows part of a flashcard; Ss guess the word.\n- T shows pictures of good and bad behaviour at the zoo (feeding, teasing, shouting at animals); Ss say “Yes” or “No”. T reminds Ss to love animals and not to tease them, throw food at them or frighten them.","hs":"- Ss work in pairs to point and say.\n- Ss guess and say the words.\n- Ss look and say “Yes” or “No”."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What words have you learnt today? What sound is it?”\n- T praises Ss and asks them to practise the words at home and prepare Lesson 2.","hs":"- Ss say the words and the sound.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":20,"tiet":2,"bai":"Unit 10: At the zoo – Lesson 2 (Activities 3–5)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say the chant with the words zoo, zebra, zebu and the sound /z/ correctly.\n- Listen and circle the correct pictures.\n- Look at the pictures and write the missing letters/words (Look and write).\n2. Skills: Listening and speaking; reading and writing (Look and write)\n3. Attributes:\n- Work hard and help friends to complete the tasks.\n- Life skills: queue, keep order and follow signs when visiting public places.\n4. Digital Competence (1.1.CB1a): Perform simple information-selection actions on digital learning resources under the teacher's guidance: listen to the chant/sentences with zoo, zebra, zebu, choose or circle the matching pictures and complete the missing words.","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 10), TV or projector, computer, digital version of the activities (teacher-controlled)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Lesson 1.\n* Procedure:\n- T greets the class.\n- T plays “Flashcard flash” with zoo, zebra, zebu: T flashes a card quickly and Ss say the word.\n- T asks Ss to say the sound /z/ and the words again.\n- T introduces Unit 10 – Lesson 2.","hs":"- Ss greet the teacher.\n- Ss look and say the words.\n- Ss say the sound and the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 3: Listen and chant\n* Aims: Pupils can say the chant with the correct rhythm and pronunciation.\n* Procedure:\n- T shows the chant picture and asks Ss to find zoo, zebra, zebu.\n- T plays the chant once; Ss listen and follow in their books.\n- T plays it again line by line; Ss repeat.\n- T has Ss chant and clap to the rhythm, first as a class, then in groups.\n- T invites some groups to perform; the class gives praise.","hs":"- Ss look and point to the things in the picture.\n- Ss listen and follow.\n- Ss repeat line by line.\n- Ss chant and clap as a class and in groups.\n- Some groups perform; the others clap."},{"ten":"3. Practice (10’)","gv":"Activity 4: Listen and circle\n* Aims: Pupils can listen and circle the correct pictures.\n* Procedure:\n- T has Ss look at the pictures and say what they can see.\n- T explains the task and does the example with the class.\n- T plays the audio twice: Ss listen and circle the correct pictures.\n- T has Ss swap books and check their answers in pairs.\n- (Digital competence 1.1.CB1a) T shows Activity 4 on the screen; for each item, T invites a pupil to come up and circle the matching picture on the class device under the teacher's guidance; the class says “Yes” or “No”.\n- T checks the answers with the class (key in the Teacher's Book) and plays the audio again to confirm.","hs":"- Ss look and name the pictures.\n- Ss listen and follow the example.\n- Ss listen and circle.\n- Ss swap books and check in pairs.\n- Ss take turns to circle the picture on the class device; the class checks.\n- Ss correct their answers."},{"ten":"4. Production (10’)","gv":"Activity 5: Look and write\n* Aims: Pupils can look at the pictures and write the missing letters/words.\n* Procedure:\n- T has Ss look at the pictures and say the words.\n- T models the first item on the board.\n- T asks Ss to do the task individually and goes around to help.\n- T invites some Ss to write the answers on the board; the class checks.\n- T has Ss read the completed words aloud.\n- (Digital competence 1.1.CB1a) T shows the Activity 5 pictures on the screen and, after Ss finish writing, clicks to show the missing letters/words one by one.\n- T shows a picture of a zoo gate with a queue and a sign and asks: “What should we do?” T reminds Ss to queue, keep order and follow the signs in public places.","hs":"- Ss look and say the words.\n- Ss watch the example.\n- Ss write in their books.\n- Some Ss write on the board; the class checks.\n- Ss read the words aloud.\n- Ss look at the screen and check their own writing.\n- Ss answer and repeat: queue, keep order, follow the signs."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the chant once more and name the words of the lesson.\n- T praises Ss and asks them to practise at home and prepare Lesson 3.","hs":"- Ss chant and say the words.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":21,"tiet":1,"bai":"Unit 10: At the zoo – Lesson 3 (Activities 6–8)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Ask and answer with “Do you like the zoo?” – “Yes, I do.” / “No, I don't.”, substituting zebra and zebu where they match the pictures.\n- Sing the song of Unit 10 with the correct rhythm and actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Speak confidently and listen to friends politely.\n- Environmental protection/biodiversity: understand that animals need to be protected and to live in a clean, safe environment; do not litter when visiting the zoo.\n4. Digital Competence (AI 2.A2): Recognise that AI can support speaking practice and pronunciation checking of simple English communication patterns; under the teacher's guidance, pupils practise “Do you like the zoo?” – “Yes, I do.” / “No, I don't.” and substitute zebra, zebu where they match the pictures.","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 10), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and the chant of Lesson 2.\n* Procedure:\n- T greets the class.\n- T has Ss say the chant of Lesson 2 and revises zoo, zebra, zebu with flashcards.\n- T introduces Unit 10 – Lesson 3.","hs":"- Ss greet the teacher.\n- Ss chant and say the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’)","gv":"Activity 6: Listen and repeat\n* Aims: Pupils can understand and say the sentence pattern correctly.\n* Procedure:\n- T shows the pictures of Activity 6 and asks: “Who can you see? What can you see?”\n- T presents the sentence pattern on the board:\n+ Do you like the zoo?: Bạn có thích sở thú không?\n+ Yes, I do.: Có, mình thích.\n+ No, I don't.: Không, mình không thích.\n- T models the sentences; Ss repeat in chorus and individually (T uses backchaining for long sentences).\n- T plays the audio: Ss listen, point to the pictures and repeat.","hs":"- Ss look and answer.\n- Ss look at the board and listen.\n- Ss repeat in chorus and individually.\n- Ss listen, point and repeat."},{"ten":"3. Practice (10’)","gv":"Activity 7: Let's talk\n* Aims: Pupils can use the sentence pattern with the words of the unit.\n* Procedure:\n- T points to the pictures and elicits the sentences.\n- T models with a good pupil: T: “Do you like the zebra?” – S: “Yes, I do.”\n- T organises T–Ss, open pairs, then closed pairs: one pupil points to a picture and asks “Do you like the zoo / zebra / zebu?”, the other answers “Yes, I do.” or “No, I don't.”\n- (AI 2.A2) T opens a teacher-checked AI speaking tool on the class device (teacher's account; pupils use no accounts). A few pupils say “Do you like the zoo?” – “Yes, I do.” / “No, I don't.” into the microphone; the class compares what the tool shows with the model. T explains that the tool can help check pronunciation, but the teacher gives the final feedback.\n- T invites some pairs to act out in front of the class and gives feedback.","hs":"- Ss look and say the sentences.\n- Ss listen and watch the model.\n- Ss practise in open pairs, then closed pairs.\n- A few Ss say the sentences to the class device; the class compares the result with the model and listens to T's feedback.\n- Some pairs act out; the class listens and claps."},{"ten":"4. Production (8’)","gv":"Activity 8: Let's sing\n* Aims: Pupils can sing the song of the unit with the correct rhythm and actions.\n* Procedure:\n- T shows the song picture and reads the lyrics (Pupil's Book) line by line.\n- T plays the song; Ss listen and follow in their books.\n- T plays it again; Ss sing along and do actions.\n- T has groups take turns to sing; the class claps and praises.\n- After the song, T shows a picture of a clean zoo and a zoo with litter and asks: “Which zoo is good for the zebras?” T reminds Ss that animals need a clean, safe home and that we never litter at the zoo.","hs":"- Ss look, listen and repeat the lyrics.\n- Ss listen and follow.\n- Ss sing along and do actions.\n- Ss sing in groups and praise their friends.\n- Ss choose the clean zoo and promise not to litter."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the sentence pattern once more: “Do you like the zoo?” – “Yes, I do.” / “No, I don't.”\n- T praises Ss and asks them to practise the sentences and the song at home.","hs":"- Ss say the sentences.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":21,"tiet":2,"bai":"Fun time 3 – Lesson 1","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Revise the words of Units 9–10: yams, yogurt, yo-yos, zoo, zebra, zebu.\n- Revise the sounds /j/ (Y, y) and /z/ (Z, z).\n- Revise the sentence patterns: “What do you want?” – “I want some yams.”; “Do you like the zoo?” – “Yes, I do.” / “No, I don't.”.\n2. Skills: Listening and speaking\n3. Attributes:\n- Cooperate, play honestly and respect friends in team games.\n- Wait for their turn and cheer for other teams.\n4. Digital Competence (2.4.CB1a; AI 2.A2): Take part in simple digital games in groups, wait for their turn, choose answers and respond politely (2.4.CB1a); compare a teacher-checked AI voice/image challenge with the pictures, words and sentence patterns they have learnt and do not treat AI output as the default answer (AI 2.A2).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Units 9–10), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only), a simple class quiz on the screen\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a fun atmosphere and lead in to Fun time.\n* Procedure:\n- T greets the class and has Ss sing a song or say a chant from Units 9–10.\n- T introduces Fun time: “Today we play games with the English we have learnt.”","hs":"- Ss sing or chant together.\n- Ss listen and get ready."},{"ten":"2. Presentation (10’)","gv":"Game 1: Slap the board – words and sounds\n* Aims: Pupils can recognise and say the words and sounds of Units 9–10.\n* Procedure:\n- T sticks the flashcards of yams, yogurt, yo-yos, zoo, zebra, zebu on the board; Ss say the words.\n- T divides the class into two teams; T says a word or a sound, and one pupil from each team slaps the right card.\n- T asks the winner to say the word and its sound again.\n- T invites some Ss to sort the cards into the /j/ words and the /z/ words.","hs":"- Ss look and say the words.\n- Ss play in two teams.\n- Ss say the word and the sound.\n- Ss come to the board and sort the cards."},{"ten":"3. Practice (8’)","gv":"Game 2: Is it right? – AI challenge\n* Aims: Pupils can check AI voices/images against what they have learnt.\n* Procedure:\n- (AI 2.A2) T shows some AI voices/images prepared and checked in advance on the class device; most match the book, one or two do not (e.g. an AI voice says “zebra” under a picture of a zebu).\n- For each one, T asks: “Is it right?” Ss compare it with the pictures in the Pupil's Book and answer “Yes” or “No”.\n- When the answer is “No”, T asks Ss to give the correct word or sentence.\n- T explains: AI can help us, but it can be wrong; we check with the book and the teacher.","hs":"- Ss look and listen carefully.\n- Ss compare with the book and answer “Yes” or “No”.\n- Ss say the correct word or sentence.\n- Ss listen and repeat the rule: check with the book and the teacher."},{"ten":"4. Production (10’)","gv":"Game 3: Team quiz on the class screen\n* Aims: Pupils can use the words and sentence patterns in a team game.\n* Procedure:\n- (Digital competence 2.4.CB1a) T shows a teacher-controlled quiz on the screen with pictures and questions using “What do you want?” – “I want some yams.” and “Do you like the zoo?” – “Yes, I do.” / “No, I don't.”.\n- Teams take turns: one pupil comes up, listens to the question, chooses the answer on the class device and says the sentence.\n- T reminds Ss to wait for their turn and say “Good job!” or “Try again!” to friends politely.\n- T counts the points and praises both teams for playing honestly and respecting friends.","hs":"- Ss look at the quiz on the screen.\n- Ss take turns in their teams, choose the answer and say the sentence.\n- Ss wait for their turn and respond politely.\n- Ss cheer for both teams."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to name their favourite game and say one sentence they have practised.\n- T praises Ss and asks them to revise Units 9–10 at home.","hs":"- Ss answer and say a sentence.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":22,"tiet":1,"bai":"Fun time 3 – Lesson 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Revise the words of Units 9–10: yams, yogurt, yo-yos, zoo, zebra, zebu.\n- Revise the sounds /j/ (Y, y) and /z/ (Z, z).\n- Revise the sentence patterns: “What do you want?” – “I want some yams.”; “Do you like the zoo?” – “Yes, I do.” / “No, I don't.”.\n2. Skills: Listening and speaking\n3. Attributes:\n- Check their answers carefully and correct mistakes honestly.\n- Digital safety: use the class device without a personal account and never enter private information.\n4. Digital Competence (1.2.CB1a; AI 2.A1): Observe, listen to and select simple information on teacher-controlled digital learning resources, and check again when an answer does not match the picture/audio (1.2.CB1a); recognise that AI can generate voices or suggest answers but is sometimes wrong, so they ask the teacher or check the Pupil's Book before correcting their work (AI 2.A1).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Units 9–10), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only), digital version of the activities (teacher-controlled)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words through a chant.\n* Procedure:\n- T greets the class and has Ss say a chant from Units 9–10.\n- T plays “Flashcard flash” with yams, yogurt, yo-yos, zoo, zebra, zebu.","hs":"- Ss say the chant and clap.\n- Ss look and say the words."},{"ten":"2. Presentation (8’)","gv":"Letters and sounds\n* Aims: Pupils can recognise the letters and sounds /j/ (Y, y) and /z/ (Z, z).\n* Procedure:\n- T writes the letters on the board and says each sound; Ss repeat.\n- T plays “Odd one out”: T says three words; Ss say the word with a different sound.\n- T writes some words with a missing letter on the board; Ss come up and write the missing letter.","hs":"- Ss listen and repeat the sounds.\n- Ss listen and say the odd word.\n- Ss write the missing letters and read the words."},{"ten":"3. Practice (10’)","gv":"Listen and choose\n* Aims: Pupils can listen and choose the correct picture on a digital resource.\n* Procedure:\n- (Digital competence 1.2.CB1a) T plays the audio of words and sentences on a teacher-controlled digital resource; for each item Ss look at the pictures on the screen.\n- T invites Ss to choose the matching picture on the class device.\n- When an answer does not match the picture/audio, T plays the audio again and asks Ss to check once more before choosing again.\n- T has the class repeat each correct word or sentence.","hs":"- Ss look and listen.\n- Ss take turns to choose the picture.\n- Ss listen again, check and choose again.\n- Ss repeat in chorus."},{"ten":"4. Production (10’)","gv":"Check the AI – Ask and answer\n* Aims: Pupils can check an AI suggestion and use the sentence patterns in pairs.\n* Procedure:\n- (AI 2.A1) T shows some AI voice/answer suggestions prepared in advance on the class device; one is wrong (e.g. the AI suggestion says “I want some yogurt.” under a picture of yams).\n- T asks: “Is the AI right?” Ss check with the Pupil's Book and ask the teacher before correcting it.\n- T reminds Ss: no personal account is needed and we never type our name, address or other private information.\n- T has Ss ask and answer in pairs with “What do you want?” – “I want some yams.” and “Do you like the zoo?” – “Yes, I do.” / “No, I don't.”, using the pictures.\n- T invites some pairs to perform and gives feedback.","hs":"- Ss look and listen.\n- Ss check with the book, ask the teacher and give the correct answer.\n- Ss listen and remember the safety rule.\n- Ss ask and answer in pairs.\n- Some pairs perform; the class claps."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What can you say now?” and reviews the words, sounds and sentences.\n- T praises Ss and asks them to prepare the next unit.","hs":"- Ss answer and say the sentences.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":22,"tiet":2,"bai":"Unit 11: In the playground – Lesson 1 (Activities 1–2)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise and say the words: riding, driving, sliding.\n- Recognise the letter I, i and say the sound /aɪ/ in riding, driving, sliding.\n2. Skills: Listening and speaking\n3. Attributes:\n- Take an active part in the lesson and cooperate with friends in pairs and groups.\n- Road safety/Play safety: wear a helmet when riding a bicycle and follow safety rules at the playground.\n4. Digital Competence (AI 2.A1): Recognise that AI can support listening, image recognition and pronunciation of simple English words/phrases: listen and look at the pictures to identify riding, driving, sliding, and practise the letter I, i and the /aɪ/ sound in the target words.","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 11), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a friendly atmosphere and revise the previous unit.\n* Procedure:\n- T greets the class and asks: “How are you today?”\n- T plays “Slap the board” with zoo, zebra, zebu (Unit 10).\n- T shows the Unit 11 opening picture and asks: “Where are they? What can you see?”\n- T introduces the new lesson: Unit 11: In the playground – Lesson 1.","hs":"- Ss greet the teacher and answer.\n- Ss play the game in two teams.\n- Ss look at the picture and answer.\n- Ss listen and open their books."},{"ten":"2. Presentation (12’)","gv":"Activity 1: Listen and repeat\n* Aims: Pupils can recognise and say the words riding, driving, sliding correctly.\n* Procedure:\n- T shows the flashcards/pictures one by one and elicits the new words:\n+ riding: đang đạp xe (picture)\n+ driving: đang lái xe (picture)\n+ sliding: đang chơi cầu trượt (picture)\n- T models each word three times.\n- T has Ss repeat in chorus, in groups and individually.\n- (AI 2.A1) T plays a teacher-checked AI text-to-speech model of riding, driving, sliding on the class device (teacher's account only) while showing the pictures; Ss listen, point to the correct picture and repeat; T asks: “Does it sound like the teacher's model?” and corrects where needed.\n- T plays the audio of Activity 1 twice: Ss listen, point to the pictures and repeat.\n- Checking: T plays “What and where” with the new words.","hs":"- Ss look at the pictures and guess the words.\n- Ss listen to the teacher.\n- Ss repeat in chorus, in groups and individually.\n- Ss listen to the AI model, point to the picture and repeat.\n- Ss listen, point and repeat.\n- Ss play the game and say the words."},{"ten":"3. Practice (10’)","gv":"Activity 2: Letter and sound – I, i /aɪ/\n* Aims: Pupils can recognise I, i and say the sound /aɪ/ correctly.\n* Procedure:\n- T writes I, i on the board and says /aɪ/ several times, showing the mouth shape.\n- T plays the audio of Activity 2: Ss listen and repeat the letter(s), the sound and the words.\n- T underlines the letter i in riding, driving, sliding and has Ss say the words again, stressing /aɪ/.\n- T has Ss write I, i in the air and on their desks while saying the sound.\n- T plays “Listen and clap”: T says some familiar words; Ss clap when they hear /aɪ/.\n- T corrects pronunciation where necessary.","hs":"- Ss look, listen and say /aɪ/.\n- Ss listen and repeat.\n- Ss read the words, stressing the sound.\n- Ss write in the air and say the sound.\n- Ss listen and clap when they hear the sound.\n- Ss correct their pronunciation."},{"ten":"4. Production (6’)","gv":"Point and say – Guess the picture\n* Aims: Pupils can use the new words in pairs and in a game.\n* Procedure:\n- T puts Ss in pairs: one points to a picture in the Pupil's Book, the other says the word.\n- T plays “Guess the picture”: T slowly shows part of a flashcard; Ss guess the word.\n- T shows a picture of a child riding a bike with a helmet and one without; T asks: “Who is safe?” and reminds Ss to wear a helmet when riding a bike and to follow the safety rules at the playground.","hs":"- Ss work in pairs to point and say.\n- Ss guess and say the words.\n- Ss point to the safe child and repeat the safety rules."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What words have you learnt today? What sound is it?”\n- T praises Ss and asks them to practise the words at home and prepare Lesson 2.","hs":"- Ss say the words and the sound.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":23,"tiet":1,"bai":"Unit 11: In the playground – Lesson 2 (Activities 3–5)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say the chant with the words riding, driving, sliding and the sound /aɪ/ correctly.\n- Listen and tick the correct pictures.\n- Look at the pictures and write the missing letters/words (Look and write).\n2. Skills: Listening and speaking; reading and writing (Look and write)\n3. Attributes:\n- Work hard and help friends to complete the tasks.\n- Physical education: enjoy suitable physical activity, play in the right areas and wait for their turn when using playground equipment.\n4. Digital Competence (1.1.CB1a): Perform simple information-selection actions on digital learning resources under the teacher's guidance: listen to the chant/sentences with riding, driving, sliding, choose/tick the matching pictures and complete the missing words.","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 11), TV or projector, computer, digital version of the activities (teacher-controlled)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Lesson 1.\n* Procedure:\n- T greets the class.\n- T plays “Flashcard flash” with riding, driving, sliding: T flashes a card quickly and Ss say the word.\n- T asks Ss to say the sound /aɪ/ and the words again.\n- T introduces Unit 11 – Lesson 2.","hs":"- Ss greet the teacher.\n- Ss look and say the words.\n- Ss say the sound and the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 3: Listen and chant\n* Aims: Pupils can say the chant with the correct rhythm and pronunciation.\n* Procedure:\n- T shows the chant picture and asks Ss to find riding, driving, sliding.\n- T plays the chant once; Ss listen and follow in their books.\n- T plays it again line by line; Ss repeat.\n- T has Ss chant and clap to the rhythm, first as a class, then in groups.\n- T invites some groups to perform; the class gives praise.","hs":"- Ss look and point to the things in the picture.\n- Ss listen and follow.\n- Ss repeat line by line.\n- Ss chant and clap as a class and in groups.\n- Some groups perform; the others clap."},{"ten":"3. Practice (10’)","gv":"Activity 4: Listen and tick\n* Aims: Pupils can listen and tick the correct pictures.\n* Procedure:\n- T has Ss look at the pictures and say what they can see.\n- T explains the task and does the example with the class.\n- T plays the audio twice: Ss listen and tick the correct pictures.\n- T has Ss swap books and check their answers in pairs.\n- (Digital competence 1.1.CB1a) T shows Activity 4 on the screen; for each item, T invites a pupil to come up and tick the matching picture on the class device under the teacher's guidance; the class says “Yes” or “No”.\n- T checks the answers with the class (key in the Teacher's Book) and plays the audio again to confirm.","hs":"- Ss look and name the pictures.\n- Ss listen and follow the example.\n- Ss listen and tick.\n- Ss swap books and check in pairs.\n- Ss take turns to tick the picture on the class device; the class checks.\n- Ss correct their answers."},{"ten":"4. Production (10’)","gv":"Activity 5: Look and write\n* Aims: Pupils can look at the pictures and write the missing letters/words.\n* Procedure:\n- T has Ss look at the pictures and say the words.\n- T models the first item on the board.\n- T asks Ss to do the task individually and goes around to help.\n- T invites some Ss to write the answers on the board; the class checks.\n- T has Ss read the completed words aloud.\n- (Digital competence 1.1.CB1a) T shows the Activity 5 pictures on the screen and, after Ss finish writing, clicks to show the missing letters/words one by one.\n- T has Ss mime riding, driving and sliding at their desks, then asks: “Where do we play? Do we wait for our turn at the slide?” T encourages safe exercise in the right areas.","hs":"- Ss look and say the words.\n- Ss watch the example.\n- Ss write in their books.\n- Some Ss write on the board; the class checks.\n- Ss read the words aloud.\n- Ss look at the screen and check their own writing.\n- Ss mime the actions and answer: “Yes, we wait for our turn.”"},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the chant once more and name the words of the lesson.\n- T praises Ss and asks them to practise at home and prepare Lesson 3.","hs":"- Ss chant and say the words.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":23,"tiet":2,"bai":"Unit 11: In the playground – Lesson 3 (Activities 6–8)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say what people are doing with “They're driving cars.”, “They're riding bikes.” and “They're sliding.”\n- Sing the song of Unit 11 with the correct rhythm and actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Speak confidently and listen to friends politely.\n- Life skills: cooperate, share the play space and remind friends to follow safety rules at the playground.\n4. Digital Competence (AI 2.A2): Recognise that AI can support speaking practice and pronunciation checking of simple English sentence patterns; under the teacher's guidance, pupils practise “They're driving cars.” and substitute “They're riding bikes.” / “They're sliding.”","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 11), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and the chant of Lesson 2.\n* Procedure:\n- T greets the class.\n- T has Ss say the chant of Lesson 2 and revises riding, driving, sliding with flashcards.\n- T introduces Unit 11 – Lesson 3.","hs":"- Ss greet the teacher.\n- Ss chant and say the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’)","gv":"Activity 6: Listen and repeat\n* Aims: Pupils can understand and say the sentence pattern correctly.\n* Procedure:\n- T shows the pictures of Activity 6 and asks: “Who can you see? What can you see?”\n- T presents the sentence pattern on the board:\n+ They're driving cars.: Họ đang lái ô tô.\n+ They're riding bikes.: Họ đang đạp xe đạp.\n+ They're sliding.: Họ đang chơi cầu trượt.\n- T models the sentences; Ss repeat in chorus and individually (T uses backchaining for long sentences).\n- T plays the audio: Ss listen, point to the pictures and repeat.","hs":"- Ss look and answer.\n- Ss look at the board and listen.\n- Ss repeat in chorus and individually.\n- Ss listen, point and repeat."},{"ten":"3. Practice (10’)","gv":"Activity 7: Let's talk\n* Aims: Pupils can use the sentence pattern with the words of the unit.\n* Procedure:\n- T points to the pictures and elicits the sentences.\n- T models with a good pupil: T points to a picture – S: “They're riding bikes.”\n- T organises T–Ss, open pairs, then closed pairs: one pupil points to a picture, the other says “They're driving cars.” / “They're riding bikes.” / “They're sliding.”\n- (AI 2.A2) T opens a teacher-checked AI speaking tool on the class device (teacher's account; pupils use no accounts). A few pupils say “They're driving cars.” / “They're riding bikes.” / “They're sliding.” into the microphone; the class compares what the tool shows with the model. T explains that the tool can help check pronunciation, but the teacher gives the final feedback.\n- T invites some pairs to act out in front of the class and gives feedback.","hs":"- Ss look and say the sentences.\n- Ss listen and watch the model.\n- Ss practise in open pairs, then closed pairs.\n- A few Ss say the sentences to the class device; the class compares the result with the model and listens to T's feedback.\n- Some pairs act out; the class listens and claps."},{"ten":"4. Production (8’)","gv":"Activity 8: Let's sing\n* Aims: Pupils can sing the song of the unit with the correct rhythm and actions.\n* Procedure:\n- T shows the song picture and reads the lyrics (Pupil's Book) line by line.\n- T plays the song; Ss listen and follow in their books.\n- T plays it again; Ss sing along and do actions.\n- T has groups take turns to sing; the class claps and praises.\n- T asks: “What do we do when many friends want to use the slide?” T encourages Ss to share the play space, take turns and remind friends to play safely.","hs":"- Ss look, listen and repeat the lyrics.\n- Ss listen and follow.\n- Ss sing along and do actions.\n- Ss sing in groups and praise their friends.\n- Ss answer and give examples of sharing and playing safely."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the sentence pattern once more: “They're driving cars.” / “They're riding bikes.” / “They're sliding.”\n- T praises Ss and asks them to practise the sentences and the song at home.","hs":"- Ss say the sentences.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":24,"tiet":1,"bai":"Unit 12: At the café – Lesson 1 (Activities 1–2)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise and say the words: cake, grapes, table.\n- Recognise the letter A, a and say the sound /eɪ/ in cake, grapes, table.\n2. Skills: Listening and speaking\n3. Attributes:\n- Take an active part in the lesson and cooperate with friends in pairs and groups.\n- Health education: choose and eat suitable amounts of food, prefer fruit and wash hands before eating.\n4. Digital Competence (AI 2.A1): Recognise that AI can support listening, image recognition and pronunciation of English vocabulary: listen to and identify the words cake, grapes, table, point to the matching pictures and practise the sound A, a – /eɪ/.","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 12), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a friendly atmosphere and revise the previous unit.\n* Procedure:\n- T greets the class and asks: “How are you today?”\n- T plays “Slap the board” with riding, driving, sliding (Unit 11).\n- T shows the Unit 12 opening picture and asks: “Where are they? What can you see?”\n- T introduces the new lesson: Unit 12: At the café – Lesson 1.","hs":"- Ss greet the teacher and answer.\n- Ss play the game in two teams.\n- Ss look at the picture and answer.\n- Ss listen and open their books."},{"ten":"2. Presentation (12’)","gv":"Activity 1: Listen and repeat\n* Aims: Pupils can recognise and say the words cake, grapes, table correctly.\n* Procedure:\n- T shows the flashcards/pictures one by one and elicits the new words:\n+ cake: cái bánh ngọt (picture)\n+ grapes: quả nho (picture)\n+ table: cái bàn (picture)\n- T models each word three times.\n- T has Ss repeat in chorus, in groups and individually.\n- (AI 2.A1) T plays a teacher-checked AI text-to-speech model of cake, grapes, table on the class device (teacher's account only) while showing the pictures; Ss listen, point to the correct picture and repeat; T asks: “Does it sound like the teacher's model?” and corrects where needed.\n- T plays the audio of Activity 1 twice: Ss listen, point to the pictures and repeat.\n- Checking: T plays “What and where” with the new words.","hs":"- Ss look at the pictures and guess the words.\n- Ss listen to the teacher.\n- Ss repeat in chorus, in groups and individually.\n- Ss listen to the AI model, point to the picture and repeat.\n- Ss listen, point and repeat.\n- Ss play the game and say the words."},{"ten":"3. Practice (10’)","gv":"Activity 2: Letter and sound – A, a /eɪ/\n* Aims: Pupils can recognise A, a and say the sound /eɪ/ correctly.\n* Procedure:\n- T writes A, a on the board and says /eɪ/ several times, showing the mouth shape.\n- T plays the audio of Activity 2: Ss listen and repeat the letter(s), the sound and the words.\n- T underlines the letter a in cake, grapes, table and has Ss say the words again, stressing /eɪ/.\n- T has Ss write A, a in the air and on their desks while saying the sound.\n- T plays “Listen and clap”: T says some familiar words; Ss clap when they hear /eɪ/.\n- T corrects pronunciation where necessary.","hs":"- Ss look, listen and say /eɪ/.\n- Ss listen and repeat.\n- Ss read the words, stressing the sound.\n- Ss write in the air and say the sound.\n- Ss listen and clap when they hear the sound.\n- Ss correct their pronunciation."},{"ten":"4. Production (6’)","gv":"Point and say – Guess the picture\n* Aims: Pupils can use the new words in pairs and in a game.\n* Procedure:\n- T puts Ss in pairs: one points to a picture in the Pupil's Book, the other says the word.\n- T plays “Guess the picture”: T slowly shows part of a flashcard; Ss guess the word.\n- T asks: “Which is better for a snack every day: grapes or cake?” T encourages Ss to eat fruit, not too many sweet things, and to wash their hands before eating.","hs":"- Ss work in pairs to point and say.\n- Ss guess and say the words.\n- Ss answer “Grapes!” and repeat the healthy habits."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What words have you learnt today? What sound is it?”\n- T praises Ss and asks them to practise the words at home and prepare Lesson 2.","hs":"- Ss say the words and the sound.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":24,"tiet":2,"bai":"Unit 12: At the café – Lesson 2 (Activities 3–5)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say the chant with the words cake, grapes, table and the sound /eɪ/ correctly.\n- Listen and circle the correct pictures.\n- Look at the pictures and write the missing letters/words (Look and write).\n2. Skills: Listening and speaking; reading and writing (Look and write)\n3. Attributes:\n- Work hard and help friends to complete the tasks.\n- Ethics – life skills: keep order, do not spill food and do not waste food at a café or restaurant.\n4. Digital Competence (1.1.CB1a; 4.1.CB1a): Perform simple information-selection actions on digital learning resources under the teacher's guidance: listen, look at the pictures, choose/circle the correct answer and match cake, grapes, table with the pictures (1.1.CB1a); begin to build safe habits with digital devices: only operate when instructed, sit properly and keep a suitable distance from the screen (4.1.CB1a).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 12), TV or projector, computer, digital version of the activities (teacher-controlled)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Lesson 1.\n* Procedure:\n- T greets the class.\n- T plays “Flashcard flash” with cake, grapes, table: T flashes a card quickly and Ss say the word.\n- T asks Ss to say the sound /eɪ/ and the words again.\n- T introduces Unit 12 – Lesson 2.","hs":"- Ss greet the teacher.\n- Ss look and say the words.\n- Ss say the sound and the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 3: Listen and chant\n* Aims: Pupils can say the chant with the correct rhythm and pronunciation.\n* Procedure:\n- T shows the chant picture and asks Ss to find cake, grapes, table.\n- T plays the chant once; Ss listen and follow in their books.\n- T plays it again line by line; Ss repeat.\n- T has Ss chant and clap to the rhythm, first as a class, then in groups.\n- T invites some groups to perform; the class gives praise.","hs":"- Ss look and point to the things in the picture.\n- Ss listen and follow.\n- Ss repeat line by line.\n- Ss chant and clap as a class and in groups.\n- Some groups perform; the others clap."},{"ten":"3. Practice (10’)","gv":"Activity 4: Listen and circle\n* Aims: Pupils can listen and circle the correct pictures.\n* Procedure:\n- T has Ss look at the pictures and say what they can see.\n- T explains the task and does the example with the class.\n- T plays the audio twice: Ss listen and circle the correct pictures.\n- T has Ss swap books and check their answers in pairs.\n- (Digital competence 4.1.CB1a) Before Ss come up to the class device, T reminds them: only touch the screen when the teacher says so, sit properly and keep a suitable distance from the screen.\n- (Digital competence 1.1.CB1a) T shows Activity 4 on the screen; for each item, T invites a pupil to come up and circle the matching picture on the class device under the teacher's guidance; the class says “Yes” or “No”.\n- T checks the answers with the class (key in the Teacher's Book) and plays the audio again to confirm.","hs":"- Ss look and name the pictures.\n- Ss listen and follow the example.\n- Ss listen and circle.\n- Ss swap books and check in pairs.\n- Ss listen and follow the rules for using the device.\n- Ss take turns to circle the picture on the class device; the class checks.\n- Ss correct their answers."},{"ten":"4. Production (10’)","gv":"Activity 5: Look and write\n* Aims: Pupils can look at the pictures and write the missing letters/words.\n* Procedure:\n- T has Ss look at the pictures and say the words.\n- T models the first item on the board.\n- T asks Ss to do the task individually and goes around to help.\n- T invites some Ss to write the answers on the board; the class checks.\n- T has Ss read the completed words aloud.\n- (Digital competence 1.1.CB1a) T shows the Activity 5 pictures on the screen and, after Ss finish writing, clicks to show the missing letters/words one by one.\n- T shows a picture of a messy café table and asks: “Is it good?” T reminds Ss to keep order, not to spill food and not to waste food when eating out.","hs":"- Ss look and say the words.\n- Ss watch the example.\n- Ss write in their books.\n- Some Ss write on the board; the class checks.\n- Ss read the words aloud.\n- Ss look at the screen and check their own writing.\n- Ss answer “No!” and say how to keep the table clean."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the chant once more and name the words of the lesson.\n- T praises Ss and asks them to practise at home and prepare Lesson 3.","hs":"- Ss chant and say the words.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":25,"tiet":1,"bai":"Unit 12: At the café – Lesson 3 (Activities 6–8)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say where food is with “The cake is on the table.” / “The grapes are on the table.”\n- Sing the song of Unit 12 with the correct rhythm and actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Speak confidently and listen to friends politely.\n- Culture of communication: speak quietly and politely, wait for their turn and keep the table clean in public places.\n4. Digital Competence (AI 2.A2; 2.1.CB1a): Recognise that AI can support speaking practice and pronunciation checking of simple English sentence patterns; under the teacher's guidance, pupils practise “The cake is on the table.” / “The grapes are on the table.” (AI 2.A2); take part in a simple guided digital communication activity: listen to models, look at the pictures and say sentences that match the food and objects (2.1.CB1a).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 12), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and the chant of Lesson 2.\n* Procedure:\n- T greets the class.\n- T has Ss say the chant of Lesson 2 and revises cake, grapes, table with flashcards.\n- T introduces Unit 12 – Lesson 3.","hs":"- Ss greet the teacher.\n- Ss chant and say the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’)","gv":"Activity 6: Listen and repeat\n* Aims: Pupils can understand and say the sentence pattern correctly.\n* Procedure:\n- T shows the pictures of Activity 6 and asks: “Who can you see? What can you see?”\n- T puts a picture of a cake and a picture of some grapes on a picture of a table and points out: one cake – “is”; many grapes – “are”.\n- T presents the sentence pattern on the board:\n+ The cake is on the table.: Cái bánh ở trên bàn.\n+ The grapes are on the table.: Những quả nho ở trên bàn.\n- T models the sentences; Ss repeat in chorus and individually (T uses backchaining for long sentences).\n- T plays the audio: Ss listen, point to the pictures and repeat.\n- (Digital competence 2.1.CB1a) T shows the pictures on the screen and plays the model sentences; Ss listen, look at each picture and say the matching sentence.","hs":"- Ss look and answer.\n- Ss look and listen.\n- Ss look at the board and listen.\n- Ss repeat in chorus and individually.\n- Ss listen, point and repeat.\n- Ss listen to the model, look at the pictures on the screen and say the sentences."},{"ten":"3. Practice (10’)","gv":"Activity 7: Let's talk\n* Aims: Pupils can use the sentence pattern with the words of the unit.\n* Procedure:\n- T points to the pictures and elicits the sentences.\n- T models with a good pupil: T puts the cake picture on the table picture – S: “The cake is on the table.”\n- T organises T–Ss, open pairs, then closed pairs: one pupil puts a picture card on the table picture, the other says “The cake is on the table.” or “The grapes are on the table.”\n- (AI 2.A2) T opens a teacher-checked AI speaking tool on the class device (teacher's account; pupils use no accounts). A few pupils say “The cake is on the table.” / “The grapes are on the table.” into the microphone; the class compares what the tool shows with the model. T explains that the tool can help check pronunciation, but the teacher gives the final feedback.\n- T invites some pairs to act out in front of the class and gives feedback.","hs":"- Ss look and say the sentences.\n- Ss listen and watch the model.\n- Ss practise in open pairs, then closed pairs.\n- A few Ss say the sentences to the class device; the class compares the result with the model and listens to T's feedback.\n- Some pairs act out; the class listens and claps."},{"ten":"4. Production (8’)","gv":"Activity 8: Let's sing\n* Aims: Pupils can sing the song of the unit with the correct rhythm and actions.\n* Procedure:\n- T shows the song picture and reads the lyrics (Pupil's Book) line by line.\n- T plays the song; Ss listen and follow in their books.\n- T plays it again; Ss sing along and do actions.\n- T has groups take turns to sing; the class claps and praises.\n- T asks: “How do we talk in a café?” T reminds Ss to speak quietly and politely, wait for their turn and keep the table clean.","hs":"- Ss look, listen and repeat the lyrics.\n- Ss listen and follow.\n- Ss sing along and do actions.\n- Ss sing in groups and praise their friends.\n- Ss answer and practise speaking quietly and politely."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the sentence pattern once more: “The cake is on the table.” / “The grapes are on the table.”\n- T praises Ss and asks them to practise the sentences and the song at home.","hs":"- Ss say the sentences.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":25,"tiet":2,"bai":"Review 3 – Phil and Sue","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Listen to and understand the Phil and Sue story.\n- Revise the words of Units 9–12: yams, yogurt, yo-yos, zoo, zebra, zebu, riding, driving, sliding, cake, grapes, table.\n- Revise the sounds /j/ (Y, y), /z/ (Z, z), /aɪ/ (I, i) and /eɪ/ (A, a).\n- Revise the sentence patterns: “What do you want?” – “I want some yams.”; “Do you like the zoo?” – “Yes, I do.”; “They're riding bikes.”; “The cake is on the table.”.\n2. Skills: Listening and speaking\n3. Attributes:\n- Be honest when saying what they have heard or read.\n- Listen to the story carefully and cooperate with friends.\n4. Digital Competence (AI 2.B1; 1.2.CB1a): Recognise that an AI-style answer/illustration may not match the story and check it against the pictures and the Pupil's Book (AI 2.B1); find simple information in the story/digital learning resource to confirm answers (1.2.CB1a).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Units 9–12), TV or projector, computer, digital version of the story (teacher-controlled), an AI-style picture prepared in advance\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Units 9–12.\n* Procedure:\n- T greets the class and plays “Slap the board” with yams, yogurt, yo-yos, zoo, zebra, zebu, riding, driving, sliding, cake, grapes, table.\n- T introduces Review: Phil and Sue.","hs":"- Ss play the game in two teams.\n- Ss listen and open their books."},{"ten":"2. Presentation (7’)","gv":"Before the story\n* Aims: Pupils can predict the story from the pictures.\n* Procedure:\n- T shows the story pictures and asks: “Who can you see? Where are they?”\n- T asks Ss to find things they know from Units 9–12 in the pictures.\n- T revises the sounds /j/ (Y, y), /z/ (Z, z), /aɪ/ (I, i) and /eɪ/ (A, a) with words from the story.","hs":"- Ss look and answer: “Phil and Sue.”\n- Ss point and say the words.\n- Ss repeat the sounds and words."},{"ten":"3. Practice (13’)","gv":"The Phil and Sue story\n* Aims: Pupils can listen to the story, understand it and act it out.\n* Procedure:\n- T plays the story audio once; Ss listen and point to the pictures.\n- T plays it again, stopping after each picture; Ss repeat the sentences.\n- (Digital competence 1.2.CB1a) T shows the story on the screen and asks simple questions about each picture using the words and sentence patterns of Units 9–12; Ss find the word or picture on the screen to confirm their answers.\n- T puts Ss in pairs to act out the story as Phil and Sue.\n- T invites some pairs to perform and praises them.","hs":"- Ss listen and point.\n- Ss listen and repeat.\n- Ss answer and point to the information on the screen to confirm.\n- Ss act out the story in pairs.\n- Some pairs perform; the class claps."},{"ten":"4. Production (8’)","gv":"Does it match the story?\n* Aims: Pupils can check an AI-style answer/picture against the story.\n* Procedure:\n- (AI 2.B1) T shows an AI-style picture/answer prepared in advance that does not fully match the story (for example, the wrong object or the wrong character).\n- T asks: “Is it the same as the story?” Ss compare it with the pictures in the Pupil's Book and say what is different.\n- T reminds Ss: AI pictures and answers can be wrong; we check with the book and tell the truth about what we hear and read.\n- T has Ss say the sentence patterns: “What do you want?” – “I want some yams.”; “Do you like the zoo?” – “Yes, I do.”; “They're riding bikes.”; “The cake is on the table.”.","hs":"- Ss look at the picture on the screen.\n- Ss compare with the book and say what is different.\n- Ss listen and repeat the rule.\n- Ss say the sentences in chorus and in pairs."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “Do you like the story? What words can you remember?”\n- T praises Ss and asks them to revise Units 9–12 for the Self-check.","hs":"- Ss answer.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":26,"tiet":1,"bai":"Review 3 – Self – check – Part 1","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Listen and choose/tick the correct pictures with the words and sentences of Units 9–12.\n- Read and match words/sentences with pictures.\n- Revise the words: yams, yogurt, yo-yos, zoo, zebra, zebu, riding, driving, sliding, cake, grapes, table.\n2. Skills: Listening and speaking; reading (read and match)\n3. Attributes:\n- Self-study: mark what they have done well and what needs more practice.\n- Work carefully and independently.\n4. Digital Competence (1.1.CB1a; AI 2.A2): Listen, choose and check answers on a digital learning resource under the teacher's guidance (1.1.CB1a); compare a simple AI suggestion with the answer based on the picture/audio and correct it if it is wrong (AI 2.A2).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Units 9–12), TV or projector, computer, digital version of the activities (teacher-controlled), a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words before the Self-check.\n* Procedure:\n- T greets the class and has Ss sing a song from Units 9–12.\n- T plays “What and where” with some words from Units 9–12.\n- T explains the Self-check: we check what we can do.","hs":"- Ss sing together.\n- Ss play the game.\n- Ss listen and open their books."},{"ten":"2. Presentation (12’)","gv":"Self-check: Listen and tick/circle\n* Aims: Pupils can listen and choose the correct pictures.\n* Procedure:\n- T has Ss look at the pictures and name them.\n- T plays the audio twice; Ss listen and tick/circle in their books.\n- (Digital competence 1.1.CB1a) T shows the task on the screen; Ss take turns to choose the answer on the class device while T plays the audio again to check.\n- T checks the answers with the class (key in the Teacher's Book).","hs":"- Ss look and name the pictures.\n- Ss listen and tick/circle.\n- Ss choose the answer on the class device and check.\n- Ss correct their answers."},{"ten":"3. Practice (10’)","gv":"Self-check: Read and match\n* Aims: Pupils can read and match words/sentences with pictures.\n* Procedure:\n- T reads the words/sentences; Ss repeat.\n- T asks Ss to match individually, then check in pairs.\n- T invites some Ss to give the answers and read them aloud.","hs":"- Ss read after the teacher.\n- Ss match, then check with a partner.\n- Some Ss give and read the answers."},{"ten":"4. Production (6’)","gv":"Check the AI – My progress\n* Aims: Pupils can check an AI suggestion and assess their own progress.\n* Procedure:\n- (AI 2.A2) T shows a simple AI suggestion for one item, prepared in advance with one mistake; Ss compare it with the picture/audio and correct it.\n- T asks Ss to colour a smiley face next to each task: happy face = I can do it; sad face = I need more practice.\n- T notes the tasks that many Ss need to practise more.","hs":"- Ss compare the AI suggestion with the picture/audio and correct it.\n- Ss colour the faces for each task.\n- Ss tell the teacher which tasks are difficult."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T praises Ss for working carefully.\n- T asks Ss to practise the words they found difficult and prepare Self-check Part 2.","hs":"- Ss listen.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":26,"tiet":2,"bai":"Review 3 – Self – check – Part 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Look and write words/sentences from Units 9–12.\n- Use the sentence patterns in short talks: “What do you want?” – “I want some yams.”; “Do you like the zoo?” – “Yes, I do.”; “They're riding bikes.”; “The cake is on the table.”.\n- Recognise what they need to practise more.\n2. Skills: Listening and speaking; reading and writing\n3. Attributes:\n- Honesty: complete the Self-check independently and do not copy.\n- Be responsible for their own learning.\n4. Digital Competence (5.2.CB1a; AI 2.B1): Choose suitable simple tools for revision (audio, digital flashcards, digital games provided by the teacher) (5.2.CB1a); do not copy AI answers: do the task themselves first, then use an AI example to check under the teacher's guidance (AI 2.B1).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Units 9–12), TV or projector, computer, digital flashcards and a simple digital game (teacher-controlled), a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the sentence patterns.\n* Procedure:\n- T greets the class and asks some quick questions with “What do you want?” – “I want some yams.” / “Do you like the zoo?” – “Yes, I do.” / “They're riding bikes.” / “The cake is on the table.”.\n- T introduces Self-check Part 2.","hs":"- Ss answer the questions.\n- Ss listen and open their books."},{"ten":"2. Presentation (12’)","gv":"Self-check: Look and write\n* Aims: Pupils can write the missing words/sentences on their own.\n* Procedure:\n- T has Ss look at the pictures and say the words.\n- T reminds Ss to do the task on their own first and not to copy.\n- T gives Ss time to write; T goes around to help.\n- T invites some Ss to write the answers on the board; the class checks.","hs":"- Ss look and say the words.\n- Ss listen.\n- Ss write on their own.\n- Some Ss write on the board; the class checks."},{"ten":"3. Practice (10’)","gv":"Self-check: Let's talk\n* Aims: Pupils can ask and answer with the sentence patterns.\n* Procedure:\n- T shows pictures and models the sentence patterns.\n- T puts Ss in pairs to ask and answer about the pictures.\n- T goes around, listens and notes common mistakes.\n- T invites some pairs to talk in front of the class.","hs":"- Ss listen and repeat.\n- Ss ask and answer in pairs.\n- Ss practise and correct mistakes.\n- Some pairs perform; the class claps."},{"ten":"4. Production (6’)","gv":"Check and choose a revision tool\n* Aims: Pupils can check their work and choose a suitable tool for more practice.\n* Procedure:\n- (AI 2.B1) After Ss have finished on their own, T shows an AI example answer on the screen; Ss use it only to check their work and correct mistakes.\n- (Digital competence 5.2.CB1a) T shows three revision tools: audio, digital flashcards and a digital game; each pupil chooses the one that suits the part they need to practise.\n- T lets a few Ss try their chosen tool on the class device.","hs":"- Ss check their own work with the example.\n- Ss choose a revision tool and say why (e.g. “flashcards – words”).\n- A few Ss try the tool on the class device."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T praises Ss for doing the Self-check honestly.\n- T asks Ss to practise with the tool they chose (with an adult at home).","hs":"- Ss listen.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":27,"tiet":1,"bai":"Unit 13: In the maths class – Lesson 1 (Activities 1–2)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise and say the words: eleven, thirteen, fourteen, fifteen.\n- Recognise the letter N, n and say the sound /n/ in eleven, thirteen, fourteen, fifteen.\n2. Skills: Listening and speaking\n3. Attributes:\n- Take an active part in the lesson and cooperate with friends in pairs and groups.\n- Maths integration: recognise, read and write numbers up to 15 and link them to simple addition through pictures.\n4. Digital Competence (AI 2.A1): Recognise that AI can support listening, number recognition and pronunciation of English number words: listen to and identify eleven, thirteen, fourteen, fifteen, match the words with the numerals and practise the sound N, n – /n/.","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 13), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a friendly atmosphere and revise the previous unit.\n* Procedure:\n- T greets the class and asks: “How are you today?”\n- T plays “Slap the board” with cake, grapes, table (Unit 12).\n- T shows the Unit 13 opening picture and asks: “Where are they? What can you see?”\n- T introduces the new lesson: Unit 13: In the maths class – Lesson 1.","hs":"- Ss greet the teacher and answer.\n- Ss play the game in two teams.\n- Ss look at the picture and answer.\n- Ss listen and open their books."},{"ten":"2. Presentation (12’)","gv":"Activity 1: Listen and repeat\n* Aims: Pupils can recognise and say the words eleven, thirteen, fourteen, fifteen correctly.\n* Procedure:\n- T shows the flashcards/pictures one by one and elicits the new words:\n+ eleven: số 11 (picture)\n+ thirteen: số 13 (picture)\n+ fourteen: số 14 (picture)\n+ fifteen: số 15 (picture)\n- T models each word three times.\n- T has Ss repeat in chorus, in groups and individually.\n- (AI 2.A1) T plays a teacher-checked AI text-to-speech model of eleven, thirteen, fourteen, fifteen on the class device (teacher's account only) while showing the pictures; Ss listen, point to the correct picture and repeat; T asks: “Does it sound like the teacher's model?” and corrects where needed.\n- T plays the audio of Activity 1 twice: Ss listen, point to the pictures and repeat.\n- Checking: T plays “What and where” with the new words.","hs":"- Ss look at the pictures and guess the words.\n- Ss listen to the teacher.\n- Ss repeat in chorus, in groups and individually.\n- Ss listen to the AI model, point to the picture and repeat.\n- Ss listen, point and repeat.\n- Ss play the game and say the words."},{"ten":"3. Practice (10’)","gv":"Activity 2: Letter and sound – N, n /n/\n* Aims: Pupils can recognise N, n and say the sound /n/ correctly.\n* Procedure:\n- T writes N, n on the board and says /n/ several times, showing the mouth shape.\n- T plays the audio of Activity 2: Ss listen and repeat the letter(s), the sound and the words.\n- T underlines the letter n in eleven, thirteen, fourteen, fifteen and has Ss say the words again, stressing /n/.\n- T has Ss write N, n in the air and on their desks while saying the sound.\n- T plays “Listen and clap”: T says some familiar words; Ss clap when they hear /n/.\n- T corrects pronunciation where necessary.","hs":"- Ss look, listen and say /n/.\n- Ss listen and repeat.\n- Ss read the words, stressing the sound.\n- Ss write in the air and say the sound.\n- Ss listen and clap when they hear the sound.\n- Ss correct their pronunciation."},{"ten":"4. Production (6’)","gv":"Point and say – Guess the picture\n* Aims: Pupils can use the new words in pairs and in a game.\n* Procedure:\n- T puts Ss in pairs: one points to a picture in the Pupil's Book, the other says the word.\n- T plays “Guess the picture”: T slowly shows part of a flashcard; Ss guess the word.\n- (Maths integration) T sticks dots on the board (e.g. 10 + 3) and asks: “How many?” Ss count, say the number word (thirteen) and write the numeral.","hs":"- Ss work in pairs to point and say.\n- Ss guess and say the words.\n- Ss count, say the number word and write the numeral."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What words have you learnt today? What sound is it?”\n- T praises Ss and asks them to practise the words at home and prepare Lesson 2.","hs":"- Ss say the words and the sound.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":27,"tiet":2,"bai":"Unit 13: In the maths class – Lesson 2 (Activities 3–5)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say the chant with the words eleven, thirteen, fourteen, fifteen and the sound /n/ correctly.\n- Listen and tick the correct pictures.\n- Write the missing words and say them aloud (Write and say).\n2. Skills: Listening and speaking; reading and writing (Write and say)\n3. Attributes:\n- Work hard and help friends to complete the tasks.\n- Maths integration: count the balls and dolls and answer “How many …?” within 11–15.\n4. Digital Competence (1.1.CB1a): Perform simple information-selection actions on digital learning resources under the teacher's guidance: listen and choose the correct numeral, and match numbers with the English words in Listen and tick / Write and say.","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 13), TV or projector, computer, digital version of the activities (teacher-controlled)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Lesson 1.\n* Procedure:\n- T greets the class.\n- T plays “Flashcard flash” with eleven, thirteen, fourteen, fifteen: T flashes a card quickly and Ss say the word.\n- T asks Ss to say the sound /n/ and the words again.\n- T introduces Unit 13 – Lesson 2.","hs":"- Ss greet the teacher.\n- Ss look and say the words.\n- Ss say the sound and the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 3: Listen and chant\n* Aims: Pupils can say the chant with the correct rhythm and pronunciation.\n* Procedure:\n- T shows the chant picture and asks Ss to find eleven, thirteen, fourteen, fifteen.\n- T plays the chant once; Ss listen and follow in their books.\n- T plays it again line by line; Ss repeat.\n- T has Ss chant and clap to the rhythm, first as a class, then in groups.\n- T invites some groups to perform; the class gives praise.","hs":"- Ss look and point to the things in the picture.\n- Ss listen and follow.\n- Ss repeat line by line.\n- Ss chant and clap as a class and in groups.\n- Some groups perform; the others clap."},{"ten":"3. Practice (10’)","gv":"Activity 4: Listen and tick\n* Aims: Pupils can listen and tick the correct pictures.\n* Procedure:\n- T has Ss look at the pictures and say what they can see.\n- (Maths integration) Before listening, T has Ss count the balls and dolls in each picture and answer “How many balls?” – “Thirteen.” (within 11–15).\n- T explains the task and does the example with the class.\n- T plays the audio twice: Ss listen and tick the correct pictures.\n- T has Ss swap books and check their answers in pairs.\n- (Digital competence 1.1.CB1a) T shows Activity 4 on the screen; for each item, T invites a pupil to come up and tick the matching picture on the class device under the teacher's guidance; the class says “Yes” or “No”.\n- T checks the answers with the class (key in the Teacher's Book) and plays the audio again to confirm.","hs":"- Ss look and name the pictures.\n- Ss count the balls and dolls and answer “How many …?”.\n- Ss listen and follow the example.\n- Ss listen and tick.\n- Ss swap books and check in pairs.\n- Ss take turns to tick the picture on the class device; the class checks.\n- Ss correct their answers."},{"ten":"4. Production (10’)","gv":"Activity 5: Write and say\n* Aims: Pupils can write the missing words and say them aloud.\n* Procedure:\n- T has Ss look at the pictures and say the words.\n- T models the first item on the board.\n- T asks Ss to do the task individually and goes around to help.\n- T invites some Ss to write the answers on the board; the class checks.\n- T has Ss say the completed words aloud in pairs, pointing to the pictures.\n- (Digital competence 1.1.CB1a) T shows the Activity 5 pictures on the screen and, after Ss finish writing, clicks to show the missing letters/words one by one.","hs":"- Ss look and say the words.\n- Ss watch the example.\n- Ss write in their books.\n- Some Ss write on the board; the class checks.\n- Ss say the words in pairs.\n- Ss look at the screen and check their own writing."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the chant once more and name the words of the lesson.\n- T praises Ss and asks them to practise at home and prepare Lesson 3.","hs":"- Ss chant and say the words.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":28,"tiet":1,"bai":"Unit 13: In the maths class – Lesson 3 (Activities 6–8)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Ask and answer with “What number is it?” – “It's eleven.”, using the numbers eleven, twelve, thirteen, fourteen and fifteen.\n- Sing the song of Unit 13 with the correct rhythm and actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Speak confidently and listen to friends politely.\n- Learning skills: react quickly to numbers, answer confidently and wait for their turn in question–answer games.\n4. Digital Competence (AI 2.A2; 2.1.CB1a): Recognise that AI can support speaking practice and pronunciation checking of question–answer patterns about numbers; under the teacher's guidance, pupils practise “What number is it?” – “It's eleven/twelve/thirteen/fourteen/fifteen.” (AI 2.A2); take part in a simple guided digital communication activity: listen to models, look at the number cards and say the number shown (2.1.CB1a).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 13), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and the chant of Lesson 2.\n* Procedure:\n- T greets the class.\n- T has Ss say the chant of Lesson 2 and revises eleven, thirteen, fourteen, fifteen with flashcards.\n- T introduces Unit 13 – Lesson 3.","hs":"- Ss greet the teacher.\n- Ss chant and say the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’)","gv":"Activity 6: Listen and repeat\n* Aims: Pupils can understand and say the sentence pattern correctly.\n* Procedure:\n- T shows the pictures of Activity 6 and asks: “Who can you see? What can you see?”\n- T revises the numbers with number cards 11–15, including twelve:\n+ twelve: số 12\n- T presents the sentence pattern on the board:\n+ What number is it?: Đó là số mấy?\n+ It's eleven.: Đó là số mười một.\n- T models the sentences; Ss repeat in chorus and individually (T uses backchaining for long sentences).\n- T plays the audio: Ss listen, point to the pictures and repeat.\n- (Digital competence 2.1.CB1a) T shows number cards 11–15 on the screen one by one and plays the model “What number is it?” – “It's …”; Ss look at the card and say the number shown.","hs":"- Ss look and answer.\n- Ss look at the cards and say the numbers.\n- Ss look at the board and listen.\n- Ss repeat in chorus and individually.\n- Ss listen, point and repeat.\n- Ss look at the number on the screen and say it."},{"ten":"3. Practice (10’)","gv":"Activity 7: Let's talk\n* Aims: Pupils can use the sentence pattern with the words of the unit.\n* Procedure:\n- T points to the pictures and elicits the sentences.\n- T models with a good pupil: T shows the number card 13: “What number is it?” – S: “It's thirteen.”\n- T organises T–Ss, open pairs, then closed pairs: with number cards 11–15, one pupil shows a card and asks “What number is it?”, the other answers “It's eleven / twelve / thirteen / fourteen / fifteen.”\n- (AI 2.A2) T opens a teacher-checked AI speaking tool on the class device (teacher's account; pupils use no accounts). A few pupils say “What number is it?” – “It's fourteen.” into the microphone; the class compares what the tool shows with the model. T explains that the tool can help check pronunciation, but the teacher gives the final feedback.\n- T invites some pairs to act out in front of the class and gives feedback.","hs":"- Ss look and say the sentences.\n- Ss listen and watch the model.\n- Ss practise in open pairs, then closed pairs.\n- A few Ss say the sentences to the class device; the class compares the result with the model and listens to T's feedback.\n- Some pairs act out; the class listens and claps."},{"ten":"4. Production (8’)","gv":"Activity 8: Let's sing\n* Aims: Pupils can sing the song of the unit with the correct rhythm and actions.\n* Procedure:\n- T shows the song picture and reads the lyrics (Pupil's Book) line by line.\n- T plays the song; Ss listen and follow in their books.\n- T plays it again; Ss sing along and do actions.\n- T has groups take turns to sing; the class claps and praises.\n- T plays “Quick numbers”: T shows a number card for two seconds and asks “What number is it?”; Ss put up their hands and wait for their turn to answer.","hs":"- Ss look, listen and repeat the lyrics.\n- Ss listen and follow.\n- Ss sing along and do actions.\n- Ss sing in groups and praise their friends.\n- Ss wait for their turn and answer quickly and confidently."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the sentence pattern once more: “What number is it?” – “It's eleven.”\n- T praises Ss and asks them to practise the sentences and the song at home.","hs":"- Ss say the sentences.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":28,"tiet":2,"bai":"Unit 14: At home – Lesson 1 (Activities 1–2)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise and say the words: sister, brother, grandmother.\n- Recognise the letters er and say the sound /ə/ in sister, brother, grandmother.\n2. Skills: Listening and speaking\n3. Attributes:\n- Take an active part in the lesson and cooperate with friends in pairs and groups.\n- Family education: love, respect and care for brothers, sisters and grandparents.\n4. Digital Competence (AI 2.A1): Recognise that AI can support listening to, identifying and pronouncing English words about family members: listen to and identify sister, brother, grandmother, match the words with the pictures and practise the letters er.","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 14), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a friendly atmosphere and revise the previous unit.\n* Procedure:\n- T greets the class and asks: “How are you today?”\n- T plays “Slap the board” with eleven, thirteen, fourteen, fifteen (Unit 13).\n- T shows the Unit 14 opening picture and asks: “Where are they? What can you see?”\n- T introduces the new lesson: Unit 14: At home – Lesson 1.","hs":"- Ss greet the teacher and answer.\n- Ss play the game in two teams.\n- Ss look at the picture and answer.\n- Ss listen and open their books."},{"ten":"2. Presentation (12’)","gv":"Activity 1: Listen and repeat\n* Aims: Pupils can recognise and say the words sister, brother, grandmother correctly.\n* Procedure:\n- T shows the flashcards/pictures one by one and elicits the new words:\n+ sister: chị gái / em gái (picture)\n+ brother: anh trai / em trai (picture)\n+ grandmother: bà (picture)\n- T models each word three times.\n- T has Ss repeat in chorus, in groups and individually.\n- (AI 2.A1) T plays a teacher-checked AI text-to-speech model of sister, brother, grandmother on the class device (teacher's account only) while showing the pictures; Ss listen, point to the correct picture and repeat; T asks: “Does it sound like the teacher's model?” and corrects where needed.\n- T plays the audio of Activity 1 twice: Ss listen, point to the pictures and repeat.\n- Checking: T plays “What and where” with the new words.","hs":"- Ss look at the pictures and guess the words.\n- Ss listen to the teacher.\n- Ss repeat in chorus, in groups and individually.\n- Ss listen to the AI model, point to the picture and repeat.\n- Ss listen, point and repeat.\n- Ss play the game and say the words."},{"ten":"3. Practice (10’)","gv":"Activity 2: Letter and sound – er /ə/\n* Aims: Pupils can recognise er and say the sound /ə/ correctly.\n* Procedure:\n- T writes er on the board and says /ə/ several times, showing the mouth shape.\n- T plays the audio of Activity 2: Ss listen and repeat the letter(s), the sound and the words.\n- T underlines the letters er in sister, brother, grandmother and has Ss say the words again, stressing /ə/.\n- T has Ss write er in the air and on their desks while saying the sound.\n- T plays “Listen and clap”: T says some familiar words; Ss clap when they hear /ə/.\n- T corrects pronunciation where necessary.","hs":"- Ss look, listen and say /ə/.\n- Ss listen and repeat.\n- Ss read the words, stressing the sound.\n- Ss write in the air and say the sound.\n- Ss listen and clap when they hear the sound.\n- Ss correct their pronunciation."},{"ten":"4. Production (6’)","gv":"Point and say – Guess the picture\n* Aims: Pupils can use the new words in pairs and in a game.\n* Procedure:\n- T puts Ss in pairs: one points to a picture in the Pupil's Book, the other says the word.\n- T plays “Guess the picture”: T slowly shows part of a flashcard; Ss guess the word.\n- T asks: “What do you do to help your grandmother / brother / sister?” T encourages Ss to love, respect and care for their family members.","hs":"- Ss work in pairs to point and say.\n- Ss guess and say the words.\n- Ss answer with simple words or gestures (help, hug, share)."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What words have you learnt today? What sound is it?”\n- T praises Ss and asks them to practise the words at home and prepare Lesson 2.","hs":"- Ss say the words and the sound.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":29,"tiet":1,"bai":"Unit 14: At home – Lesson 2 (Activities 3–5)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say the chant with the words sister, brother, grandmother and the sound /ə/ correctly.\n- Recognise and say the ages sixteen, seventeen, eighteen, nineteen and twenty.\n- Listen and circle the correct pictures.\n- Write the missing words and say them aloud (Write and say).\n2. Skills: Listening and speaking; reading and writing (Write and say)\n3. Attributes:\n- Work hard and help friends to complete the tasks.\n- Maths integration: recognise and read ages up to 20, especially sixteen, seventeen, eighteen, nineteen and twenty.\n4. Digital Competence (1.1.CB1a): Perform simple information-selection actions on digital learning resources under the teacher's guidance: listen, look at the pictures and choose the correct character/age in Listen and circle, then complete Write and say with grandmother, brother, sister.","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 14), TV or projector, computer, digital version of the activities (teacher-controlled)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Lesson 1.\n* Procedure:\n- T greets the class.\n- T plays “Flashcard flash” with sister, brother, grandmother: T flashes a card quickly and Ss say the word.\n- T asks Ss to say the sound /ə/ and the words again.\n- T introduces Unit 14 – Lesson 2.","hs":"- Ss greet the teacher.\n- Ss look and say the words.\n- Ss say the sound and the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 3: Listen and chant\n* Aims: Pupils can say the chant with the correct rhythm and pronunciation.\n* Procedure:\n- (Maths integration) T revises the numbers for ages with number cards:\n+ sixteen: số 16\n+ seventeen: số 17\n+ eighteen: số 18\n+ nineteen: số 19\n+ twenty: số 20\n- T has Ss count from eleven to twenty in chorus.\n- T shows the chant picture and asks Ss to find sister, brother, grandmother.\n- T plays the chant once; Ss listen and follow in their books.\n- T plays it again line by line; Ss repeat.\n- T has Ss chant and clap to the rhythm, first as a class, then in groups.\n- T invites some groups to perform; the class gives praise.","hs":"- Ss look, listen and repeat the numbers.\n- Ss count from eleven to twenty.\n- Ss look and point to the things in the picture.\n- Ss listen and follow.\n- Ss repeat line by line.\n- Ss chant and clap as a class and in groups.\n- Some groups perform; the others clap."},{"ten":"3. Practice (10’)","gv":"Activity 4: Listen and circle\n* Aims: Pupils can listen and circle the correct pictures.\n* Procedure:\n- T has Ss look at the pictures and say what they can see.\n- T explains the task and does the example with the class.\n- T plays the audio twice: Ss listen and circle the correct pictures.\n- T has Ss swap books and check their answers in pairs.\n- (Digital competence 1.1.CB1a) T shows Activity 4 on the screen; for each item, T invites a pupil to come up and circle the matching picture on the class device under the teacher's guidance; the class says “Yes” or “No”.\n- T checks the answers with the class (key in the Teacher's Book) and plays the audio again to confirm.","hs":"- Ss look and name the pictures.\n- Ss listen and follow the example.\n- Ss listen and circle.\n- Ss swap books and check in pairs.\n- Ss take turns to circle the picture on the class device; the class checks.\n- Ss correct their answers."},{"ten":"4. Production (10’)","gv":"Activity 5: Write and say\n* Aims: Pupils can write the missing words and say them aloud.\n* Procedure:\n- T has Ss look at the pictures and say the words.\n- T models the first item on the board.\n- T asks Ss to do the task individually and goes around to help.\n- T invites some Ss to write the answers on the board; the class checks.\n- T has Ss say the completed words aloud in pairs, pointing to the pictures.\n- (Digital competence 1.1.CB1a) T shows the Activity 5 pictures on the screen and, after Ss finish writing, clicks to show the missing letters/words one by one.","hs":"- Ss look and say the words.\n- Ss watch the example.\n- Ss write in their books.\n- Some Ss write on the board; the class checks.\n- Ss say the words in pairs.\n- Ss look at the screen and check their own writing."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the chant once more and name the words of the lesson.\n- T praises Ss and asks them to practise at home and prepare Lesson 3.","hs":"- Ss chant and say the words.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":29,"tiet":2,"bai":"Unit 14: At home – Lesson 3 (Activities 6–8)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Ask and answer about age with “How old is your brother?” – “He's nineteen.”, substituting suitable ages from sixteen to twenty.\n- Sing the song of Unit 14 with the correct rhythm and actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Speak confidently and listen to friends politely.\n- Love and care for family members and talk about them kindly.\n4. Digital Competence (AI 2.A2; 4.2.CB1a): Recognise that AI can support speaking practice and pronunciation checking of question–answer patterns about age; pupils practise “How old is your brother?” – “He's nineteen.” and substitute suitable ages (AI 2.A2); recognise that the ages and pictures of family members are personal information to be used carefully in the digital environment and not shared without an adult's permission (4.2.CB1a).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 14), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and the chant of Lesson 2.\n* Procedure:\n- T greets the class.\n- T has Ss say the chant of Lesson 2 and revises sister, brother, grandmother with flashcards.\n- T introduces Unit 14 – Lesson 3.","hs":"- Ss greet the teacher.\n- Ss chant and say the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’)","gv":"Activity 6: Listen and repeat\n* Aims: Pupils can understand and say the sentence pattern correctly.\n* Procedure:\n- T shows the pictures of Activity 6 and asks: “Who can you see? What can you see?”\n- T presents the sentence pattern on the board:\n+ How old is your brother?: Anh trai bạn bao nhiêu tuổi?\n+ He's nineteen.: Anh ấy mười chín tuổi.\n- T models the sentences; Ss repeat in chorus and individually (T uses backchaining for long sentences).\n- T plays the audio: Ss listen, point to the pictures and repeat.","hs":"- Ss look and answer.\n- Ss look at the board and listen.\n- Ss repeat in chorus and individually.\n- Ss listen, point and repeat."},{"ten":"3. Practice (10’)","gv":"Activity 7: Let's talk\n* Aims: Pupils can use the sentence pattern with the words of the unit.\n* Procedure:\n- T points to the pictures and elicits the sentences.\n- T models with a good pupil: T: “How old is your brother?” – S: “He's seventeen.”\n- T organises T–Ss, open pairs, then closed pairs: using the pictures, one pupil asks “How old is your brother?”, the other answers with the age in the picture (“He's sixteen / eighteen / twenty.”); for a sister, T models “How old is your sister?” – “She's eighteen.”\n- (AI 2.A2) T opens a teacher-checked AI speaking tool on the class device (teacher's account; pupils use no accounts). A few pupils say “How old is your brother?” – “He's nineteen.” into the microphone; the class compares what the tool shows with the model. T explains that the tool can help check pronunciation, but the teacher gives the final feedback.\n- T invites some pairs to act out in front of the class and gives feedback.","hs":"- Ss look and say the sentences.\n- Ss listen and watch the model.\n- Ss practise in open pairs, then closed pairs.\n- A few Ss say the sentences to the class device; the class compares the result with the model and listens to T's feedback.\n- Some pairs act out; the class listens and claps."},{"ten":"4. Production (8’)","gv":"Activity 8: Let's sing\n* Aims: Pupils can sing the song of the unit with the correct rhythm and actions.\n* Procedure:\n- T shows the song picture and reads the lyrics (Pupil's Book) line by line.\n- T plays the song; Ss listen and follow in their books.\n- T plays it again; Ss sing along and do actions.\n- T has groups take turns to sing; the class claps and praises.\n- (Digital competence 4.2.CB1a) T asks: “Can you post your brother's photo and age on the Internet?” T explains that ages and photos of family members are personal information; Ss do not share them without an adult's permission.","hs":"- Ss look, listen and repeat the lyrics.\n- Ss listen and follow.\n- Ss sing along and do actions.\n- Ss sing in groups and praise their friends.\n- Ss answer “No!” and repeat: ask an adult first."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the sentence pattern once more: “How old is your brother?” – “He's nineteen.”\n- T praises Ss and asks them to practise the sentences and the song at home.","hs":"- Ss say the sentences.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":30,"tiet":1,"bai":"Fun time 4 – Lesson 1","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Revise the words of Units 13–14: eleven, thirteen, fourteen, fifteen, sister, brother, grandmother, sixteen, seventeen, eighteen, nineteen, twenty.\n- Revise the sounds /n/ (N, n) and /ə/ (er).\n- Revise the sentence patterns: “What number is it?” – “It's fourteen.”; “How old is your brother?” – “He's nineteen.”.\n2. Skills: Listening and speaking\n3. Attributes:\n- Cooperate, play honestly and respect friends in team games.\n- Wait for their turn and cheer for other teams.\n4. Digital Competence (2.4.CB1a; AI 2.A2): Take part in simple digital games in groups, wait for their turn, choose answers and respond politely (2.4.CB1a); compare a teacher-checked AI voice/image challenge with the pictures, words and sentence patterns they have learnt and do not treat AI output as the default answer (AI 2.A2).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Units 13–14), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only), a simple class quiz on the screen\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a fun atmosphere and lead in to Fun time.\n* Procedure:\n- T greets the class and has Ss sing a song or say a chant from Units 13–14.\n- T introduces Fun time: “Today we play games with the English we have learnt.”","hs":"- Ss sing or chant together.\n- Ss listen and get ready."},{"ten":"2. Presentation (10’)","gv":"Game 1: Slap the board – words and sounds\n* Aims: Pupils can recognise and say the words and sounds of Units 13–14.\n* Procedure:\n- T sticks the flashcards of eleven, thirteen, fourteen, fifteen, sister, brother, grandmother, sixteen, seventeen, eighteen, nineteen, twenty on the board; Ss say the words.\n- T divides the class into two teams; T says a word or a sound, and one pupil from each team slaps the right card.\n- T asks the winner to say the word and its sound again.\n- T invites some Ss to sort the cards into the /n/ words and the er words.","hs":"- Ss look and say the words.\n- Ss play in two teams.\n- Ss say the word and the sound.\n- Ss come to the board and sort the cards."},{"ten":"3. Practice (8’)","gv":"Game 2: Is it right? – AI challenge\n* Aims: Pupils can check AI voices/images against what they have learnt.\n* Procedure:\n- (AI 2.A2) T shows some AI voices/images prepared and checked in advance on the class device; most match the book, one or two do not (e.g. an AI voice says “fifteen” under the number 13).\n- For each one, T asks: “Is it right?” Ss compare it with the pictures in the Pupil's Book and answer “Yes” or “No”.\n- When the answer is “No”, T asks Ss to give the correct word or sentence.\n- T explains: AI can help us, but it can be wrong; we check with the book and the teacher.","hs":"- Ss look and listen carefully.\n- Ss compare with the book and answer “Yes” or “No”.\n- Ss say the correct word or sentence.\n- Ss listen and repeat the rule: check with the book and the teacher."},{"ten":"4. Production (10’)","gv":"Game 3: Team quiz on the class screen\n* Aims: Pupils can use the words and sentence patterns in a team game.\n* Procedure:\n- (Digital competence 2.4.CB1a) T shows a teacher-controlled quiz on the screen with pictures and questions using “What number is it?” – “It's fourteen.” and “How old is your brother?” – “He's nineteen.”.\n- Teams take turns: one pupil comes up, listens to the question, chooses the answer on the class device and says the sentence.\n- T reminds Ss to wait for their turn and say “Good job!” or “Try again!” to friends politely.\n- T counts the points and praises both teams for playing honestly and respecting friends.","hs":"- Ss look at the quiz on the screen.\n- Ss take turns in their teams, choose the answer and say the sentence.\n- Ss wait for their turn and respond politely.\n- Ss cheer for both teams."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to name their favourite game and say one sentence they have practised.\n- T praises Ss and asks them to revise Units 13–14 at home.","hs":"- Ss answer and say a sentence.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":30,"tiet":2,"bai":"Fun time 4 – Lesson 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Revise the words of Units 13–14: eleven, thirteen, fourteen, fifteen, sister, brother, grandmother, sixteen, seventeen, eighteen, nineteen, twenty.\n- Revise the sounds /n/ (N, n) and /ə/ (er).\n- Revise the sentence patterns: “What number is it?” – “It's fourteen.”; “How old is your brother?” – “He's nineteen.”.\n2. Skills: Listening and speaking\n3. Attributes:\n- Check their answers carefully and correct mistakes honestly.\n- Digital safety: use the class device without a personal account and never enter private information.\n4. Digital Competence (1.2.CB1a; AI 2.A1): Observe, listen to and select simple information on teacher-controlled digital learning resources, and check again when an answer does not match the picture/audio (1.2.CB1a); recognise that AI can generate voices or suggest answers but is sometimes wrong, so they ask the teacher or check the Pupil's Book before correcting their work (AI 2.A1).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Units 13–14), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only), digital version of the activities (teacher-controlled)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words through a chant.\n* Procedure:\n- T greets the class and has Ss say a chant from Units 13–14.\n- T plays “Flashcard flash” with eleven, thirteen, fourteen, fifteen, sister, brother, grandmother, sixteen, seventeen, eighteen, nineteen, twenty.","hs":"- Ss say the chant and clap.\n- Ss look and say the words."},{"ten":"2. Presentation (8’)","gv":"Letters and sounds\n* Aims: Pupils can recognise the letters and sounds /n/ (N, n) and /ə/ (er).\n* Procedure:\n- T writes the letters on the board and says each sound; Ss repeat.\n- T plays “Odd one out”: T says three words; Ss say the word with a different sound.\n- T writes some words with a missing letter on the board; Ss come up and write the missing letter.","hs":"- Ss listen and repeat the sounds.\n- Ss listen and say the odd word.\n- Ss write the missing letters and read the words."},{"ten":"3. Practice (10’)","gv":"Listen and choose\n* Aims: Pupils can listen and choose the correct picture on a digital resource.\n* Procedure:\n- (Digital competence 1.2.CB1a) T plays the audio of words and sentences on a teacher-controlled digital resource; for each item Ss look at the pictures on the screen.\n- T invites Ss to choose the matching picture on the class device.\n- When an answer does not match the picture/audio, T plays the audio again and asks Ss to check once more before choosing again.\n- T has the class repeat each correct word or sentence.","hs":"- Ss look and listen.\n- Ss take turns to choose the picture.\n- Ss listen again, check and choose again.\n- Ss repeat in chorus."},{"ten":"4. Production (10’)","gv":"Check the AI – Ask and answer\n* Aims: Pupils can check an AI suggestion and use the sentence patterns in pairs.\n* Procedure:\n- (AI 2.A1) T shows some AI voice/answer suggestions prepared in advance on the class device; one is wrong (e.g. the AI suggestion says “He's sixteen.” when the picture shows 19).\n- T asks: “Is the AI right?” Ss check with the Pupil's Book and ask the teacher before correcting it.\n- T reminds Ss: no personal account is needed and we never type our name, address or other private information.\n- T has Ss ask and answer in pairs with “What number is it?” – “It's fourteen.” and “How old is your brother?” – “He's nineteen.”, using the pictures.\n- T invites some pairs to perform and gives feedback.","hs":"- Ss look and listen.\n- Ss check with the book, ask the teacher and give the correct answer.\n- Ss listen and remember the safety rule.\n- Ss ask and answer in pairs.\n- Some pairs perform; the class claps."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What can you say now?” and reviews the words, sounds and sentences.\n- T praises Ss and asks them to prepare the next unit.","hs":"- Ss answer and say the sentences.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":31,"tiet":1,"bai":"Unit 15: In the clothes shop – Lesson 1 (Activities 1–2)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise and say the words: shoes, shirts, shorts.\n- Recognise the letters sh and say the sound /ʃ/ in shoes, shirts, shorts.\n2. Skills: Listening and speaking\n3. Attributes:\n- Take an active part in the lesson and cooperate with friends in pairs and groups.\n- Life skills: keep clothes and shoes clean and tidy, and choose clothes that suit the activity and the weather.\n4. Digital Competence (AI 2.A1): Recognise that AI can support image recognition and pronunciation of English words about clothes: look at the pictures, listen to the tool read shoes, shirts, shorts, point to the correct items and practise the /ʃ/ sound in the letters sh.","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 15), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a friendly atmosphere and revise the previous unit.\n* Procedure:\n- T greets the class and asks: “How are you today?”\n- T plays “Slap the board” with sister, brother, grandmother (Unit 14).\n- T shows the Unit 15 opening picture and asks: “Where are they? What can you see?”\n- T introduces the new lesson: Unit 15: In the clothes shop – Lesson 1.","hs":"- Ss greet the teacher and answer.\n- Ss play the game in two teams.\n- Ss look at the picture and answer.\n- Ss listen and open their books."},{"ten":"2. Presentation (12’)","gv":"Activity 1: Listen and repeat\n* Aims: Pupils can recognise and say the words shoes, shirts, shorts correctly.\n* Procedure:\n- T shows the flashcards/pictures one by one and elicits the new words:\n+ shoes: đôi giày (picture)\n+ shirts: áo sơ mi (picture)\n+ shorts: quần soóc (picture)\n- T models each word three times.\n- T has Ss repeat in chorus, in groups and individually.\n- (AI 2.A1) T plays a teacher-checked AI text-to-speech model of shoes, shirts, shorts on the class device (teacher's account only) while showing the pictures; Ss listen, point to the correct picture and repeat; T asks: “Does it sound like the teacher's model?” and corrects where needed.\n- T plays the audio of Activity 1 twice: Ss listen, point to the pictures and repeat.\n- Checking: T plays “What and where” with the new words.","hs":"- Ss look at the pictures and guess the words.\n- Ss listen to the teacher.\n- Ss repeat in chorus, in groups and individually.\n- Ss listen to the AI model, point to the picture and repeat.\n- Ss listen, point and repeat.\n- Ss play the game and say the words."},{"ten":"3. Practice (10’)","gv":"Activity 2: Letter and sound – sh /ʃ/\n* Aims: Pupils can recognise sh and say the sound /ʃ/ correctly.\n* Procedure:\n- T writes sh on the board and says /ʃ/ several times, showing the mouth shape.\n- T plays the audio of Activity 2: Ss listen and repeat the letter(s), the sound and the words.\n- T underlines the letters sh in shoes, shirts, shorts and has Ss say the words again, stressing /ʃ/.\n- T has Ss write sh in the air and on their desks while saying the sound.\n- T plays “Listen and clap”: T says some familiar words; Ss clap when they hear /ʃ/.\n- T corrects pronunciation where necessary.","hs":"- Ss look, listen and say /ʃ/.\n- Ss listen and repeat.\n- Ss read the words, stressing the sound.\n- Ss write in the air and say the sound.\n- Ss listen and clap when they hear the sound.\n- Ss correct their pronunciation."},{"ten":"4. Production (6’)","gv":"Point and say – Guess the picture\n* Aims: Pupils can use the new words in pairs and in a game.\n* Procedure:\n- T puts Ss in pairs: one points to a picture in the Pupil's Book, the other says the word.\n- T plays “Guess the picture”: T slowly shows part of a flashcard; Ss guess the word.\n- T shows pictures of a hot day and a rainy day and asks: “Shorts or a coat?” T reminds Ss to choose clothes that suit the weather and to keep their clothes and shoes clean and tidy.","hs":"- Ss work in pairs to point and say.\n- Ss guess and say the words.\n- Ss choose the right clothes and say how to keep them tidy."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What words have you learnt today? What sound is it?”\n- T praises Ss and asks them to practise the words at home and prepare Lesson 2.","hs":"- Ss say the words and the sound.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":31,"tiet":2,"bai":"Unit 15: In the clothes shop – Lesson 2 (Activities 3–5)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say the chant with the words shoes, shirts, shorts and the sound /ʃ/ correctly.\n- Listen and tick the correct pictures.\n- Write the missing words and say them aloud (Write and say).\n2. Skills: Listening and speaking; reading and writing (Write and say)\n3. Attributes:\n- Work hard and help friends to complete the tasks.\n- Take care of their clothes and keep them tidy.\n4. Digital Competence (1.1.CB1a; 4.1.CB1a): Perform simple information-selection actions on digital learning resources under the teacher's guidance: listen, look and choose the correct pictures in Listen and tick, then complete Write and say with shirts, shoes, shorts (1.1.CB1a); use digital devices safely when viewing shopping pictures: only operate as instructed and do not click on advertisements or unfamiliar links (4.1.CB1a).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 15), TV or projector, computer, digital version of the activities (teacher-controlled)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Lesson 1.\n* Procedure:\n- T greets the class.\n- T plays “Flashcard flash” with shoes, shirts, shorts: T flashes a card quickly and Ss say the word.\n- T asks Ss to say the sound /ʃ/ and the words again.\n- T introduces Unit 15 – Lesson 2.","hs":"- Ss greet the teacher.\n- Ss look and say the words.\n- Ss say the sound and the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 3: Listen and chant\n* Aims: Pupils can say the chant with the correct rhythm and pronunciation.\n* Procedure:\n- T shows the chant picture and asks Ss to find shoes, shirts, shorts.\n- T plays the chant once; Ss listen and follow in their books.\n- T plays it again line by line; Ss repeat.\n- T has Ss chant and clap to the rhythm, first as a class, then in groups.\n- T invites some groups to perform; the class gives praise.","hs":"- Ss look and point to the things in the picture.\n- Ss listen and follow.\n- Ss repeat line by line.\n- Ss chant and clap as a class and in groups.\n- Some groups perform; the others clap."},{"ten":"3. Practice (10’)","gv":"Activity 4: Listen and tick\n* Aims: Pupils can listen and tick the correct pictures.\n* Procedure:\n- T has Ss look at the pictures and say what they can see.\n- T explains the task and does the example with the class.\n- T plays the audio twice: Ss listen and tick the correct pictures.\n- T has Ss swap books and check their answers in pairs.\n- (Digital competence 4.1.CB1a) Before Ss come up to the class device, T reminds them: only touch what the teacher says; never click on advertisements or unfamiliar links when looking at shopping pictures.\n- (Digital competence 1.1.CB1a) T shows Activity 4 on the screen; for each item, T invites a pupil to come up and tick the matching picture on the class device under the teacher's guidance; the class says “Yes” or “No”.\n- T checks the answers with the class (key in the Teacher's Book) and plays the audio again to confirm.","hs":"- Ss look and name the pictures.\n- Ss listen and follow the example.\n- Ss listen and tick.\n- Ss swap books and check in pairs.\n- Ss listen and follow the rules for using the device.\n- Ss take turns to tick the picture on the class device; the class checks.\n- Ss correct their answers."},{"ten":"4. Production (10’)","gv":"Activity 5: Write and say\n* Aims: Pupils can write the missing words and say them aloud.\n* Procedure:\n- T has Ss look at the pictures and say the words.\n- T models the first item on the board.\n- T asks Ss to do the task individually and goes around to help.\n- T invites some Ss to write the answers on the board; the class checks.\n- T has Ss say the completed words aloud in pairs, pointing to the pictures.\n- (Digital competence 1.1.CB1a) T shows the Activity 5 pictures on the screen and, after Ss finish writing, clicks to show the missing letters/words one by one.","hs":"- Ss look and say the words.\n- Ss watch the example.\n- Ss write in their books.\n- Some Ss write on the board; the class checks.\n- Ss say the words in pairs.\n- Ss look at the screen and check their own writing."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the chant once more and name the words of the lesson.\n- T praises Ss and asks them to practise at home and prepare Lesson 3.","hs":"- Ss chant and say the words.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":32,"tiet":1,"bai":"Unit 15: In the clothes shop – Lesson 3 (Activities 6–8)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Ask and answer where clothes are with “Where are the shoes?” – “Over there.”, substituting shirts and shorts.\n- Sing the song of Unit 15 with the correct rhythm and actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Speak confidently and listen to friends politely.\n- Be polite in shops: ask nicely and say “Thank you.”\n4. Digital Competence (AI 2.A2; 4.2.CB1a): Recognise that AI can support listening and speaking practice in situations asking where things are; under the teacher's guidance, pupils practise “Where are the shoes?” – “Over there.” and substitute shirts / shorts (AI 2.A2); recognise that they must not give their name, address, phone number or payment information when viewing shopping content on digital devices, and must ask an adult (4.2.CB1a).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 15), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and the chant of Lesson 2.\n* Procedure:\n- T greets the class.\n- T has Ss say the chant of Lesson 2 and revises shoes, shirts, shorts with flashcards.\n- T introduces Unit 15 – Lesson 3.","hs":"- Ss greet the teacher.\n- Ss chant and say the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’)","gv":"Activity 6: Listen and repeat\n* Aims: Pupils can understand and say the sentence pattern correctly.\n* Procedure:\n- T shows the pictures of Activity 6 and asks: “Who can you see? What can you see?”\n- T presents the sentence pattern on the board:\n+ Where are the shoes?: Đôi giày ở đâu?\n+ Over there.: Ở đằng kia.\n- T models the sentences; Ss repeat in chorus and individually (T uses backchaining for long sentences).\n- T plays the audio: Ss listen, point to the pictures and repeat.","hs":"- Ss look and answer.\n- Ss look at the board and listen.\n- Ss repeat in chorus and individually.\n- Ss listen, point and repeat."},{"ten":"3. Practice (10’)","gv":"Activity 7: Let's talk\n* Aims: Pupils can use the sentence pattern with the words of the unit.\n* Procedure:\n- T points to the pictures and elicits the sentences.\n- T models with a good pupil: T: “Where are the shirts?” – S points and says: “Over there.”\n- T organises T–Ss, open pairs, then closed pairs: one pupil asks “Where are the shoes / shirts / shorts?”, the other points to the picture and answers “Over there.”\n- (AI 2.A2) T opens a teacher-checked AI speaking tool on the class device (teacher's account; pupils use no accounts). A few pupils say “Where are the shoes?” – “Over there.” into the microphone; the class compares what the tool shows with the model. T explains that the tool can help check pronunciation, but the teacher gives the final feedback.\n- T invites some pairs to act out in front of the class and gives feedback.","hs":"- Ss look and say the sentences.\n- Ss listen and watch the model.\n- Ss practise in open pairs, then closed pairs.\n- A few Ss say the sentences to the class device; the class compares the result with the model and listens to T's feedback.\n- Some pairs act out; the class listens and claps."},{"ten":"4. Production (8’)","gv":"Activity 8: Let's sing\n* Aims: Pupils can sing the song of the unit with the correct rhythm and actions.\n* Procedure:\n- T shows the song picture and reads the lyrics (Pupil's Book) line by line.\n- T plays the song; Ss listen and follow in their books.\n- T plays it again; Ss sing along and do actions.\n- T has groups take turns to sing; the class claps and praises.\n- (Digital competence 4.2.CB1a) T shows a picture of a shopping app asking for “Name, Address, Phone number”; T asks: “Can you type it?” and reminds Ss never to give their name, address, phone number or payment information; they ask an adult.","hs":"- Ss look, listen and repeat the lyrics.\n- Ss listen and follow.\n- Ss sing along and do actions.\n- Ss sing in groups and praise their friends.\n- Ss answer “No!” and repeat: ask an adult."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the sentence pattern once more: “Where are the shoes?” – “Over there.”\n- T praises Ss and asks them to practise the sentences and the song at home.","hs":"- Ss say the sentences.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":32,"tiet":2,"bai":"Unit 16: At the campsite – Lesson 1 (Activities 1–2)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise and say the words: tent, teapot, blanket.\n- Recognise the letter T, t and say the sound /t/ in tent, teapot, blanket.\n2. Skills: Listening and speaking\n3. Attributes:\n- Take an active part in the lesson and cooperate with friends in pairs and groups.\n- Life skills: recognise some things needed for camping and keep them neat and in the right places.\n- Safety: do not go near barbecue grills, boiling water or fire without an adult.\n4. Digital Competence (AI 2.A1): Recognise that AI can support image recognition and pronunciation of English words: look at camping pictures, listen to a model-reading tool, identify tent, teapot, blanket and practise the initial /t/ sound in tent and teapot.","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 16), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a friendly atmosphere and revise the previous unit.\n* Procedure:\n- T greets the class and asks: “How are you today?”\n- T plays “Slap the board” with shoes, shirts, shorts (Unit 15).\n- T shows the Unit 16 opening picture and asks: “Where are they? What can you see?”\n- T introduces the new lesson: Unit 16: At the campsite – Lesson 1.","hs":"- Ss greet the teacher and answer.\n- Ss play the game in two teams.\n- Ss look at the picture and answer.\n- Ss listen and open their books."},{"ten":"2. Presentation (12’)","gv":"Activity 1: Listen and repeat\n* Aims: Pupils can recognise and say the words tent, teapot, blanket correctly.\n* Procedure:\n- T shows the flashcards/pictures one by one and elicits the new words:\n+ tent: cái lều (picture)\n+ teapot: cái ấm trà (picture)\n+ blanket: cái chăn (picture)\n- T models each word three times.\n- T has Ss repeat in chorus, in groups and individually.\n- (AI 2.A1) T plays a teacher-checked AI text-to-speech model of tent, teapot, blanket on the class device (teacher's account only) while showing the pictures; Ss listen, point to the correct picture and repeat; T asks: “Does it sound like the teacher's model?” and corrects where needed.\n- T plays the audio of Activity 1 twice: Ss listen, point to the pictures and repeat.\n- Checking: T plays “What and where” with the new words.","hs":"- Ss look at the pictures and guess the words.\n- Ss listen to the teacher.\n- Ss repeat in chorus, in groups and individually.\n- Ss listen to the AI model, point to the picture and repeat.\n- Ss listen, point and repeat.\n- Ss play the game and say the words."},{"ten":"3. Practice (10’)","gv":"Activity 2: Letter and sound – T, t /t/\n* Aims: Pupils can recognise T, t and say the sound /t/ correctly.\n* Procedure:\n- T writes T, t on the board and says /t/ several times, showing the mouth shape.\n- T plays the audio of Activity 2: Ss listen and repeat the letter(s), the sound and the words.\n- T underlines the letter t in tent, teapot, blanket and has Ss say the words again, stressing /t/.\n- T has Ss write T, t in the air and on their desks while saying the sound.\n- T plays “Listen and clap”: T says some familiar words; Ss clap when they hear /t/.\n- T corrects pronunciation where necessary.","hs":"- Ss look, listen and say /t/.\n- Ss listen and repeat.\n- Ss read the words, stressing the sound.\n- Ss write in the air and say the sound.\n- Ss listen and clap when they hear the sound.\n- Ss correct their pronunciation."},{"ten":"4. Production (6’)","gv":"Point and say – Guess the picture\n* Aims: Pupils can use the new words in pairs and in a game.\n* Procedure:\n- T puts Ss in pairs: one points to a picture in the Pupil's Book, the other says the word.\n- T plays “Guess the picture”: T slowly shows part of a flashcard; Ss guess the word.\n- T shows a camping picture with a fire and a teapot of hot water and asks: “Can you go near the fire alone?” T reminds Ss to stay away from fire and boiling water without an adult and to keep camping things neat.","hs":"- Ss work in pairs to point and say.\n- Ss guess and say the words.\n- Ss answer “No!” and point to the safe places in the picture."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “What words have you learnt today? What sound is it?”\n- T praises Ss and asks them to practise the words at home and prepare Lesson 2.","hs":"- Ss say the words and the sound.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":33,"tiet":1,"bai":"Unit 16: At the campsite – Lesson 2 (Activities 3–5)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Say the chant with the words tent, teapot, blanket and the sound /t/ correctly.\n- Understand the position words near, in and on in the pictures.\n- Listen and circle the correct pictures.\n- Look at the pictures and write the missing letters/words (Look and write).\n2. Skills: Listening and speaking; reading and writing (Look and write)\n3. Attributes:\n- Work hard and help friends to complete the tasks.\n- Environmental protection: keep the campsite clean, collect rubbish and do not damage trees, flowers or grass.\n4. Digital Competence (1.1.CB1a; 4.1.CB1a): Perform simple information-selection actions on digital learning resources under the teacher's guidance: listen and choose/circle the pictures matching tent, blanket, teapot and the positions near, in, on (1.1.CB1a); follow the rules for using digital devices safely: only touch/select as instructed and do not open other apps or links (4.1.CB1a).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 16), TV or projector, computer, digital version of the activities (teacher-controlled)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Lesson 1.\n* Procedure:\n- T greets the class.\n- T plays “Flashcard flash” with tent, teapot, blanket: T flashes a card quickly and Ss say the word.\n- T asks Ss to say the sound /t/ and the words again.\n- T introduces Unit 16 – Lesson 2.","hs":"- Ss greet the teacher.\n- Ss look and say the words.\n- Ss say the sound and the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 3: Listen and chant\n* Aims: Pupils can say the chant with the correct rhythm and pronunciation.\n* Procedure:\n- T revises the position words with a real bag and a pencil:\n+ near: ở gần\n+ in: ở trong\n+ on: ở trên\n- T shows the chant picture and asks Ss to find tent, teapot, blanket.\n- T plays the chant once; Ss listen and follow in their books.\n- T plays it again line by line; Ss repeat.\n- T has Ss chant and clap to the rhythm, first as a class, then in groups.\n- T invites some groups to perform; the class gives praise.","hs":"- Ss look, listen and repeat: near, in, on.\n- Ss look and point to the things in the picture.\n- Ss listen and follow.\n- Ss repeat line by line.\n- Ss chant and clap as a class and in groups.\n- Some groups perform; the others clap."},{"ten":"3. Practice (10’)","gv":"Activity 4: Listen and circle\n* Aims: Pupils can listen and circle the correct pictures.\n* Procedure:\n- T has Ss look at the pictures and say what they can see.\n- T explains the task and does the example with the class.\n- T plays the audio twice: Ss listen and circle the correct pictures.\n- T has Ss swap books and check their answers in pairs.\n- (Digital competence 4.1.CB1a) Before Ss come up to the class device, T reminds them: only touch or select what the teacher says; do not open other apps or links.\n- (Digital competence 1.1.CB1a) T shows Activity 4 on the screen; for each item, T invites a pupil to come up and circle the matching picture on the class device under the teacher's guidance; the class says “Yes” or “No”.\n- T checks the answers with the class (key in the Teacher's Book) and plays the audio again to confirm.","hs":"- Ss look and name the pictures.\n- Ss listen and follow the example.\n- Ss listen and circle.\n- Ss swap books and check in pairs.\n- Ss listen and follow the rules for using the device.\n- Ss take turns to circle the picture on the class device; the class checks.\n- Ss correct their answers."},{"ten":"4. Production (10’)","gv":"Activity 5: Look and write\n* Aims: Pupils can look at the pictures and write the missing letters/words.\n* Procedure:\n- T has Ss look at the pictures and say the words.\n- T models the first item on the board.\n- T asks Ss to do the task individually and goes around to help.\n- T invites some Ss to write the answers on the board; the class checks.\n- T has Ss read the completed words aloud.\n- (Digital competence 1.1.CB1a) T shows the Activity 5 pictures on the screen and, after Ss finish writing, clicks to show the missing letters/words one by one.\n- T shows a clean campsite and a campsite with rubbish and asks: “Which one is good?” T reminds Ss to collect their rubbish and not to damage trees, flowers or grass.","hs":"- Ss look and say the words.\n- Ss watch the example.\n- Ss write in their books.\n- Some Ss write on the board; the class checks.\n- Ss read the words aloud.\n- Ss look at the screen and check their own writing.\n- Ss choose the clean campsite and say what they can do to keep it clean."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the chant once more and name the words of the lesson.\n- T praises Ss and asks them to practise at home and prepare Lesson 3.","hs":"- Ss chant and say the words.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":33,"tiet":2,"bai":"Unit 16: At the campsite – Lesson 3 (Activities 6–8)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Ask and answer about position with “Is the blanket near the tent?” – “No, it isn't. It's in the tent.”, substituting table, teapot and tent.\n- Sing the song of Unit 16 with the correct rhythm and actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Speak confidently and listen to friends politely.\n- Camping safety: stay close to adults, do not leave the camping area alone and follow safety instructions.\n4. Digital Competence (AI 2.A2; 2.1.CB1a): Recognise that AI can support listening and speaking practice and give pronunciation feedback on simple English sentence patterns; under the teacher's guidance, pupils ask and answer “Is the blanket near the tent?” – “No, it isn't. It's in the tent.” and substitute table, teapot, tent (AI 2.A2); take part in a simple guided digital communication activity: listen to models, look at the pictures and choose suitable answers (2.1.CB1a).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Unit 16), TV or projector, computer, a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words and the chant of Lesson 2.\n* Procedure:\n- T greets the class.\n- T has Ss say the chant of Lesson 2 and revises tent, teapot, blanket with flashcards.\n- T introduces Unit 16 – Lesson 3.","hs":"- Ss greet the teacher.\n- Ss chant and say the words.\n- Ss listen and open their books."},{"ten":"2. Presentation (10’)","gv":"Activity 6: Listen and repeat\n* Aims: Pupils can understand and say the sentence pattern correctly.\n* Procedure:\n- T shows the pictures of Activity 6 and asks: “Who can you see? What can you see?”\n- T presents the sentence pattern on the board:\n+ Is the blanket near the tent?: Cái chăn có ở gần cái lều không?\n+ No, it isn't. It's in the tent.: Không. Nó ở trong lều.\n- T models the sentences; Ss repeat in chorus and individually (T uses backchaining for long sentences).\n- T plays the audio: Ss listen, point to the pictures and repeat.\n- (Digital competence 2.1.CB1a) T shows the pictures on the screen and plays the model questions; Ss look at the pictures and choose the suitable answer (“Yes, it is.” / “No, it isn't. It's in the tent.”).","hs":"- Ss look and answer.\n- Ss look at the board and listen.\n- Ss repeat in chorus and individually.\n- Ss listen, point and repeat.\n- Ss look at the pictures on the screen and choose the suitable answer."},{"ten":"3. Practice (10’)","gv":"Activity 7: Let's talk\n* Aims: Pupils can use the sentence pattern with the words of the unit.\n* Procedure:\n- T points to the pictures and elicits the sentences.\n- T models with a good pupil: T: “Is the teapot near the tent?” – S: “No, it isn't. It's on the table.”\n- T organises T–Ss, open pairs, then closed pairs: using the pictures, one pupil asks “Is the blanket / teapot near the tent?”, the other answers “Yes, it is.” or “No, it isn't. It's in / on / near the …”\n- (AI 2.A2) T opens a teacher-checked AI speaking tool on the class device (teacher's account; pupils use no accounts). A few pupils say “Is the blanket near the tent?” – “No, it isn't. It's in the tent.” into the microphone; the class compares what the tool shows with the model. T explains that the tool can help check pronunciation, but the teacher gives the final feedback.\n- T invites some pairs to act out in front of the class and gives feedback.","hs":"- Ss look and say the sentences.\n- Ss listen and watch the model.\n- Ss practise in open pairs, then closed pairs.\n- A few Ss say the sentences to the class device; the class compares the result with the model and listens to T's feedback.\n- Some pairs act out; the class listens and claps."},{"ten":"4. Production (8’)","gv":"Activity 8: Let's sing\n* Aims: Pupils can sing the song of the unit with the correct rhythm and actions.\n* Procedure:\n- T shows the song picture and reads the lyrics (Pupil's Book) line by line.\n- T plays the song; Ss listen and follow in their books.\n- T plays it again; Ss sing along and do actions.\n- T has groups take turns to sing; the class claps and praises.\n- T asks: “At the campsite, where do you stay?” T reminds Ss to stay close to adults, not to leave the camping area alone and to follow the safety instructions.","hs":"- Ss look, listen and repeat the lyrics.\n- Ss listen and follow.\n- Ss sing along and do actions.\n- Ss sing in groups and praise their friends.\n- Ss answer “Near my mum and dad!” and repeat the safety rules."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the sentence pattern once more: “Is the blanket near the tent?” – “No, it isn't. It's in the tent.”\n- T praises Ss and asks them to practise the sentences and the song at home.","hs":"- Ss say the sentences.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":34,"tiet":1,"bai":"Review 4 – Phil and Sue","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Listen to and understand the Phil and Sue story.\n- Revise the words of Units 13–16: eleven to twenty, sister, brother, grandmother, shoes, shirts, shorts, tent, teapot, blanket.\n- Revise the sounds /n/ (N, n), /ə/ (er), /ʃ/ (sh) and /t/ (T, t).\n- Revise the sentence patterns: “What number is it?” – “It's eleven.”; “How old is your brother?” – “He's nineteen.”; “Where are the shoes?” – “Over there.”; “Is the blanket near the tent?” – “No, it isn't. It's in the tent.”.\n2. Skills: Listening and speaking\n3. Attributes:\n- Be honest when saying what they have heard or read.\n- Listen to the story carefully and cooperate with friends.\n4. Digital Competence (AI 2.B1; 1.2.CB1a): Recognise that an AI-style answer/illustration may not match the story and check it against the pictures and the Pupil's Book (AI 2.B1); find simple information in the story/digital learning resource to confirm answers (1.2.CB1a).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Units 13–16), TV or projector, computer, digital version of the story (teacher-controlled), an AI-style picture prepared in advance\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words of Units 13–16.\n* Procedure:\n- T greets the class and plays “Slap the board” with eleven to twenty, sister, brother, grandmother, shoes, shirts, shorts, tent, teapot, blanket.\n- T introduces Review: Phil and Sue.","hs":"- Ss play the game in two teams.\n- Ss listen and open their books."},{"ten":"2. Presentation (7’)","gv":"Before the story\n* Aims: Pupils can predict the story from the pictures.\n* Procedure:\n- T shows the story pictures and asks: “Who can you see? Where are they?”\n- T asks Ss to find things they know from Units 13–16 in the pictures.\n- T revises the sounds /n/ (N, n), /ə/ (er), /ʃ/ (sh) and /t/ (T, t) with words from the story.","hs":"- Ss look and answer: “Phil and Sue.”\n- Ss point and say the words.\n- Ss repeat the sounds and words."},{"ten":"3. Practice (13’)","gv":"The Phil and Sue story\n* Aims: Pupils can listen to the story, understand it and act it out.\n* Procedure:\n- T plays the story audio once; Ss listen and point to the pictures.\n- T plays it again, stopping after each picture; Ss repeat the sentences.\n- (Digital competence 1.2.CB1a) T shows the story on the screen and asks simple questions about each picture using the words and sentence patterns of Units 13–16; Ss find the word or picture on the screen to confirm their answers.\n- T puts Ss in pairs to act out the story as Phil and Sue.\n- T invites some pairs to perform and praises them.","hs":"- Ss listen and point.\n- Ss listen and repeat.\n- Ss answer and point to the information on the screen to confirm.\n- Ss act out the story in pairs.\n- Some pairs perform; the class claps."},{"ten":"4. Production (8’)","gv":"Does it match the story?\n* Aims: Pupils can check an AI-style answer/picture against the story.\n* Procedure:\n- (AI 2.B1) T shows an AI-style picture/answer prepared in advance that does not fully match the story (for example, the wrong object or the wrong character).\n- T asks: “Is it the same as the story?” Ss compare it with the pictures in the Pupil's Book and say what is different.\n- T reminds Ss: AI pictures and answers can be wrong; we check with the book and tell the truth about what we hear and read.\n- T has Ss say the sentence patterns: “What number is it?” – “It's eleven.”; “How old is your brother?” – “He's nineteen.”; “Where are the shoes?” – “Over there.”; “Is the blanket near the tent?” – “No, it isn't. It's in the tent.”.","hs":"- Ss look at the picture on the screen.\n- Ss compare with the book and say what is different.\n- Ss listen and repeat the rule.\n- Ss say the sentences in chorus and in pairs."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks: “Do you like the story? What words can you remember?”\n- T praises Ss and asks them to revise Units 13–16 for the Self-check.","hs":"- Ss answer.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":34,"tiet":2,"bai":"Review 4 – Self – check – Part 1","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Listen and choose/tick the correct pictures with the words and sentences of Units 13–16.\n- Read and match words/sentences with pictures.\n- Revise the words: eleven to twenty, sister, brother, grandmother, shoes, shirts, shorts, tent, teapot, blanket.\n2. Skills: Listening and speaking; reading (read and match)\n3. Attributes:\n- Self-study: mark what they have done well and what needs more practice.\n- Work carefully and independently.\n4. Digital Competence (1.1.CB1a; AI 2.A2): Listen, choose and check answers on a digital learning resource under the teacher's guidance (1.1.CB1a); compare a simple AI suggestion with the answer based on the picture/audio and correct it if it is wrong (AI 2.A2).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Units 13–16), TV or projector, computer, digital version of the activities (teacher-controlled), a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the words before the Self-check.\n* Procedure:\n- T greets the class and has Ss sing a song from Units 13–16.\n- T plays “What and where” with some words from Units 13–16.\n- T explains the Self-check: we check what we can do.","hs":"- Ss sing together.\n- Ss play the game.\n- Ss listen and open their books."},{"ten":"2. Presentation (12’)","gv":"Self-check: Listen and tick/circle\n* Aims: Pupils can listen and choose the correct pictures.\n* Procedure:\n- T has Ss look at the pictures and name them.\n- T plays the audio twice; Ss listen and tick/circle in their books.\n- (Digital competence 1.1.CB1a) T shows the task on the screen; Ss take turns to choose the answer on the class device while T plays the audio again to check.\n- T checks the answers with the class (key in the Teacher's Book).","hs":"- Ss look and name the pictures.\n- Ss listen and tick/circle.\n- Ss choose the answer on the class device and check.\n- Ss correct their answers."},{"ten":"3. Practice (10’)","gv":"Self-check: Read and match\n* Aims: Pupils can read and match words/sentences with pictures.\n* Procedure:\n- T reads the words/sentences; Ss repeat.\n- T asks Ss to match individually, then check in pairs.\n- T invites some Ss to give the answers and read them aloud.","hs":"- Ss read after the teacher.\n- Ss match, then check with a partner.\n- Some Ss give and read the answers."},{"ten":"4. Production (6’)","gv":"Check the AI – My progress\n* Aims: Pupils can check an AI suggestion and assess their own progress.\n* Procedure:\n- (AI 2.A2) T shows a simple AI suggestion for one item, prepared in advance with one mistake; Ss compare it with the picture/audio and correct it.\n- T asks Ss to colour a smiley face next to each task: happy face = I can do it; sad face = I need more practice.\n- T notes the tasks that many Ss need to practise more.","hs":"- Ss compare the AI suggestion with the picture/audio and correct it.\n- Ss colour the faces for each task.\n- Ss tell the teacher which tasks are difficult."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T praises Ss for working carefully.\n- T asks Ss to practise the words they found difficult and prepare Self-check Part 2.","hs":"- Ss listen.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":35,"tiet":1,"bai":"Review 4 – Self – check – Part 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Look and write words/sentences from Units 13–16.\n- Use the sentence patterns in short talks: “What number is it?” – “It's eleven.”; “How old is your brother?” – “He's nineteen.”; “Where are the shoes?” – “Over there.”; “Is the blanket near the tent?” – “No, it isn't. It's in the tent.”.\n- Recognise what they need to practise more.\n2. Skills: Listening and speaking; reading and writing\n3. Attributes:\n- Honesty: complete the Self-check independently and do not copy.\n- Be responsible for their own learning.\n4. Digital Competence (5.2.CB1a; AI 2.B1): Choose suitable simple tools for revision (audio, digital flashcards, digital games provided by the teacher) (5.2.CB1a); do not copy AI answers: do the task themselves first, then use an AI example to check under the teacher's guidance (AI 2.B1).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Units 13–16), TV or projector, computer, digital flashcards and a simple digital game (teacher-controlled), a teacher-checked AI speaking/text-to-speech tool on the class computer (teacher's account only)\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To revise the sentence patterns.\n* Procedure:\n- T greets the class and asks some quick questions with “What number is it?” – “It's eleven.” / “How old is your brother?” – “He's nineteen.” / “Where are the shoes?” – “Over there.” / “Is the blanket near the tent?” – “No, it isn't. It's in the tent.”.\n- T introduces Self-check Part 2.","hs":"- Ss answer the questions.\n- Ss listen and open their books."},{"ten":"2. Presentation (12’)","gv":"Self-check: Look and write\n* Aims: Pupils can write the missing words/sentences on their own.\n* Procedure:\n- T has Ss look at the pictures and say the words.\n- T reminds Ss to do the task on their own first and not to copy.\n- T gives Ss time to write; T goes around to help.\n- T invites some Ss to write the answers on the board; the class checks.","hs":"- Ss look and say the words.\n- Ss listen.\n- Ss write on their own.\n- Some Ss write on the board; the class checks."},{"ten":"3. Practice (10’)","gv":"Self-check: Let's talk\n* Aims: Pupils can ask and answer with the sentence patterns.\n* Procedure:\n- T shows pictures and models the sentence patterns.\n- T puts Ss in pairs to ask and answer about the pictures.\n- T goes around, listens and notes common mistakes.\n- T invites some pairs to talk in front of the class.","hs":"- Ss listen and repeat.\n- Ss ask and answer in pairs.\n- Ss practise and correct mistakes.\n- Some pairs perform; the class claps."},{"ten":"4. Production (6’)","gv":"Check and choose a revision tool\n* Aims: Pupils can check their work and choose a suitable tool for more practice.\n* Procedure:\n- (AI 2.B1) After Ss have finished on their own, T shows an AI example answer on the screen; Ss use it only to check their work and correct mistakes.\n- (Digital competence 5.2.CB1a) T shows three revision tools: audio, digital flashcards and a digital game; each pupil chooses the one that suits the part they need to practise.\n- T lets a few Ss try their chosen tool on the class device.","hs":"- Ss check their own work with the example.\n- Ss choose a revision tool and say why (e.g. “flashcards – words”).\n- A few Ss try the tool on the class device."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T praises Ss for doing the Self-check honestly.\n- T asks Ss to practise with the tool they chose (with an adult at home).","hs":"- Ss listen.\n- Ss listen and remember the homework."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":2,"mon":"Tiếng Anh","tuan":35,"tiet":2,"bai":"Reserve period 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Consolidate the words, sounds and sentence patterns of Units 13–16 that pupils still find difficult.\n- Revise: “What number is it?” – “It's eleven.”; “How old is your brother?” – “He's nineteen.”; “Where are the shoes?” – “Over there.”; “Is the blanket near the tent?” – “No, it isn't. It's in the tent.”.\n2. Skills: Listening and speaking\n3. Attributes:\n- Take part actively and help friends who need more practice.\n- Flexible learning: the content is adjusted to the real situation of the class.\n4. Digital Competence (2.4.CB1a; AI 2.A1): Take part in a simple digital activity organised by the teacher (2.4.CB1a); recall that AI only supports learning and information must be checked before it is used (AI 2.A1).","dodung":"- Teacher: Teacher's Book, audio, flashcards/pictures (Units 13–16), TV or projector, computer, a simple class quiz on the screen\n- Pupils: Pupil's Book, notebooks, pencils","hoatdong":[{"ten":"1. Warm-up (5’)","gv":"* Aims: To create a fun atmosphere.\n* Procedure:\n- T greets the class and has Ss sing their favourite song of the year.\n- T tells Ss the aims of the period: practise what is still difficult.","hs":"- Ss sing together.\n- Ss listen."},{"ten":"2. Presentation (12’)","gv":"Words and sounds\n* Aims: Pupils can say the words and sounds they found difficult.\n* Procedure:\n- T reviews the words and sounds that many Ss found difficult in Review 4: /n/ (N, n), /ə/ (er), /ʃ/ (sh) and /t/ (T, t).\n- T plays “Slap the board” with eleven to twenty, sister, brother, grandmother, shoes, shirts, shorts, tent, teapot, blanket.\n- T gives extra practice (spelling, reading) to Ss who need it; stronger Ss help their friends.","hs":"- Ss listen and repeat.\n- Ss play in two teams.\n- Ss practise; stronger Ss help their friends."},{"ten":"3. Practice (8’)","gv":"Sentence patterns\n* Aims: Pupils can ask and answer with the sentence patterns.\n* Procedure:\n- T models the sentence patterns with pictures.\n- T puts Ss in pairs to ask and answer.\n- T invites some pairs to perform.","hs":"- Ss listen and repeat.\n- Ss ask and answer in pairs.\n- Some pairs perform."},{"ten":"4. Production (8’)","gv":"Class quiz on the screen\n* Aims: Pupils can use what they have learnt in a digital class game.\n* Procedure:\n- (AI 2.A1) Before the game, T shows one AI-made picture and asks: “Does it match the word?” T reminds Ss: AI only helps; we check the information first.\n- (Digital competence 2.4.CB1a) T runs a teacher-controlled class quiz on the screen; teams take turns to choose answers on the class device.\n- T praises the teams for playing fairly.","hs":"- Ss check the picture and answer.\n- Ss take turns to choose answers in their teams.\n- Ss cheer for their friends."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To end the school year positively.\n* Procedure:\n- T praises Ss for their progress this year.\n- T encourages Ss to sing English songs and review the words with their family in the summer.","hs":"- Ss listen.\n- Ss listen and remember."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"}
];
